    public static List<String> selectedRouteAssessmentLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("No route selected.");
        CampaignLocation current = currentCampaignLocation(ctx);
        CampaignLocation selected = selectedCampaignLocation(ctx);
        if (selected == null) return List.of("No route selected.");
        ensureGalaxyFleetPosition(st, current);
        GalaxyRouteAssessment assessment = analyzeRoute(st, ctx, st.playerGalaxyX, st.playerGalaxyY, selected);
        double displayRisk = assessment.interceptionRisk;
        if (st.galaxyTravel != null
                && st.galaxyTravel.traveling
                && selected.id.equals(st.galaxyTravel.destinationId)) {
            displayRisk = st.galaxyTravel.interceptionRisk;
        }
        ArrayList<String> out = new ArrayList<>();
        out.add("Travel Speed: " + routeTempoLabel(assessment));
        out.add("ETA: " + (int) Math.ceil(assessment.durationSec) + "s");
        out.add("Threat Exposure: " + routeExposureLabel(assessment) + "  Risk " + (int) Math.round(displayRisk) + "%");
        out.add(routeForecastLine(ctx, st, assessment));
        out.addAll(campaignTransitVariationLines(ctx));
        out.add(routeNotesLine(assessment));
        String sustainWarning = routeSustainabilityWarning(ctx, st, assessment);
        if (!sustainWarning.isBlank()) out.add("Route Warning: " + sustainWarning);
        String recovery = recoveryRouteSuggestionLine(ctx, st);
        if (!recovery.isBlank()) out.add(recovery);
        out.add(encounterDensityLine(ctx));
        out.add("Supply Cost: " + routeLogisticsLabel(assessment));
        out.add("Allied Support: " + routeSupportLabel(assessment));
        out.add("Nearby Opportunities: " + routeOpportunityLabel(assessment));
        out.add("Regional Danger: " + regionalPressureLabel(assessment.northPressure));
        out.add("Intel Confidence: " + campaignIntelReadout(ctx));
        out.addAll(routeForceWarningLines(ctx, st.playerGalaxyX, st.playerGalaxyY, selected.x, selected.y));
        return out;
    }

