    public static List<String> campaignStrategicAuthorityLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("Strategic map data unavailable.");
        synchronizeStrategicExpansionFromLive(st);
        int moving = 0;
        int hostile = 0;
        int friendly = 0;
        int visibleHostile = 0;
        int contestedNodes = 0;
        int activeBattles = 0;
        for (CampaignForce force : st.campaignForces) {
            if (force == null || force.destroyed) continue;
            if (force.intent != CampaignForceIntent.HOLDING || Math.hypot(force.targetX - force.x, force.targetY - force.y) > 1.0) {
                moving++;
            }
            if (force.faction == Faction.ENEMY) {
                hostile++;
                if (force.visibleToPlayer || force.contactConfidence > 0.0) visibleHostile++;
            } else {
                friendly++;
            }
        }
        for (StrategicNodeState node : st.strategicNodes) {
            if (node != null && node.owner == TheaterNodeOwner.CONTESTED) contestedNodes++;
        }
        for (CampaignBattle battle : st.campaignBattles) {
            if (battle != null && !battle.resolved) activeBattles++;
        }
        ArrayList<String> out = new ArrayList<>();
        out.add("REGION CONTROL  |  Sites " + st.strategicNodes.size()
                + "  Contested " + contestedNodes
                + "  Fronts " + st.campaignTheaters.size());
        out.add("FLEETS ON MAP  |  Friendly " + friendly
                + "  Hostile " + hostile
                + "  Moving " + moving
                + "  Tracked " + visibleHostile);
        out.add("ONGOING BATTLES  |  Battles " + activeBattles
                + "  Intervention reserve " + (int) Math.round(st.blueInterventionReserve) + "%");
        out.addAll(campaignObservedBattleReportLines(st, strategicDetectionRange(ctx, st)));
        out.add("OVERLAY  |  " + parseEnum(st.selectedStrategicOverlayId,
                StrategicCampaignExpansionSystem.MapOverlay.CONTROL));
        out.addAll(strategicOverlayInsightLines(ctx));
        out.addAll(campaignMapBookmarkLines(ctx));
        out.addAll(campaignRouteQueueLines(ctx));
        out.add("FACTION PLANS  |  " + st.redDirectorBrief + "  |  " + st.greenDirectorBrief + "  |  " + st.yellowDirectorBrief);
        if (!st.theaterWarRecentEvents.isEmpty()) {
            out.add("AFTERMATH  |  " + st.theaterWarRecentEvents.get(st.theaterWarRecentEvents.size() - 1));
        }
        return out;
    }

    public static List<String> campaignTerritoryAuthorityLines(GameContext ctx, int maxLines) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("TERRITORY AUTHORITY  |  unavailable");
        ArrayList<String> out = new ArrayList<>();
        out.add("TERRITORY AUTHORITY  |  owner / occupation / contest / garrison / supply");
        for (StrategicNodeState node : st.strategicNodes) {
            if (node == null) continue;
            CampaignLocation location = campaignLocationById(st, node.locationId);
            if (location == null) continue;
            int garrison = 0;
            for (CampaignForce force : st.campaignForces) {
                if (force == null || force.destroyed || force.kind != CampaignForceKind.BASE_DEFENSE) continue;
                if (force.faction != location.ownerFaction) continue;
                if (GameMath.dist2(force.x, force.y, location.x, location.y) <= theaterNodeRadius(node.type) * theaterNodeRadius(node.type)) {
                    garrison++;
                }
            }
            CampaignTheaterState theater = campaignTheaterById(st, node.theaterId);
            String supply = location.ownerFaction == Faction.ENEMY
                    ? "Red influence " + (int) Math.round(theater == null ? 0.0 : theater.redInfluence)
                    : "coalition supply " + (int) Math.round(theater == null ? 0.0 : theater.supplyState);
            out.add(location.name
                    + "  |  owner " + factionBoardName(location.ownerFaction)
                    + "  |  occupation " + node.owner
                    + "  |  capture " + (int) Math.round(node.contestProgress)
                    + "/100  |  garrison " + garrison + " required " + Math.max(1, location.strategicValue / 2)
                    + "  |  " + supply
                    + "  |  services " + location.stationServiceState
                    + "  |  missions " + String.join(",", location.missionTags));
            if (out.size() >= Math.max(2, maxLines)) break;
        }
        return out;
    }

    public static List<String> campaignBattleWarningLines(GameContext ctx, int maxLines) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("BATTLE WARNING  |  unavailable");
        ArrayList<String> out = new ArrayList<>();
        for (CampaignBattle battle : st.campaignBattles) {
            if (battle == null || battle.resolved) continue;
            double distance = Math.hypot(battle.x - st.playerGalaxyX, battle.y - st.playerGalaxyY);
            double eta = distance / Math.max(1.0, st.galaxyTravel.speed > 0.0 ? st.galaxyTravel.speed : 120.0);
            double friendly = 0.0;
            double hostile = 0.0;
            for (Integer forceId : battle.participantForceIds) {
                CampaignForce force = campaignForceById(st, forceId == null ? 0 : forceId);
                if (force == null) continue;
                if (force.faction == Faction.ENEMY) hostile += campaignFleetCombatPower(force);
                else friendly += campaignFleetCombatPower(force);
            }
            out.add("BATTLE #" + battle.id
                    + "  |  " + theaterForPoint(st, battle.y).label
                    + "  |  engagement warning " + (int) Math.ceil(CAMPAIGN_BATTLE_WARNING_LEAD_SEC) + "s"
                    + "  |  coalition " + (int) Math.round(friendly)
                    + " vs hostile " + (int) Math.round(hostile)
                    + "  |  distance " + (int) Math.round(distance)
                    + " ETA " + (int) Math.ceil(eta) + "s"
                    + "  |  Follow Fleet / Join Battle / Ignore / Offer Support"
                    + "  |  participants " + battle.participantManifest);
            if (out.size() >= Math.max(1, maxLines)) break;
        }
        if (out.isEmpty()) out.add("BATTLE WARNING  |  no active major battle");
        return out;
    }

    public static List<String> campaignStalemateOpportunityLines(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("STALEMATE  |  unavailable");
        ArrayList<String> out = new ArrayList<>();
        for (CampaignTheaterState theater : st.campaignTheaters) {
            if (!isProlongedStalemate(st, theater)) continue;
            out.add("STALEMATE  |  " + theater.id.name()
                    + "  |  no free fleets generated"
                    + "  |  Offer Ore / Credits / Intelligence / Ship"
                    + "  |  Major Offensive / Logistics Interdiction / Shipyard Defense or Sabotage"
                    + "  |  Ignore leaves control unresolved");
        }
        if (out.isEmpty()) out.add("STALEMATE  |  no prolonged front");
        return out;
    }

    private static boolean isProlongedStalemate(CampaignState st, CampaignTheaterState theater) {
        return st != null && theater != null
                && st.theaterWarTickIndex >= 12
                && theater.controlState == TheaterControlState.CONTESTED
                && Math.abs(theater.controlScore) < 18.0;
    }

    public static boolean resolveCampaignStalemateIntervention(GameContext ctx, String theaterId, String choice) {
        CampaignState st = state(ctx);
        TheaterId id = parseEnum(theaterId, TheaterId.FRONTIER);
        CampaignTheaterState theater = campaignTheaterById(st, id);
        if (ctx == null || st == null || !isProlongedStalemate(st, theater)) return false;
        String action = trimmedOrFallback(choice, "IGNORE").toUpperCase(Locale.US);
        String key = "stalemate:" + id + ":" + action + ":" + st.theaterWarTickIndex / 12;
        if (st.completedCampaignBoardMissionIds.contains(key)) return false;
        double delta = 0.0;
        switch (action) {
            case "ORE" -> {
                if (!spendCampaignOre(ctx, 40)) return false;
                delta = 10.0;
            }
            case "CREDITS" -> {
                if (ctx.credits < 600) return false;
                ctx.credits -= 600;
                delta = 8.0;
            }
            case "INTELLIGENCE", "INTEL" -> {
                if (st.campaignIntelLevel < 12.0) return false;
                st.campaignIntelLevel -= 12.0;
                delta = 9.0;
            }
            case "SHIP" -> {
                PersistentFleetEntry donor = st.persistentBlueFleet.stream()
                        .filter(entry -> entry != null && !entry.destroyed && !entry.role.isTitanOrMothership())
                        .findFirst().orElse(null);
                if (donor == null) return false;
                donor.destroyed = true;
                appendPersistentServiceHistory(donor, "TRANSFERRED TO " + id.label + " STALEMATE FRONT");
                delta = 15.0;
            }
            case "OFFENSIVE" -> delta = 18.0;
            case "INTERDICT", "LOGISTICS_INTERDICTION" -> {
                delta = 13.0;
                theater.supplyState = Math.min(100.0, theater.supplyState + 8.0);
                theater.routeRisk = Math.max(0.0, theater.routeRisk - 8.0);
            }
            case "SHIPYARD", "SHIPYARD_DEFENSE", "SABOTAGE" -> {
                delta = 12.0;
                theater.installationIntegrity = Math.min(100.0, theater.installationIntegrity + 12.0);
            }
            case "IGNORE" -> {
                pushTheaterEvent(st, id.label + " stalemate ignored; front remains unresolved");
                return true;
            }
            default -> {
                return false;
            }
        }
        theater.controlScore = MathUtil.clamp(theater.controlScore + delta, -100.0, 100.0);
        theater.greenInfluence = MathUtil.clamp(theater.greenInfluence + delta * 0.6, 0.0, 100.0);
        theater.redInfluence = MathUtil.clamp(theater.redInfluence - delta * 0.45, 0.0, 100.0);
        applyNormalizedInfluence(theater, theater.greenInfluence, theater.yellowInfluence, theater.redInfluence);
        theater.controlState = theaterControlStateForScore(theater.controlScore);
        st.completedCampaignBoardMissionIds.add(key);
        addCampaignMemoryFlag(st, "Blue intervention " + action + " shifted the " + id.label + " stalemate.");
        pushTheaterEvent(st, "STALEMATE INTERVENTION: " + action + " materially shifted " + id.label);
        return true;
    }

    public static String campaignDivergenceSignature(GameContext ctx) {
        CampaignState st = state(ctx);
        if (st == null) return "unavailable";
        String theater = st.campaignTheaters.stream()
                .filter(Objects::nonNull)
                .map(item -> item.id + ":" + (int) Math.round(item.controlScore)
                        + "/" + (int) Math.round(item.greenInfluence)
                        + "/" + (int) Math.round(item.yellowInfluence)
                        + "/" + (int) Math.round(item.redInfluence))
                .collect(Collectors.joining(","));
        return "seed=" + (ctx.config == null ? 0L : ctx.config.seed)
                + "|tick=" + st.theaterWarTickIndex
                + "|yellow=" + yellowAlignment(ctx)
                + "|directors=" + st.greenDirectorBrief + ";" + st.yellowDirectorBrief + ";" + st.redDirectorBrief
                + "|theaters=" + theater;
    }

    public static List<String> strategicOverlayInsightLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("Overlay Detail  |  unavailable");
        StrategicCampaignExpansionSystem.MapOverlay overlay = parseEnum(st.selectedStrategicOverlayId,
                StrategicCampaignExpansionSystem.MapOverlay.CONTROL);
        return switch (overlay) {
            case LOGISTICS -> List.of(logisticsOverlayInsightLine(ctx, st));
            case SENSORS -> List.of(sensorOverlayInsightLine(ctx, st));
            case CONTROL -> List.of(controlOverlayInsightLine(st));
            case DANGER -> List.of(dangerOverlayInsightLine(st));
            case TRADE -> List.of(tradeOverlayInsightLine(st));
            case HOSTILE_ROUTES -> List.of(hostileRoutesOverlayInsightLine(st));
            case FACILITIES -> List.of(facilitiesOverlayInsightLine(st));
            case MISSIONS -> List.of(missionsOverlayInsightLine(ctx, st));
            case FLEETS -> List.of(fleetsOverlayInsightLine(st));
            case ROUTES -> List.of(routesOverlayInsightLine(ctx));
            case INTEL -> List.of(intelOverlayInsightLine(st));
        };
    }

    private static List<String> campaignObservedBattleReportLines(CampaignState st, double detectionRange) {
        if (st == null || st.campaignBattles.isEmpty()) return List.of();
        ArrayList<CampaignBattle> remoteBattles = new ArrayList<>();
        for (CampaignBattle battle : st.campaignBattles) {
            if (battle == null || battle.resolved || battle.stage == CampaignBattleStage.RESOLVED) continue;
            if (battle.playerAwareness && isWithinStrategicDetectionRange(st, battle.x, battle.y, detectionRange)) continue;
            remoteBattles.add(battle);
        }
        if (remoteBattles.isEmpty()) return List.of();
        remoteBattles.sort(java.util.Comparator
                .comparingDouble((CampaignBattle battle) -> battle.importance)
                .reversed()
                .thenComparingInt(battle -> battle.id));
        ArrayList<String> out = new ArrayList<>();
        int limit = Math.min(3, remoteBattles.size());
        for (int i = 0; i < limit; i++) {
            CampaignBattle battle = remoteBattles.get(i);
            int range = (int) Math.round(Math.hypot(battle.x - st.playerGalaxyX, battle.y - st.playerGalaxyY));
            out.add("OBSERVED FROM AFAR  |  Fleet Clash #" + battle.id
                    + "  " + battle.stage.name().replace('_', ' ')
                    + "  |  range " + range
                    + "  |  delayed intel, no direct sensor lock");
        }
        return out;
    }

    private static String logisticsOverlayInsightLine(GameContext ctx, CampaignState st) {
        int serviceHubs = 0;
        int recoverySites = 0;
        for (CampaignLocation location : allCampaignLocations(st)) {
            if (location == null || !location.discovered) continue;
            if (!location.services.isEmpty()) serviceHubs++;
            if (location.type == CampaignLocationType.REPAIR_SITE || location.type == CampaignLocationType.SALVAGE_FIELD) recoverySites++;
        }
        return "Logistics Overlay  |  service hubs " + serviceHubs
                + "  recovery sites " + recoverySites
                + "  fuel " + campaignFuel(ctx)
                + "  supplies " + campaignSupplies(ctx);
    }

    private static String sensorOverlayInsightLine(GameContext ctx, CampaignState st) {
        int relays = st.sensorRelayNodes.size();
        int hidden = 0;
        for (CampaignLocation location : st.galaxyAreasOfInterest) {
            if (location != null && !location.discovered && !location.consumed) hidden++;
        }
        int uncertain = uncertainContactCount(st);
        return "Sensor Overlay  |  relays " + relays
                + "  uncertain contacts " + uncertain
                + "  hidden leads " + hidden
                + "  scan range " + sweepWindowReadout(ctx);
    }

    private static String controlOverlayInsightLine(CampaignState st) {
        int contested = 0;
        int blue = 0;
        int hostile = 0;
        for (StrategicNodeState node : st.strategicNodes) {
            if (node == null) continue;
            if (node.owner == TheaterNodeOwner.CONTESTED) contested++;
            if (node.owner == TheaterNodeOwner.BLUE_GREEN) blue++;
            if (node.owner == TheaterNodeOwner.RED) hostile++;
        }
        return "Control Overlay  |  coalition " + blue + "  hostile " + hostile + "  contested " + contested;
    }

    private static String dangerOverlayInsightLine(CampaignState st) {
        int activeBattles = 0;
        int recentScars = 0;
        for (CampaignBattle battle : st.campaignBattles) {
            if (battle != null && !battle.resolved) activeBattles++;
        }
        for (CampaignLocation location : allCampaignLocations(st)) {
            if (location != null && location.scarNote != null && !location.scarNote.isBlank()) recentScars++;
        }
        return "Danger Overlay  |  active battles " + activeBattles
                + "  recent battle scars " + recentScars
                + "  hostile groups " + contactPressureCount(st);
    }

    private static String tradeOverlayInsightLine(CampaignState st) {
        int convoyForces = 0;
        int tradeHubs = 0;
        int unstable = 0;
        for (CampaignForce force : st.campaignForces) {
            if (force == null || force.destroyed) continue;
            if (force.kind == CampaignForceKind.CONVOY
                    || force.kind == CampaignForceKind.TRADE_GROUP
                    || force.kind == CampaignForceKind.INSTALLATION_TRAFFIC) convoyForces++;
        }
        for (CampaignLocation location : allCampaignLocations(st)) {
            if (location == null || !location.discovered) continue;
            if (location.services.contains(HubService.TRADE) || location.services.contains(HubService.FUEL)) tradeHubs++;
            if (location.routeNote != null && location.routeNote.toLowerCase(Locale.US).contains("traffic")) unstable++;
        }
        return "Trade Overlay  |  convoy lanes " + convoyForces
                + "  trade/fuel hubs " + tradeHubs
                + "  shortages " + unstable;
    }

    private static String hostileRoutesOverlayInsightLine(CampaignState st) {
        int patrolRoutes = 0;
        int hostileRoutes = 0;
        int blockade = 0;
        for (CampaignForce force : st.campaignForces) {
            if (force == null || force.destroyed) continue;
            if (force.kind == CampaignForceKind.PATROL_GROUP || force.kind == CampaignForceKind.TASK_FORCE) patrolRoutes++;
            if (force.faction == Faction.ENEMY && (force.intent == CampaignForceIntent.INTERCEPTING
                    || force.intent == CampaignForceIntent.SEARCHING
                    || force.intent == CampaignForceIntent.GUARDING)) hostileRoutes++;
            if (isMovingBlockadeForce(force)) blockade++;
        }
        for (GalaxySearchGroup group : st.galaxySearchGroups) {
            if (group == null || !group.hostile) continue;
            if (group.doctrine == GalaxySearchDoctrine.BLOCKADE_GROUP) blockade++;
            if (group.visible || group.contactFadeSec > 0.0) hostileRoutes++;
        }
        return "Hostile Routes Overlay  |  patrol routes " + patrolRoutes
                + "  hostile shadows " + hostileRoutes
                + "  blockade lines " + blockade;
    }

    private static String facilitiesOverlayInsightLine(CampaignState st) {
        int major = 0;
        int minor = 0;
        int hidden = 0;
        int red = 0;
        for (CampaignLocation location : allCampaignLocations(st)) {
            if (location == null || location.destroyed) continue;
            if (!location.discovered) {
                hidden++;
                continue;
            }
            if (location.ownerFaction == Faction.ENEMY) red++;
            if (location.strategicValue >= 3 || location.primaryMission) major++;
            else minor++;
        }
        return "Facilities Filter  |  major " + major + "  minor " + minor + "  hidden " + hidden + "  Red-held " + red;
    }

    private static String missionsOverlayInsightLine(GameContext ctx, CampaignState st) {
        int green = campaignFactionMissionBoard(ctx, Faction.TEAM_C).size();
        int yellow = campaignFactionMissionBoard(ctx, Faction.TEAM_D).size();
        int urgent = 0;
        for (Faction faction : List.of(Faction.TEAM_C, Faction.TEAM_D)) {
            for (CampaignMissionBoardEntry entry : campaignFactionMissionBoard(ctx, faction)) {
                if (entry != null && "urgent".equalsIgnoreCase(entry.timePressure)) urgent++;
            }
        }
        return "Missions Filter  |  Green " + green + "  Yellow " + yellow
                + "  urgent " + urgent + "  expired " + st.expiredCampaignBoardMissionIds.size();
    }

    private static String fleetsOverlayInsightLine(CampaignState st) {
        int friendly = 0;
        int yellow = 0;
        int red = 0;
        int hidden = 0;
        for (CampaignForce force : st.campaignForces) {
            if (force == null || force.destroyed) continue;
            if (force.faction == Faction.ENEMY) red++;
            else if (force.faction == Faction.TEAM_D) yellow++;
            else friendly++;
            if (!campaignForceVisibleOnMap(force)) hidden++;
        }
        return "Fleets Filter  |  Green/Blue " + friendly + "  Yellow " + yellow + "  Red " + red + "  hidden/stale " + hidden;
    }

    private static String routesOverlayInsightLine(GameContext ctx) {
        List<CampaignRouteSegment> segments = campaignRouteSegments(ctx);
        int local = 0;
        int supply = 0;
        int contested = 0;
        int blockade = 0;
        int player = 0;
        for (CampaignRouteSegment segment : segments) {
            if (segment == null) continue;
            switch (segment.kind) {
                case LOCAL_ZONE -> local++;
                case SUPPLY_LINE -> supply++;
                case CONTESTED_LANE -> contested++;
                case BLOCKADE_LINE -> blockade++;
                case PLAYER_PLOTTED -> player++;
            }
        }
        return "Routes Filter  |  local " + local + "  supply " + supply
                + "  contested " + contested + "  blockade " + blockade + "  plotted " + player;
    }

    private static String intelOverlayInsightLine(CampaignState st) {
        int unknown = 0;
        int partial = 0;
        int good = 0;
        int full = 0;
        int stale = 0;
        for (CampaignLocation location : allCampaignLocations(st)) {
            if (location == null || location.destroyed) continue;
            if (location.intelStaleAtSec > 0.0) stale++;
            switch (location.intelLevel == null ? CampaignIntelLevel.UNKNOWN : location.intelLevel) {
                case UNKNOWN -> unknown++;
                case PARTIAL -> partial++;
                case GOOD -> good++;
                case FULL -> full++;
            }
        }
        return "Intel Filter  |  unknown " + unknown + "  partial " + partial
                + "  good " + good + "  full " + full + "  stale " + stale;
    }

    private static void synchronizeStrategicExpansionFromLive(CampaignState st) {
        if (st == null) return;
        StrategicCampaignExpansionSystem.State projection = st.strategicExpansion;
        if (projection == null) {
            projection = StrategicCampaignExpansionSystem.bootstrap(0L);
            st.strategicExpansion = projection;
        }
        projection.systems.clear();
        projection.lanes.clear();
        projection.installations.clear();
        projection.taskGroups.clear();
        for (CampaignLocation location : allCampaignLocations(st)) {
            if (location == null) continue;
            TheaterId theater = theaterForPoint(st, location.y);
            StrategicCampaignExpansionSystem.RegionRule rule = switch (theater) {
                case SOUTHERN -> StrategicCampaignExpansionSystem.RegionRule.SHELTERED;
                case FRONTIER -> StrategicCampaignExpansionSystem.RegionRule.CONTESTED_BELT;
                case LUNAR -> StrategicCampaignExpansionSystem.RegionRule.GRAVITY_WELL;
                case EARTH -> StrategicCampaignExpansionSystem.RegionRule.ORBITAL;
            };
            projection.systems.add(new StrategicCampaignExpansionSystem.StarSystem(
                    location.id, location.name, rule, location.discovered));
        }
        ArrayList<CampaignLocation> routeLocations = new ArrayList<>(st.galaxyMainPois);
        for (int i = 1; i < routeLocations.size(); i++) {
            CampaignLocation from = routeLocations.get(i - 1);
            CampaignLocation to = routeLocations.get(i);
            if (from == null || to == null) continue;
            StrategicCampaignExpansionSystem.LaneType type = to.discovered
                    ? StrategicCampaignExpansionSystem.LaneType.TRAVEL_LANE
                    : StrategicCampaignExpansionSystem.LaneType.HIDDEN_ROUTE;
            projection.lanes.add(new StrategicCampaignExpansionSystem.TravelLane(
                    from.id, to.id, type, from.discovered && to.discovered));
        }
        for (StrategicNodeState node : st.strategicNodes) {
            if (node == null) continue;
            StrategicCampaignExpansionSystem.InstallationType type = switch (node.type) {
                case SHIPYARD -> StrategicCampaignExpansionSystem.InstallationType.ORBITAL_PLATFORM;
                case LOGISTICS_HUB -> StrategicCampaignExpansionSystem.InstallationType.HUB;
                case DEFENSE_ANCHOR -> StrategicCampaignExpansionSystem.InstallationType.FORWARD_BASE;
                case RESOURCE_FIELD -> StrategicCampaignExpansionSystem.InstallationType.RESOURCE_BELT;
                case RELAY -> StrategicCampaignExpansionSystem.InstallationType.POPULATION_CENTER;
            };
            projection.installations.add(new StrategicCampaignExpansionSystem.Installation(
                    node.locationId, type, node.locationId, node.owner.name()));
        }
        for (CampaignForce force : st.campaignForces) {
            if (force == null || force.destroyed) continue;
            StrategicCampaignExpansionSystem.TaskGroup group =
                    new StrategicCampaignExpansionSystem.TaskGroup("live-force-" + force.id, force.name);
            group.delegatedCaptain = force.kind == CampaignForceKind.PLAYER_FLEET ? "Blue Command" : force.faction.name();
            group.route = campaignForceIntentLabel(force.intent) + "  |  " + theaterForPoint(st, force.y).label;
            group.etaHours = (int) Math.ceil(Math.hypot(force.targetX - force.x, force.targetY - force.y) / Math.max(1.0, force.speed));
            group.riskPercent = (int) Math.round(MathUtil.clamp(100.0 - force.readiness, 0.0, 100.0));
            projection.taskGroups.add(group);
        }
        double sum = 0.0;
        for (CampaignTheaterState theater : st.campaignTheaters) if (theater != null) sum += theater.controlScore;
        projection.frontLinePosition = MathUtil.clamp((int) Math.round(50.0 + sum / Math.max(1, st.campaignTheaters.size()) * 0.5), 0, 100);
    }

    public static boolean cycleStrategicMapOverlay(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return false;
        StrategicCampaignExpansionSystem.MapOverlay current = parseEnum(st.selectedStrategicOverlayId,
                StrategicCampaignExpansionSystem.MapOverlay.CONTROL);
        StrategicCampaignExpansionSystem.MapOverlay[] values = StrategicCampaignExpansionSystem.MapOverlay.values();
        st.selectedStrategicOverlayId = values[(current.ordinal() + 1) % values.length].name();
        EventSystem.showBanner(ctx, "STRATEGIC OVERLAY: " + st.selectedStrategicOverlayId, 1.2);
        return true;
    }

    public static boolean cycleCampaignTaskGroup(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return false;
        ArrayList<CampaignForce> friendly = new ArrayList<>();
        for (CampaignForce force : st.campaignForces) {
            if (force != null && !force.destroyed && force.faction != Faction.ENEMY) friendly.add(force);
        }
        if (friendly.isEmpty()) return false;
        int index = -1;
        for (int i = 0; i < friendly.size(); i++) if (friendly.get(i).id == st.selectedCampaignTaskGroupId) index = i;
        CampaignForce selected = friendly.get((index + 1) % friendly.size());
        st.selectedCampaignTaskGroupId = selected.id;
        EventSystem.showBanner(ctx, "TASK GROUP: " + selected.name, 1.2);
        return true;
    }

    public static boolean cycleSelectedCampaignTaskGroupOrder(GameContext ctx) {
        CampaignState st = state(ctx);
        CampaignForce force = (st == null) ? null : campaignForceById(st, st.selectedCampaignTaskGroupId);
        if (ctx == null || st == null || force == null || force.destroyed || force.faction == Faction.ENEMY) return false;
        CampaignForceIntent[] orders = {
                CampaignForceIntent.HOLDING,
                CampaignForceIntent.PATROLLING,
                CampaignForceIntent.ESCORTING,
                CampaignForceIntent.REINFORCING,
                CampaignForceIntent.REPAIRING
        };
        int index = 0;
        for (int i = 0; i < orders.length; i++) if (orders[i] == force.intent) index = i;
        force.intent = orders[(index + 1) % orders.length];
        force.intentTimerSec = Math.max(force.intentTimerSec, 12.0);
        pushTheaterEvent(st, "Blue delegated " + force.name + " to " + campaignForceIntentLabel(force.intent));
        EventSystem.showBanner(ctx, "TASK ORDER: " + campaignForceIntentLabel(force.intent), 1.2);
        return true;
    }

    public static boolean beginFollowingCampaignForce(GameContext ctx, int forceId) {
        CampaignState st = state(ctx);
        CampaignForce force = campaignForceById(st, forceId);
        if (ctx == null || st == null || force == null || force.destroyed || force.faction == Faction.ENEMY) return false;
        if (force.faction == Faction.TEAM_D && !isYellowForceFriendlyToBlue(st, force)) return false;
        st.selectedCampaignTaskGroupId = force.id;
        st.campaignMemoryFlags.removeIf(flag -> flag != null && flag.startsWith("FOLLOWING_FORCE:"));
        st.campaignMemoryFlags.add("FOLLOWING_FORCE:" + force.id);
        selectCampaignFreeTravelTarget(ctx, force.x, force.y);
        if (!st.galaxyTravel.traveling) startTravelToSelectedLocation(ctx);
        EventSystem.showBanner(ctx, "FOLLOWING FLEET: " + force.name, 1.4);
        return true;
    }

    public static boolean stopFollowingCampaignForce(GameContext ctx) {
        CampaignState st = state(ctx);
        if (st == null) return false;
        boolean removed = st.campaignMemoryFlags.removeIf(flag -> flag != null && flag.startsWith("FOLLOWING_FORCE:"));
        if (removed) EventSystem.showBanner(ctx, "FLEET FOLLOW RELEASED", 1.0);
        return removed;
    }

    public static List<String> campaignFollowedFleetLines(GameContext ctx) {
        CampaignState st = state(ctx);
        if (st == null) return List.of("FOLLOW FLEET  |  unavailable");
        int id = followedCampaignForceId(st);
        CampaignForce force = campaignForceById(st, id);
        if (force == null || force.destroyed) return List.of("FOLLOW FLEET  |  none");
        double distance = Math.hypot(force.x - st.playerGalaxyX, force.y - st.playerGalaxyY);
        double eta = distance / Math.max(1.0, st.galaxyTravel.speed > 0.0 ? st.galaxyTravel.speed : 120.0);
        return List.of("FOLLOW FLEET  |  " + force.name
                + "  |  " + factionBoardName(force.faction)
                + "  |  " + campaignForceIntentLabel(force.intent)
                + "  |  distance " + (int) Math.round(distance)
                + "  |  ETA " + (int) Math.ceil(eta) + "s"
                + "  |  destination " + trimmedOrFallback(force.destinationLocationId, "moving contact"));
    }

    private static int followedCampaignForceId(CampaignState st) {
        if (st == null) return 0;
        for (String flag : st.campaignMemoryFlags) {
            if (flag == null || !flag.startsWith("FOLLOWING_FORCE:")) continue;
            return Math.max(0, parseInt(flag.substring("FOLLOWING_FORCE:".length()), 0));
        }
        return 0;
    }

    private static void updateFollowedCampaignForce(GameContext ctx, CampaignState st) {
        int id = followedCampaignForceId(st);
        if (ctx == null || st == null || id <= 0) return;
        CampaignForce force = campaignForceById(st, id);
        if (force == null || force.destroyed || force.intent == CampaignForceIntent.RETREATING) {
            st.campaignMemoryFlags.removeIf(flag -> flag != null && flag.startsWith("FOLLOWING_FORCE:"));
            pushTheaterEvent(st, "FOLLOW ENDED: allied fleet was destroyed or withdrew");
            return;
        }
        st.selectedCampaignTaskGroupId = force.id;
        st.selectedFreeGalaxyTargetX = force.x;
        st.selectedFreeGalaxyTargetY = force.y;
        if (st.galaxyTravel.traveling && st.galaxyTravel.freeTravel) {
            st.galaxyTravel.targetX = force.x;
            st.galaxyTravel.targetY = force.y;
            st.galaxyTravel.destinationLabel = force.name;
        }
    }

    public static List<String> sectionFourHullFlowLines() {
        ArrayList<String> out = new ArrayList<>();
        for (ShipRole role : ShipRole.values()) {
            FleetBuildingSystem.HullProfile hull = FleetBuildingSystem.hullProfile(role);
            String shipyard = (role == ShipRole.BASE || role == ShipRole.STATIC_TURRET || role == ShipRole.MOTHERSHIP
                    || role == ShipRole.FIGHTER || role == ShipRole.BOMBER || role == ShipRole.PD_CRAFT || role == ShipRole.DRONE)
                    ? "ENCOUNTER"
                    : "SHIPYARD+ENCOUNTER";
            out.add(role + "  |  " + shipyard + "  |  " + hull.family
                    + "  |  " + hull.factionVariant);
        }
        return out;
    }

