        st.retreatCorridorY = GameMath.clamp(corridorY, CAMPAIGN_POCKET_MARGIN, ctx.WORLD_H - CAMPAIGN_POCKET_MARGIN);
        st.retreatCorridorRadius = Math.max(150.0, corridorRadius);
        st.retreatCorridorProgressSec = 0.0;
