    public static List<String> tacticalDeploymentPreviewLines(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || ctx.command == null) return List.of("Deployment Preview: unavailable");
        GameContext.FleetFormation formation = ctx.command.alliedFleetFormation == null
                ? GameContext.FleetFormation.WEDGE
                : ctx.command.alliedFleetFormation;
        int commit = 0;
        int reserve = 0;
        int hold = 0;
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed) continue;
            FleetCommitment commitment = resolveFleetCommitment(entry.tacticalCommitmentId);
            if (commitment == FleetCommitment.COMMIT) commit++;
            else if (commitment == FleetCommitment.RESERVE) reserve++;
            else if (commitment == FleetCommitment.HOLD_BACK) hold++;
        }
        ArrayList<String> out = new ArrayList<>();
        out.add("Pre-Battle Formation: " + formation.name()
                + "  |  " + preBattleFormationEffect(formation));
        out.add("Deployment Preview: Flagship left entry  |  committed " + commit
                + "  reserve " + reserve
                + "  hold " + hold);
        out.add("Deployment Zones: allies left lane  |  maneuver center  |  hostiles right lane");
        CampaignObjectiveMarker escort = missionEscortObjectiveMarker(ctx);
        if (escort != null) {
            out.add("Objective Preview: " + escort.label + "  |  " + escort.subtitle);
        }
        return out;
    }

    private static String preBattleFormationEffect(GameContext.FleetFormation formation) {
        return switch (formation == null ? GameContext.FleetFormation.WEDGE : formation) {
            case WEDGE -> "balanced screen and advance";
            case LINE -> "broadside control, slower turns";
            case ASSAULT -> "tight strike push, higher exposure";
            case SCREEN -> "escort coverage and missile defense";
        };
    }

    public static List<String> campaignFleetRosterLines(GameContext ctx, int maxCount) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null || maxCount <= 0) return List.of();
        ArrayList<String> out = new ArrayList<>();
        ArrayList<PersistentFleetEntry> live = orderedLivePersistentFleetEntries(st);
        for (PersistentFleetEntry entry : live) {
            String role = roleDisplayName(entry.role).toUpperCase(Locale.US);
            String group = (entry.commandGroupId == CAMPAIGN_FLAGSHIP_COMMAND_GROUP)
                    ? "FLAG"
                    : ("DET " + entry.commandGroupId);
            String commitment = fleetCommitmentLabel(resolveFleetCommitment(entry.tacticalCommitmentId));
            String hull = String.valueOf((int) Math.round(MathUtil.clamp(entry.hullConditionFrac, 0.0, 1.0) * 100.0));
            String armor = String.valueOf((int) Math.round(MathUtil.clamp(entry.armorConditionFrac, 0.0, 1.0) * 100.0));
            String shield = String.valueOf((int) Math.round(MathUtil.clamp(entry.shieldConditionFrac, 0.0, 1.0) * 100.0));
            out.add(displayPersistentFleetEntryName(entry) + "  |  " + role
                    + "  |  Combat Condition H " + hull + "  A " + armor + "  S " + shield
                    + "  |  Repair Need " + repairStateLabel(entry)
                    + "  |  " + campaignCargoLabelForPersistentEntry(entry)
                    + "  |  " + campaignForceLabelForPersistentEntry(st, entry)
                    + "  |  " + group + "  |  " + commitment);
            if (out.size() >= maxCount) break;
        }
        return out;
    }

    public static List<String> campaignFleetArchiveLines(GameContext ctx, int maxCount) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null || maxCount <= 0) return List.of();
        ArrayList<String> out = new ArrayList<>();
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null) continue;
            String prefix = entry.destroyed ? "MEMORIAL" : "SERVICE";
            out.add(prefix + "  |  " + displayPersistentFleetEntryName(entry)
                    + "  |  K " + Math.max(0, entry.kills)
                    + " R " + Math.max(0, entry.rescues)
                    + " SCARS " + Math.max(0, entry.scars)
                    + "  |  " + persistentFleetPersonnelLabel(entry));
            if (out.size() >= maxCount) break;
        }
        return out;
    }

    public static List<String> campaignFleetServiceRecordLines(GameContext ctx, int maxCount) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null || maxCount <= 0) return List.of();
        ArrayList<String> out = new ArrayList<>();
        ArrayList<PersistentFleetEntry> fleet = new ArrayList<>(st.persistentBlueFleet);
        fleet.sort((a, b) -> {
            if (a == null && b == null) return 0;
            if (a == null) return 1;
            if (b == null) return -1;
            if (a.destroyed != b.destroyed) return Boolean.compare(a.destroyed, b.destroyed);
            int action = Integer.compare(
                    Math.max(0, b.kills) + Math.max(0, b.rescues) + Math.max(0, b.retreats) + Math.max(0, b.scars),
                    Math.max(0, a.kills) + Math.max(0, a.rescues) + Math.max(0, a.retreats) + Math.max(0, a.scars));
            if (action != 0) return action;
            return Integer.compare(a.slotId, b.slotId);
        });
        for (PersistentFleetEntry entry : fleet) {
            if (entry == null) continue;
            String status = entry.destroyed ? "LOST" : repairStateLabel(entry);
            String role = roleDisplayName(entry.role).toUpperCase(Locale.US);
            String history = (entry.serviceHistory == null || entry.serviceHistory.isBlank())
                    ? "No major service events recorded"
                    : entry.serviceHistory.trim();
            out.add(displayPersistentFleetEntryName(entry) + "  |  " + role
                    + "  |  " + persistentFleetPersonnelLabel(entry)
                    + "  |  STATUS " + status
                    + "  |  KILLS " + Math.max(0, entry.kills)
                    + " RESCUES " + Math.max(0, entry.rescues)
                    + " RETREATS " + Math.max(0, entry.retreats)
                    + " SCARS " + Math.max(0, entry.scars)
                    + "  |  EVENTS " + history);
            if (out.size() >= maxCount) break;
        }
        return out;
    }

    private static String repairStateLabel(PersistentFleetEntry entry) {
        if (entry == null) return "UNKNOWN";
        int hull = (int) Math.round(MathUtil.clamp(entry.hullConditionFrac, 0.0, 1.0) * 100.0);
        int shield = (int) Math.round(MathUtil.clamp(entry.shieldConditionFrac, 0.0, 1.0) * 100.0);
        String state;
        if (hull < 45 || shield < 35) {
            state = "CRITICAL REPAIR";
        } else if (hull < 72 || shield < 58) {
            state = "REPAIRS NEEDED";
        } else if (hull >= 92 && shield >= 88) {
            state = "BATTLE READY";
        } else {
            state = "OPERATIONAL";
        }
        return state + " H" + hull + " S" + shield;
    }

    private static ArrayList<PersistentFleetEntry> orderedLivePersistentFleetEntries(CampaignState st) {
        ArrayList<PersistentFleetEntry> live = new ArrayList<>();
        if (st == null) return live;
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed) continue;
            live.add(entry);
        }
        live.sort((a, b) -> {
            int cost = Integer.compare(
                    campaignOreCost(b.role, shipyardOfferCreditCost(b.role), campaignRequiredTier(b.role, 1)),
                    campaignOreCost(a.role, shipyardOfferCreditCost(a.role), campaignRequiredTier(a.role, 1)));
            if (cost != 0) return cost;
            return Integer.compare(a.slotId, b.slotId);
        });
        return live;
    }

    public static List<CampaignFleetRosterEntry> campaignFleetRosterEntries(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of();
        ArrayList<PersistentFleetEntry> live = orderedLivePersistentFleetEntries(st);
        if (ctx.ui != null && !live.isEmpty()) {
            boolean hasFocus = false;
            for (PersistentFleetEntry entry : live) {
                if (entry.slotId == ctx.ui.campaignFleetFocusSlotId) {
                    hasFocus = true;
                    break;
                }
            }
            if (!hasFocus) ctx.ui.campaignFleetFocusSlotId = live.get(0).slotId;
            ctx.ui.campaignFleetRosterScroll = MathUtil.clamp(ctx.ui.campaignFleetRosterScroll, 0, Math.max(0, live.size() - 1));
        }
        ArrayList<CampaignFleetRosterEntry> out = new ArrayList<>();
        int selectedSlot = (ctx.ui == null) ? -1 : ctx.ui.campaignFleetFocusSlotId;
        for (PersistentFleetEntry entry : live) {
            out.add(new CampaignFleetRosterEntry(st, entry, entry.slotId == selectedSlot));
        }
        return out;
    }

    public static boolean selectCampaignFleetRosterSlot(GameContext ctx, int slotId) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || ctx.ui == null || slotId <= 0) return false;
        PersistentFleetEntry entry = persistentFleetEntryBySlotId(st, slotId);
        if (entry == null || entry.destroyed) return false;
        ctx.ui.campaignFleetFocusSlotId = entry.slotId;
        EventSystem.showBanner(ctx, "FLEET FOCUS: " + displayPersistentFleetEntryName(entry).toUpperCase(Locale.US), 0.9);
        return true;
    }

    public static boolean scrollCampaignFleetRoster(GameContext ctx, int wheelRotation, int visibleRows) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || ctx.ui == null || wheelRotation == 0) return false;
        int maxScroll = Math.max(0, orderedLivePersistentFleetEntries(st).size() - Math.max(1, visibleRows));
        int next = MathUtil.clamp(ctx.ui.campaignFleetRosterScroll + wheelRotation, 0, maxScroll);
        if (next == ctx.ui.campaignFleetRosterScroll && maxScroll > 0) return true;
        ctx.ui.campaignFleetRosterScroll = next;
        return true;
    }

    public static boolean openFocusedCampaignFleetEditor(GameContext ctx) {
        CampaignState st = state(ctx);
        PersistentFleetEntry entry = campaignFleetFocusEntry(ctx);
        if (ctx == null || st == null || ctx.ui == null || entry == null) return false;
        Ship live = findShipById(ctx, entry.activeShipId);
        if ((live == null || !live.alive || live.dying || live.hp <= 0) && !entry.destroyed) {
            live = materializePersistentFleetEntryForRefit(ctx, st, entry);
        }
        if (live == null || !live.alive || live.dying || live.hp <= 0) {
            EventSystem.showBanner(ctx, "REFIT UNAVAILABLE: " + displayPersistentFleetEntryName(entry).toUpperCase(Locale.US), 1.2);
            return true;
        }
        ctx.ui.shopOpen = true;
        ctx.ui.fleetRefitMode = true;
        ctx.ui.fleetSelectedShipId = live.id;
        ctx.ui.fleetSelectedTurretIndex = 0;
        ctx.lockedTarget = live;
        EventSystem.showBanner(ctx, "REFIT OPEN: " + displayPersistentFleetEntryName(entry).toUpperCase(Locale.US), 1.1);
        return true;
    }

    private static Ship materializePersistentFleetEntryForRefit(GameContext ctx, CampaignState st, PersistentFleetEntry entry) {
        if (ctx == null || st == null || entry == null || entry.destroyed || ctx.ships == null) return null;
        double x = (ctx.player == null) ? ctx.WORLD_W * 0.5 : ctx.player.x + 160.0 + (entry.slotId % 5) * 34.0;
        double y = (ctx.player == null) ? ctx.WORLD_H * 0.5 : ctx.player.y + 90.0 + (entry.slotId % 3) * 28.0;
        double angle = (ctx.player == null) ? 0.0 : ctx.player.angle;
        double vx = (ctx.player == null) ? 0.0 : ctx.player.vx;
        double vy = (ctx.player == null) ? 0.0 : ctx.player.vy;
        return spawnPersistentBlueShipAtPose(ctx, entry, x, y, angle, vx, vy);
    }

    public static List<String> campaignFleetConditionLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("Condition board offline.");
        int battleReady = 0;
        int escortReady = 0;
        int miningReady = 0;
        int repairQueue = 0;
        int heldBack = 0;
        int reserve = 0;
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed) continue;
            double hull = MathUtil.clamp(entry.hullConditionFrac, 0.0, 1.0);
            double shield = MathUtil.clamp(entry.shieldConditionFrac, 0.0, 1.0);
            boolean carrier = entry.role == ShipRole.CARRIER || entry.role == ShipRole.DRONE_CARRIER || entry.role == ShipRole.CARRIER_SUPPORT_TITAN;
            boolean logistics = entry.role == ShipRole.HAULER || entry.role == ShipRole.MINER
                    || entry.role == ShipRole.TRANSPORT || entry.role == ShipRole.TRANSPORT_TITAN
                    || entry.role == ShipRole.MOBILE_STATION_TITAN;
            FleetCommitment commitment = resolveFleetCommitment(entry.tacticalCommitmentId);
            if (commitment == FleetCommitment.HOLD_BACK) heldBack++;
            if (commitment == FleetCommitment.RESERVE) reserve++;
            if (hull < 0.64 || shield < 0.56) repairQueue++;
            if (hull >= 0.84 && shield >= 0.76 && !logistics) battleReady++;
            if (hull >= 0.76 && shield >= 0.68 && !carrier) escortReady++;
            if (logistics && hull >= 0.72) miningReady++;
        }
        return List.of(
                "BATTLE READY " + battleReady,
                "ESCORT READY " + escortReady,
                "MINING READY " + miningReady,
                "REPAIR QUEUE " + repairQueue,
                "HELD BACK " + heldBack + "  |  RESERVE " + reserve,
                "FLEET STRAIN " + campaignFleetStrainReadout(ctx)
        );
    }

    public static List<String> campaignDifficultyTelemetryLines(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("Difficulty telemetry unavailable.");
        int losses = 0;
        int retreats = 0;
        int battles = st.campaignAfterActionReports.size();
        for (AfterActionReport report : st.campaignAfterActionReports) {
            if (report == null) continue;
            String text = (report.result + " " + report.losses + " " + report.resources).toLowerCase(Locale.US);
            if (text.contains("defeat") || text.contains("failed") || text.contains("destroyed")) losses++;
            if (text.contains("retreat") || text.contains("withdraw")) retreats++;
        }
        int emergencies = 0;
        if (campaignFuel(ctx) < 16) emergencies++;
        if (campaignSupplies(ctx) < 12) emergencies++;
        if (campaignAmmo(ctx) < 14) emergencies++;
        String preset = ctx.experience == null ? "STANDARD" : ctx.experience.preset.name();
        ArrayList<String> out = new ArrayList<>();
        out.add("Difficulty " + preset + "  |  battles/reports " + battles
                + "  major losses " + losses + "  retreats " + retreats + "  resource emergencies " + emergencies);
        out.add("Standard target: roughly one major loss, failure, or forced withdrawal per five battles, with hub recovery.");
        out.add("Collapse rule: one ordinary mistake remains recoverable; repeated losses plus unresolved shortages can end the campaign.");
        if (ctx.experience != null) out.addAll(ctx.experience.modifierSummaryLines());
        return out;
    }

    public static List<String> campaignDoctrineAuditLines(GameContext ctx) {
        GameContext.FleetFormation selected = ctx == null || ctx.command == null || ctx.command.alliedFleetFormation == null
                ? GameContext.FleetFormation.WEDGE : ctx.command.alliedFleetFormation;
        return List.of(
                "WEDGE: fast concentration and attack lead; vulnerable to enveloping fire.",
                "LINE: broad lateral spacing, overlapping fields of fire, and shallow reinforcement rows; slower to turn.",
                "SCREEN: circular protection for capitals, carriers, and transports; weaker forward concentration.",
                "ASSAULT: role-layered spearhead with escorts forward and support aft; highest commitment risk.",
                "Selected: " + selected + "  |  no formation changes raw hull health or creates free ships.",
                "Workload: one formation choice applies to the fleet; individual micromanagement remains optional."
        );
    }

    public static List<String> campaignDifficultyModifierLines(GameContext ctx) {
        if (ctx == null || ctx.experience == null) return List.of("Difficulty modifiers unavailable.");
        return ctx.experience.modifierSummaryLines();
    }

    public static List<String> campaignFleetDetachmentLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("No detachment data.");
        java.util.LinkedHashMap<Integer, Integer> groups = new java.util.LinkedHashMap<>();
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed) continue;
            groups.merge(entry.commandGroupId, 1, Integer::sum);
        }
        ArrayList<String> out = new ArrayList<>();
        for (java.util.Map.Entry<Integer, Integer> entry : groups.entrySet()) {
            int groupId = entry.getKey();
            int count = entry.getValue();
            String label = (groupId == CAMPAIGN_FLAGSHIP_COMMAND_GROUP) ? "FLAG GROUP" : ("DETACHMENT " + groupId);
            out.add(label + "  |  " + count + " HULLS");
            if (out.size() >= 4) break;
        }
        return out;
    }

    public static List<String> campaignResourceManagerLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("Resource data unavailable.");
        synchronizeCampaignEconomyLedger(ctx, st);
        EconomyLogisticsIndustrySystem.LogisticsLedger ledger = st.economyExpansion.logistics;
        ArrayList<String> out = new ArrayList<>();
        out.add("Credits: " + ctx.credits + "  |  Ore " + currentCampaignOre(ctx));
        out.add("Operational State: Fuel " + logisticsStateLabel(campaignFuel(ctx), 42, 84)
                + "  |  Supply " + logisticsStateLabel(campaignSupplies(ctx), 34, 76));
        out.add("Strike Availability: Ammo " + campaignAmmo(ctx) + "  |  Torpedo Packages " + Math.max(0, st.strategicTorpedoCharges));
        out.add("Recovery Resources: Salvage " + campaignSalvageStock(ctx) + "  |  Supplies " + campaignSupplies(ctx));
        out.add("Blue Intervention Reserve: " + (int) Math.round(MathUtil.clamp(st.blueInterventionReserve, 0.0, 100.0)) + "%");
        out.add("Pressure: Intel " + campaignIntelReadout(ctx) + "  |  Exposure " + campaignExposureReadout(ctx));
        out.add("Fleet Strain: " + campaignFleetStrainReadout(ctx));
        out.add("Expansion Ledger: Production Progress " + ledger.readinessPercent + "%  |  Crew Fatigue " + ledger.crewFatigue
                + "  |  Maintenance " + ledger.maintenanceDebt);
        List<String> latestReport = campaignLatestAfterActionReportLines(ctx);
        if (!latestReport.isEmpty() && !latestReport.get(0).startsWith("No after-action")) {
            out.add("Latest Report: " + latestReport.get(0));
        }
        List<String> baseLedger = campaignBaseEconomyLedgerLines(ctx, 2);
        if (baseLedger.size() > 1) out.add("Base Economy: " + baseLedger.get(1));
        out.add(DeepCampaignSimulationSystem.commandBoardLines(st.deepCampaignExpansion).get(1));
        return out;
    }

