    public static boolean hasSelectedCampaignContactTarget(GameContext ctx) {
        refreshSelectedCampaignContactLock(ctx);
        return ctx != null && ctx.ui != null
                && ctx.ui.selectedCampaignContactLabel != null
                && !ctx.ui.selectedCampaignContactLabel.isBlank()
                && Double.isFinite(ctx.ui.selectedCampaignContactX)
                && Double.isFinite(ctx.ui.selectedCampaignContactY);
    }

    public static String selectedCampaignContactLabel(GameContext ctx) {
        refreshSelectedCampaignContactLock(ctx);
        return (ctx == null || ctx.ui == null) ? "" : ctx.ui.selectedCampaignContactLabel;
    }

    public static String selectedCampaignContactSubtitle(GameContext ctx) {
        refreshSelectedCampaignContactLock(ctx);
        return (ctx == null || ctx.ui == null) ? "" : ctx.ui.selectedCampaignContactSubtitle;
    }

    public static String selectedCampaignContactIntelLabel(GameContext ctx) {
        refreshSelectedCampaignContactLock(ctx);
        return (ctx == null || ctx.ui == null) ? "" : ctx.ui.selectedCampaignContactIntel;
    }

    public static boolean selectedCampaignContactHostile(GameContext ctx) {
        return ctx != null && ctx.ui != null && ctx.ui.selectedCampaignContactHostile;
    }

    public static void clearSelectedCampaignContact(GameContext ctx) {
        if (ctx == null || ctx.ui == null) return;
        ctx.ui.clearSelectedCampaignContact();
    }

    public static void selectCampaignContactTarget(GameContext ctx,
                                                   String label,
                                                   String subtitle,
                                                   String intelQuality,
                                                   double x,
                                                   double y,
                                                   boolean hostile,
                                                   boolean trackable) {
        if (ctx == null || ctx.ui == null) return;
        ctx.ui.selectedCampaignContactLabel = (label == null) ? "" : label.trim();
        ctx.ui.selectedCampaignContactSubtitle = (subtitle == null) ? "" : subtitle.trim();
        ctx.ui.selectedCampaignContactIntel = (intelQuality == null) ? "" : intelQuality.trim();
        ctx.ui.selectedCampaignContactX = x;
        ctx.ui.selectedCampaignContactY = y;
        ctx.ui.selectedCampaignContactHostile = hostile;
        ctx.ui.selectedCampaignContactTrackable = trackable;
        ctx.ui.selectedCampaignContactGalaxySearchGroupId = 0;
        CampaignState st = state(ctx);
        if (hostile && st != null && isStrategicOvermapMode(st)) {
            GalaxySearchGroup group = nearestHostileGalaxySearchGroup(st, x, y, 180.0);
            if (group != null && galaxySearchContactActionable(group)) {
                ctx.ui.selectedCampaignContactGalaxySearchGroupId = group.id;
                ctx.ui.selectedCampaignContactLabel = contactConfidenceLabel(group);
                ctx.ui.selectedCampaignContactSubtitle = contactIntelQualityLabel(group.intelQuality)
                        + "  |  " + contactConfidenceReadout(group) + "  |  " + doctrineReadout(group);
                ctx.ui.selectedCampaignContactIntel = contactIntelQualityLabel(group.intelQuality);
                ctx.ui.selectedCampaignContactX = group.x;
                ctx.ui.selectedCampaignContactY = group.y;
            } else if (group != null
                    && group.contactConfidence == GalaxyContactConfidence.LOST_CONTACT
                    && GameMath.dist2(x, y, group.x, group.y) <= 60.0 * 60.0) {
                ctx.ui.clearSelectedCampaignContact();
            }
        }
    }

    public static boolean trackSelectedCampaignContact(GameContext ctx) {
        if (!hasSelectedCampaignContactTarget(ctx)) return false;
        UISystem.addPing(ctx, ctx.ui.selectedCampaignContactX, ctx.ui.selectedCampaignContactY, 2.2);
        EventSystem.showBanner(ctx, "TRACKING " + selectedCampaignContactLabel(ctx).toUpperCase(Locale.US), 1.2);
        return true;
    }

    public static boolean engageSelectedCampaignContact(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !hasSelectedCampaignContactTarget(ctx) || !selectedCampaignContactHostile(ctx)) return false;
        GalaxySearchGroup group = selectedCampaignSearchGroup(ctx);
        if (group == null) {
            EventSystem.showBanner(ctx, "NO DIRECT-ENGAGE HOSTILE CONTACT AT CURRENT TARGET LOCK", 1.2);
            return false;
        }
        String locationLine = strategicEncounterLocationLine(ctx, st, group);
        showGalaxySearchGroupEncounterChoice(
                ctx,
                group,
                "HOSTILE CONTACT: " + contactConfidenceLabel(group).toUpperCase(Locale.US),
                "Direct engagement ordered. Take command to break the hostile screen in one large tactical sector, or auto-resolve from the campaign layer.",
                locationLine,
                galaxySearchGroupStrengthReadout(ctx, st, group));
        st.galaxyTravel.clear();
        EventSystem.showBanner(ctx, "HOSTILE CONTACT MARKED FOR INTERCEPT", 1.4);
        return true;
    }

    public static boolean launchSelectedCampaignTorpedoStrike(GameContext ctx) {
        if (isMissionTacticalStrikeMode(ctx)) {
            return launchSelectedTacticalTorpedoStrike(ctx);
        }
        StrikePreflight preflight = buildStrikePreflight(ctx, "TORPEDO_STRIKE");
        if (!preflight.valid) {
            recordStrikeDenial(ctx, preflight);
            if (ctx != null) EventSystem.showBanner(ctx, ("TORPEDO STRIKE  |  " + preflight.reason).toUpperCase(Locale.US), 1.2);
            return hasSelectedCampaignContactTarget(ctx);
        }
        CampaignState st = state(ctx);
        boolean result = launchStrategicTorpedoStrike(ctx, preflight.targetX, preflight.targetY);
        if (!result) EventSystem.showBanner(ctx, "NO STRIKE-ELIGIBLE CONTACT AT CURRENT TARGET LOCK", 1.2);
        return result;
    }

    public static boolean launchSelectedCampaignSortie(GameContext ctx) {
        if (isMissionTacticalStrikeMode(ctx)) {
            return launchSelectedTacticalSortie(ctx);
        }
        StrikePreflight preflight = buildStrikePreflight(ctx, "CARRIER_SORTIE");
        if (!preflight.valid) {
            recordStrikeDenial(ctx, preflight);
            if (ctx != null) EventSystem.showBanner(ctx, ("CARRIER SORTIE  |  " + preflight.reason).toUpperCase(Locale.US), 1.2);
            return hasSelectedCampaignContactTarget(ctx);
        }
        CampaignState st = state(ctx);
        boolean result = launchStrategicSortie(ctx, preflight.targetX, preflight.targetY);
        if (!result) EventSystem.showBanner(ctx, "NO SORTIE-ELIGIBLE CONTACT AT CURRENT TARGET LOCK", 1.2);
        return result;
    }

    public static boolean launchSelectedCampaignAtomicStrike(GameContext ctx) {
        if (isMissionTacticalStrikeMode(ctx)) {
            return launchSelectedTacticalAtomicStrike(ctx);
        }
        StrikePreflight preflight = buildStrikePreflight(ctx, "ATOMIC_STRIKE");
        if (!preflight.valid) {
            recordStrikeDenial(ctx, preflight);
            if (ctx != null) EventSystem.showBanner(ctx, ("ATOMIC STRIKE  |  " + preflight.reason).toUpperCase(Locale.US), 1.2);
            return hasSelectedCampaignContactTarget(ctx);
        }
        CampaignState st = state(ctx);
        boolean result = launchStrategicAtomicStrike(ctx, preflight.targetX, preflight.targetY);
        if (!result) EventSystem.showBanner(ctx, "NO ATOMIC-ELIGIBLE CONTACT AT CURRENT TARGET LOCK", 1.2);
        return result;
    }

    private static void recordStrikeDenial(GameContext ctx, StrikePreflight preflight) {
        CampaignState st = state(ctx);
        if (st == null || preflight == null) return;
        recordStructuredCampaignEvent(st, "campaign.strike.denied",
                "action=" + safeTelemetryValue(preflight.actionId)
                        + " target=" + safeTelemetryValue(preflight.targetLabel)
                        + " reason=" + safeTelemetryValue(preflight.reason));
    }

    static void noteAmbientSupportRequest(GameContext ctx, Ship target) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || target == null || !st.galaxyAmbientEncounterActive) return;
        CampaignLocation location = campaignLocationById(st, st.activeGalaxyEncounterLocationId);
        if (location == null) return;
        if (ctx.player == null || ctx.player.faction == null || target.faction == null || target.faction == Faction.ENEMY) return;
        String name = (target.name == null) ? "" : target.name.toUpperCase(Locale.US);
        boolean distressRecruit = (location.type == CampaignLocationType.DISTRESS_SIGNAL || location.type == CampaignLocationType.STORY_EVENT)
                && (name.contains("DISTRESS") || name.contains("RELIEF") || name.contains("LOST"));
        boolean installationHire = (!location.services.isEmpty() || isOpenCampaignMissionHub(location) || location.type == CampaignLocationType.REPAIR_SITE)
                && isPersistentRecruitableShip(target);
        if (!distressRecruit && !installationHire) return;
        st.galaxyAmbientSupportRequested = true;
        if (installationHire) {
            st.galaxyAmbientHiredShipIds.add(target.id);
            EventSystem.showBanner(ctx, "HIRE CONTRACT LOCKED  " + target.name.toUpperCase(Locale.US) + " WILL JOIN ON EXTRACTION", 1.3);
        } else {
            EventSystem.showBanner(ctx, "DISTRESS CHANNEL LOCKED  SURVIVORS MOVING TO YOUR NET", 1.2);
        }
    }

    private static void refreshSelectedCampaignContactLock(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || ctx.ui == null) return;
        if (ctx.ui.selectedCampaignContactGalaxySearchGroupId <= 0 || !isStrategicOvermapMode(st)) return;
        GalaxySearchGroup group = galaxySearchGroupById(st, ctx.ui.selectedCampaignContactGalaxySearchGroupId);
        if (group == null || !group.hostile || !galaxySearchContactActionable(group)) {
            ctx.ui.clearSelectedCampaignContact();
            return;
        }
        ctx.ui.selectedCampaignContactLabel = contactConfidenceLabel(group);
        ctx.ui.selectedCampaignContactSubtitle = contactIntelQualityLabel(group.intelQuality)
                + "  |  " + contactConfidenceReadout(group) + "  |  " + doctrineReadout(group);
        ctx.ui.selectedCampaignContactIntel = contactIntelQualityLabel(group.intelQuality);
        ctx.ui.selectedCampaignContactX = group.x;
        ctx.ui.selectedCampaignContactY = group.y;
        ctx.ui.selectedCampaignContactHostile = group.hostile;
        ctx.ui.selectedCampaignContactTrackable = galaxySearchContactActionable(group);
    }

    private static GalaxySearchGroup selectedCampaignSearchGroup(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || ctx.ui == null) return null;
        if (ctx.ui.selectedCampaignContactGalaxySearchGroupId > 0) {
            GalaxySearchGroup group = galaxySearchGroupById(st, ctx.ui.selectedCampaignContactGalaxySearchGroupId);
            if (group != null && group.hostile && galaxySearchContactActionable(group)) return group;
        }
        GalaxySearchGroup group = nearestHostileGalaxySearchGroup(st, ctx.ui.selectedCampaignContactX, ctx.ui.selectedCampaignContactY, 420.0);
        return galaxySearchContactActionable(group) ? group : null;
    }

    private static StrategicStrikeTargetLock resolveStrategicStrikeTargetLock(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return null;
        if (hasSelectedCampaignContactTarget(ctx) && selectedCampaignContactHostile(ctx)) {
            return new StrategicStrikeTargetLock(
                    selectedCampaignContactLabel(ctx),
                    selectedCampaignContactIntelLabel(ctx),
                    ctx.ui.selectedCampaignContactX,
                    ctx.ui.selectedCampaignContactY);
        }
        if (!isStrategicOvermapMode(st) || !Double.isFinite(st.playerGalaxyX) || !Double.isFinite(st.playerGalaxyY)) return null;
        CampaignForce force = nearestStrikeableCampaignForce(st, st.playerGalaxyX, st.playerGalaxyY, 900.0);
        if (force != null) {
            return new StrategicStrikeTargetLock(force.name, "Tracked", forceMarkerX(force), forceMarkerY(force));
        }
        GalaxySearchGroup group = nearestHostileGalaxySearchGroup(st, st.playerGalaxyX, st.playerGalaxyY, 900.0);
        if (group == null) return null;
        double dist = Math.hypot(group.x - st.playerGalaxyX, group.y - st.playerGalaxyY);
        ContactIntelQuality intel = (group.intelQuality == null) ? ContactIntelQuality.UNKNOWN : group.intelQuality;
        if (intel.ordinal() < ContactIntelQuality.TRACKED.ordinal() && !(group.visible && dist <= 260.0)) return null;
        String intelLabel = intel.ordinal() >= ContactIntelQuality.TRACKED.ordinal()
                ? contactIntelQualityLabel(intel)
                : "Tracked";
        return new StrategicStrikeTargetLock(hostileSearchGroupDisplayName(st, group), intelLabel, group.x, group.y);
    }

    private static StrikePreflight buildStrikePreflight(GameContext ctx, String actionId) {
        CampaignState st = state(ctx);
        String id = (actionId == null) ? "" : actionId.trim().toUpperCase(Locale.US);
        StrategicStrikeTargetLock targetLock = resolveStrategicStrikeTargetLock(ctx);
        String targetLabel = targetLock != null ? targetLock.label : "NO TARGET SELECTED";
        boolean hostile = targetLock != null;
        String intel = targetLock != null ? targetLock.intelLabel : "";
        boolean trackedIntel = "Tracked".equalsIgnoreCase(intel) || "Target-Quality".equalsIgnoreCase(intel);
        boolean identifiedIntel = "Identified".equalsIgnoreCase(intel) || trackedIntel;
        StrikeCost cost = strikeCost(ctx, st, id, intel, false);
        int ammoCost = cost.ammo;
        int fuelCost = cost.fuel;
        int supplyCost = cost.supplies;
        int chargeCost = cost.charges;
        String effect = "";
        String retaliation = "";
        String reason = "";
        boolean valid = true;
        if (ctx == null || st == null) {
            return new StrikePreflight(id, targetLabel, false, "strike systems offline", 0, 0, 0, 0, "", "");
        }
        switch (id) {
            case "TORPEDO_STRIKE" -> {
                effect = "Heavy direct damage to a tracked hostile; spends a scarce torpedo package.";
                retaliation = "High alert and exposure spike.";
                if (!hostile) reason = "no tracked hostile contact selected";
                else if (!trackedIntel) reason = "target intel below Tracked";
                else if (st.strategicTorpedoCharges <= 0) reason = "no torpedo strikes ready";
                else if (st.campaignAmmo < ammoCost) reason = "insufficient ammo";
                else if (st.campaignFuel < fuelCost) reason = "insufficient fuel";
            }
            case "CARRIER_SORTIE" -> {
                effect = "Flexible strike package with recon follow-through; ties up carrier readiness.";
                retaliation = "High alert and exposure increase.";
                int sortieCap = strategicSortieCapacity(ctx);
                if (!hostile) reason = "no identified hostile contact selected";
                else if (!identifiedIntel) reason = "target intel below Identified";
                else if (sortieCap <= 0) reason = "no carrier sorties available";
                else if (st.strategicSortiesLaunched >= sortieCap) reason = "sortie decks committed";
                else if (st.campaignAmmo < ammoCost) reason = "insufficient ammo";
                else if (st.campaignFuel < fuelCost) reason = "insufficient fuel";
                else if (st.campaignSupplies < supplyCost) reason = "insufficient supplies";
            }
            case "ATOMIC_STRIKE" -> {
                effect = "Devastating strike with severe theater consequence.";
                retaliation = "Massive alert, exposure, and political blowback.";
                if (!hostile) reason = "no target-quality hostile contact selected";
                else if (!"Target-Quality".equalsIgnoreCase(intel)) reason = "target intel below Target-Quality";
                else if (st.strategicAtomicCharges <= 0) reason = "atomic option unavailable";
                else if (st.campaignAmmo < ammoCost) reason = "insufficient ammo";
                else if (st.campaignFuel < fuelCost) reason = "insufficient fuel";
                else if (st.campaignSupplies < supplyCost) reason = "insufficient supplies";
            }
            default -> {
                reason = "unknown strike action";
            }
        }
        if (reason.isBlank() && hostile && targetLock != null
                && !isWithinStrategicStrikeRange(ctx, st, targetLock.x, targetLock.y)) {
            reason = "target outside strike range";
        }
        valid = reason.isBlank();
        return new StrikePreflight(id, targetLabel,
                targetLock == null ? Double.NaN : targetLock.x,
                targetLock == null ? Double.NaN : targetLock.y,
                valid, reason, ammoCost, fuelCost, supplyCost, chargeCost, effect, retaliation);
    }

    private static StrikeCost strikeCost(GameContext ctx, CampaignState st, String actionId, String intelLabel, boolean tactical) {
        String id = (actionId == null) ? "" : actionId.trim().toUpperCase(Locale.US);
        int ammo = 0;
        int fuel = 0;
        int supplies = 0;
        int charges = 0;
        switch (id) {
            case "TORPEDO_STRIKE", "TACTICAL_TORPEDO_STRIKE" -> {
                ammo = TORPEDO_STRIKE_BASE_AMMO_COST;
                fuel = TORPEDO_STRIKE_BASE_FUEL_COST;
                charges = 1;
            }
            case "CARRIER_SORTIE", "TACTICAL_CARRIER_SORTIE" -> {
                ammo = SORTIE_STRIKE_BASE_AMMO_COST;
                fuel = SORTIE_STRIKE_BASE_FUEL_COST;
                supplies = SORTIE_STRIKE_BASE_SUPPLY_COST;
            }
            case "ATOMIC_STRIKE", "TACTICAL_ATOMIC_STRIKE" -> {
                ammo = ATOMIC_STRIKE_BASE_AMMO_COST;
                fuel = ATOMIC_STRIKE_BASE_FUEL_COST;
                supplies = ATOMIC_STRIKE_BASE_SUPPLY_COST;
                charges = 1;
            }
            default -> {
                return new StrikeCost(0, 0, 0, 0);
            }
        }
        if (tactical) {
            return new StrikeCost(ammo, fuel, supplies, charges);
        }
        double multiplier = 1.0;
        if ("Target-Quality".equalsIgnoreCase(intelLabel)) {
            multiplier += 0.18;
        } else if ("Tracked".equalsIgnoreCase(intelLabel)) {
            multiplier += 0.08;
        }
        double heat = (st == null) ? 0.0 : MathUtil.clamp(st.recentStrikePressure / 100.0, 0.0, 1.0);
        multiplier += heat * 0.35;
        StrategicRoleProfile profile = friendlyStrategicRoleProfile(ctx, st);
        multiplier -= profile.logisticsSupport() * 0.14;
        multiplier -= profile.carrierProjection() * 0.08;
        multiplier = MathUtil.clamp(multiplier, 0.92, 1.55);
        return new StrikeCost(
                (int) Math.ceil(ammo * multiplier),
                (int) Math.ceil(fuel * multiplier),
                (int) Math.ceil(supplies * multiplier),
                charges);
    }

    private static String strategicStrikeCostIntelLabel(GameContext ctx) {
        if (hasSelectedCampaignContactTarget(ctx) && selectedCampaignContactHostile(ctx)) {
            String intel = selectedCampaignContactIntelLabel(ctx);
            if (intel != null && !intel.isBlank()) return intel;
        }
        return "Tracked";
    }

    public static List<String> campaignNavigationStationLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("Navigation offline.");
        CampaignTravelState travel = st.galaxyTravel;
        CampaignLocation selected = selectedCampaignLocation(ctx);
        String selectedCourse = selectedStrategicDestinationLabel(ctx);
        String routeRisk = (travel != null && travel.traveling)
                ? ((int) Math.round(travel.interceptionRisk) + "% INTERCEPT RISK")
                : ("Alert " + enemyAlertReadout(ctx));
        String blocker = selected == null
                ? "Select a destination or free course"
                : (canEnterSelectedLocalEncounter(ctx)
                ? "Enter site available"
                : (isWithinDockingRange(st, selected) ? "Approach / dock range established" : "Move within approach range"));
        ArrayList<String> out = new ArrayList<>();
        out.add("SESSION TIME");
        out.add(formatCampaignSessionClock(st.sectorElapsed));
        out.add("Current Order: " + ((travel != null && travel.traveling) ? "TRAVEL" : "HOLDING"));
        out.add("Selected Course: " + selectedCourse);
        out.add("Travel: " + galaxyTravelSidebarReadout(ctx, travel));
        out.add("Fleet Order: " + campaignFleetPostureReadout(ctx));
        out.add("Travel Danger: " + routeRisk);
        out.add("Immediate Blocker: " + blocker);
        out.add("Reputation: " + campaignReputationReadout(ctx));
        out.add("Regional Situation: " + theaterPressureReadout(ctx));
        out.add("Map use: select first, then command from the action bay.");
        return out;
    }

    public static List<String> campaignReceiverBoardLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("Receiver offline.");
        CampaignTravelState travel = st.galaxyTravel;
        String bestLead = campaignCrewCommentaryLines(ctx).isEmpty()
                ? "No actionable lead"
                : campaignCrewCommentaryLines(ctx).get(0);
        CampaignLocation selected = selectedCampaignLocation(ctx);
        String selectedLine = selected == null
                ? selectedStrategicDestinationLabel(ctx)
                : selected.name + "  |  " + dockingStatusReadout(ctx, selected);
        ArrayList<String> out = new ArrayList<>();
        out.add("Objective: " + selectedLine);
        out.add("Fleet: " + ((travel != null && travel.traveling) ? "TRAVELING" : "HOLDING")
                + "  |  " + campaignFleetPostureReadout(ctx));
        out.add("Threat: " + enemyAlertReadout(ctx) + "  |  " + enemyAlertRegionReadout(ctx));
        out.add("Intel: " + campaignIntelReadout(ctx) + "  |  uncertain " + uncertainContactCount(st));
        out.add("Advice: " + bestLead);
        out.add((travel != null && travel.traveling)
                ? ("Drive: " + (travel.freeTravel ? "free course" : "selected route"))
                : "Drive: select a destination or free course");
        out.add("Fleet State: " + ((travel != null && travel.traveling) ? "TRAVELING" : "HOLDING")
                + "  |  " + campaignFleetPostureReadout(ctx));
        out.add("Destination: " + selectedStrategicDestinationLabel(ctx));
        return out;
    }

    public static List<String> campaignDirectionFinderLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("Direction finder offline.");
        CampaignLocation selected = selectedCampaignLocation(ctx);
        String routeVector = "Route Vector: HOLDING PATTERN";
        if (selected != null) {
            double dx = selected.x - st.playerGalaxyX;
            double dy = selected.y - st.playerGalaxyY;
            String facing = Math.abs(dx) > Math.abs(dy)
                    ? ((dx >= 0.0) ? "EASTBOUND" : "WESTBOUND")
                    : ((dy >= 0.0) ? "SOUTHBOUND" : "NORTHBOUND");
            routeVector = "Route Vector: " + facing;
        }
        ArrayList<String> out = new ArrayList<>();
        out.add("Selected: " + selectedStrategicDestinationLabel(ctx));
        out.add(routeVector);
        out.add("Docking: " + (selected == null ? "NO DESTINATION SELECTED" : dockingStatusReadout(ctx, selected)));
        out.add("Travel Danger: " + routeDangerTrendLine(ctx, selected).replace("Danger Trend: ", ""));
        out.add("Exposure: " + campaignExposureReadout(ctx));
        out.add("Enter Site: " + (canEnterSelectedLocalEncounter(ctx) ? "READY" : "NO LOCAL CONTACT"));
        out.add("Regional Situation: " + theaterPressureReadout(ctx));
        out.add("Note: Green traffic is denser here. We are not alone.");
        return out;
    }

    public static List<String> campaignCommsBoardLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("Comms offline.");
        ArrayList<String> out = new ArrayList<>();
        out.add("Actionable Lead: " + campaignCrewCommentaryLines(ctx).get(0));
        if (!st.theaterWarRecentEvents.isEmpty()) {
            String latest = st.theaterWarRecentEvents.get(st.theaterWarRecentEvents.size() - 1);
            out.add("War Change: " + latest);
        } else {
            out.add("War Change: no major theater shift reported");
        }
        List<String> log = campaignCaptainLogLines(ctx, 1);
        if (!log.isEmpty()) out.add("Captain's Log: " + log.get(0));
        List<String> memory = campaignMemoryFlagLines(ctx, 1);
        if (!memory.isEmpty() && !memory.get(0).contains("no persistent flags")) {
            out.add("Memory: " + memory.get(0).replaceFirst("^Memory:\\s*", ""));
        }
        out.add("Green: " + st.greenDirectorBrief.replaceFirst("^Green:\\s*", ""));
        out.add("Yellow: " + st.yellowDirectorBrief.replaceFirst("^Yellow:\\s*", ""));
        out.add("Red: " + st.redDirectorBrief.replaceFirst("^Red:\\s*", ""));
        out.add("Standing: " + campaignRelationshipBoardLine(ctx));
        out.add("Reputation: " + campaignReputationReadout(ctx));
        out.add("Green Reputation: " + st.greenContractFavor);
        out.add("Contacts: " + campaignRelationshipBoardLine(ctx));
        out.add("Crew: Radio room standing by for sweeps.");
        out.add("Lead  |  " + campaignCrewCommentaryLines(ctx).get(0));
        out.add("Expansion Reputation Mil " + campaignReputationReadout(ctx));
        return out;
    }

    public static List<String> strategicFleetRoleSummaryLines(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of();
        StrategicRoleProfile profile = friendlyStrategicRoleProfile(ctx, st);
        ArrayList<String> out = new ArrayList<>();
        out.add("Stealth Screen: " + roleStrengthLabel(profile.stealthCoverage()));
        out.add("Carrier Projection: " + roleStrengthLabel(profile.carrierProjection()));
        out.add("Heavy Presence: " + roleStrengthLabel(profile.heavyPresence()));
        out.add("Strike Reach: " + roleStrengthLabel(profile.strikeReach()));
        out.add("Role Coverage Bonus: x" + String.format(Locale.US, "%.2f", profile.roleCoverageBonus()));
        return out;
    }

    private static String roleStrengthLabel(double value) {
        double v = MathUtil.clamp(value, 0.0, 1.0);
        if (v <= 0.04) return "NONE";
        if (v <= 0.18) return "LIGHT";
        if (v <= 0.34) return "SOLID";
        if (v <= 0.54) return "STRONG";
        return "DOMINANT";
    }

    private static String formatCampaignSessionClock(double seconds) {
        int total = Math.max(0, (int) Math.floor(seconds));
        int hours = total / 3600;
        int minutes = (total % 3600) / 60;
        int secs = total % 60;
        return String.format(Locale.US, "%02d:%02d:%02d", hours, minutes, secs);
    }

    private static String receiverBandLabel(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return "50-79 MHZ";
        double intel = MathUtil.clamp(st.campaignIntelLevel, 0.0, 100.0);
        if (intel < 28.0) return "50-79 MHZ";
        if (intel < 56.0) return "80-109 MHZ";
        if (intel < 78.0) return "110-139 MHZ";
        return "140-169 MHZ";
    }

    private static FleetPosture resolveFleetPosture(String raw) {
        if (raw != null) {
            try {
                return FleetPosture.valueOf(raw.trim().toUpperCase(Locale.US));
            } catch (Exception ignored) {
                // Fall through to default.
            }
        }
        return FleetPosture.SILENT_RUNNING;
    }

