    private static double postureTransitCooldownBias(FleetPosture posture) {
        return switch ((posture == null) ? FleetPosture.SILENT_RUNNING : posture) {
            case SILENT_RUNNING -> 2.0;
            case COMBAT_PATROL -> 1.0;
            case RESCUE_PRIORITY -> -2.0;
            case RAIDER_DOCTRINE -> -1.0;
            case LOGISTICS_CONSERVATION -> 1.5;
            case RECON_SWEEP -> -3.0;
        };
    }

    private static double postureInterceptRangeBias(FleetPosture posture) {
        return switch ((posture == null) ? FleetPosture.SILENT_RUNNING : posture) {
            case SILENT_RUNNING -> -0.18;
            case COMBAT_PATROL -> 0.10;
            case RESCUE_PRIORITY -> 0.04;
            case RAIDER_DOCTRINE -> 0.08;
            case LOGISTICS_CONSERVATION -> -0.06;
            case RECON_SWEEP -> 0.12;
        };
    }

    private static double postureAlertOnForcedIntercept(FleetPosture posture) {
        return switch ((posture == null) ? FleetPosture.SILENT_RUNNING : posture) {
            case SILENT_RUNNING -> -2.0;
            case COMBAT_PATROL -> 2.0;
            case RESCUE_PRIORITY -> 0.0;
            case RAIDER_DOCTRINE -> 3.0;
            case LOGISTICS_CONSERVATION -> -1.0;
            case RECON_SWEEP -> 1.0;
        };
    }

    private static String fleetPostureEffectSummary(FleetPosture posture) {
        return switch ((posture == null) ? FleetPosture.SILENT_RUNNING : posture) {
            case SILENT_RUNNING -> "low detect / slow burn / weak sweep";
            case COMBAT_PATROL -> "hard screen / higher drain / louder signature";
            case RESCUE_PRIORITY -> "more aid leads / steadier allies / slower push";
            case RAIDER_DOCTRINE -> "aggressive gains / hotter reprisals / higher exposure";
            case LOGISTICS_CONSERVATION -> "lean drain / slow response / soft posture";
            case RECON_SWEEP -> "sharp IDs / more discoveries / easier to detect";
        };
    }

    private static String campaignBearingReadout(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return "000 DEG";
        double fromX = st.playerGalaxyX;
        double fromY = st.playerGalaxyY;
        CampaignLocation selected = selectedCampaignLocation(ctx);
        double targetX;
        double targetY;
        if (selected != null) {
            targetX = selected.x;
            targetY = selected.y;
        } else if (hasSelectedFreeTravelTarget(ctx)) {
            targetX = selectedFreeTravelTargetX(ctx);
            targetY = selectedFreeTravelTargetY(ctx);
        } else {
            return "NO LOCK";
        }
        double angle = Math.toDegrees(Math.atan2(targetY - fromY, targetX - fromX));
        int bearing = Math.floorMod((int) Math.round(angle + 90.0), 360);
        return String.format(Locale.US, "%03d DEG", bearing);
    }

    public static String localRangeBearingReadout(GameContext ctx, double worldX, double worldY) {
        if (ctx == null || ctx.player == null || !Double.isFinite(worldX) || !Double.isFinite(worldY)) {
            return "R --  |  BRG ---";
        }
        double dx = worldX - ctx.player.x;
        double dy = worldY - ctx.player.y;
        int range = (int) Math.round(Math.hypot(dx, dy));
        int bearing = Math.floorMod((int) Math.round(Math.toDegrees(Math.atan2(dy, dx)) + 90.0), 360);
        return String.format(Locale.US, "R %d  |  BRG %03d", Math.max(0, range), bearing);
    }

    private static String sweepWindowReadout(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return "COLD";
        if (st.campaignSupplies < sweepSupplyCost(resolveFleetPosture(st.selectedFleetPostureId))) return "COLD";
        if (st.campaignIntelLevel < 28.0) return "NARROW";
        if (st.campaignIntelLevel < 58.0) return "WORKABLE";
        return "OPEN";
    }

    private static String logisticsStateLabel(int value, int lowThreshold, int healthyThreshold) {
        int critical = Math.max(1, lowThreshold);
        int shortfall = Math.max(critical + 6, healthyThreshold - 22);
        int strained = Math.max(shortfall + 1, healthyThreshold);
        if (value < critical) return "CRITICAL";
        if (value < shortfall) return "SHORT";
        if (value < strained) return "STRAINED";
        return "STABLE";
    }

    private static String routeCostForecastLine(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return "2-JUMP FORECAST  |  OFFLINE";
        FleetPosture posture = resolveFleetPosture(st.selectedFleetPostureId);
        int fuel = Math.max(1, (int) Math.ceil(postureTravelFuelCostPerTick(posture, 20.0)));
        int supplies = Math.max(0, (int) Math.ceil(postureTravelSupplyCostPerTick(posture, 20.0)));
        int ammo = Math.max(0, (int) Math.ceil(postureTravelAmmoCostPerTick(posture, 20.0)));
        return "2-JUMP FORECAST  |  FUEL " + (fuel * 2) + "  SUP " + (supplies * 2) + "  AMMO " + (ammo * 2);
    }

    private static String strikeCostForecastLine(GameContext ctx) {
        StrikePreflight torpedo = buildStrikePreflight(ctx, "TORPEDO_STRIKE");
        StrikePreflight sortie = buildStrikePreflight(ctx, "CARRIER_SORTIE");
        return "STRIKE FORECAST  |  TORP " + torpedo.ammoCost + "/" + torpedo.fuelCost
                + "  SORTIE " + sortie.ammoCost + "/" + sortie.fuelCost + "/" + sortie.supplyCost;
    }

    private static String strikeRecoveryForecastLine(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return "STRIKE RECOVERY  |  OFFLINE";
        CampaignLocation hub = nearestStrikeRecoveryHub(st);
        HubProfile profile = hubProfile(ctx, hub);
        int credits = strikeRearmCreditCost(profile);
        int ore = strikeRearmOreCost(profile);
        int supplies = Math.max(3, (int) Math.round(5 / Math.max(0.70, profile.supportMul)));
        return "STRIKE RECOVERY  |  REARM C" + credits + " O" + ore + " S" + supplies
                + "  |  BUY fuel/supplies, SELL salvage" + strikeRecoveryHubSuffix(hub);
    }

    private static CampaignLocation nearestStrikeRecoveryHub(CampaignState st) {
        if (st == null) return null;
        CampaignLocation best = null;
        double bestD2 = Double.POSITIVE_INFINITY;
        for (CampaignLocation location : allCampaignLocations(st)) {
            if (location == null || !location.discovered || !location.services.contains(HubService.STRIKE_REARM)) continue;
            double d2 = GameMath.dist2(st.playerGalaxyX, st.playerGalaxyY, location.x, location.y);
            if (d2 < bestD2) {
                best = location;
                bestD2 = d2;
            }
        }
        return best;
    }

    private static String strikeRecoveryHubSuffix(CampaignLocation hub) {
        return hub == null ? "" : "  |  HUB " + hub.name;
    }

    private static String repairCostForecastLine(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return "REPAIR FORECAST  |  OFFLINE";
        StrategicRoleProfile profile = friendlyStrategicRoleProfile(ctx, st);
        int damagedShips = Math.max(1, damagedPersistentFleetCount(ctx, st));
        double supportMul = Math.max(0.7, 0.85 + profile.logisticsSupport());
        int supplyCost = Math.max(1, (int) Math.round((4 + damagedShips * 2) / supportMul));
        int salvageCost = Math.max(1, damagedShips);
        int minutes = Math.max(1, damagedShips * 2);
        return "REPAIR FORECAST  |  FIELD " + minutes + "m  SUP " + supplyCost + "  SALV " + salvageCost
                + "  |  full armor/systems require a repair hub";
    }

    private static String logisticsBlockerLine(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return "LIMITER  |  OFFLINE";
        if (campaignFuel(ctx) < 16) return "LIMITER  |  LONG MOVES BLOCKED BY FUEL SHORTAGE";
        if (campaignSupplies(ctx) < 12) return "LIMITER  |  SWEEP / REPAIR TEMPO COLLAPSING";
        if (campaignAmmo(ctx) < 18) return "LIMITER  |  LONG-RANGE STRIKES NEARLY DRY";
        return "LIMITER  |  NO HARD OPERATIONAL BLOCKER";
    }

    private static String pressureBandLabel(double value) {
        double v = MathUtil.clamp(value, 0.0, 100.0);
        if (v < 12.0) return "COLD";
        if (v < 32.0) return "LOW";
        if (v < 56.0) return "RISING";
        if (v < 78.0) return "HOT";
        return "SEVERE";
    }

    private static String routeSupportPreviewLine(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return "ROUTE PREVIEW OFFLINE";
        List<String> route = compactRouteAssessmentLines(ctx);
        if (!route.isEmpty()) {
            String support = route.size() >= 3 ? route.get(2) : route.get(route.size() - 1);
            return "ROUTE PREVIEW  |  " + support.replace("Support: ", "");
        }
        if (hasSelectedFreeTravelTarget(ctx)) {
            List<String> free = freeTravelSelectionLines(ctx);
            if (free.size() >= 7) {
                return "ROUTE PREVIEW  |  " + free.get(6).replace("Support: ", "");
            }
        }
        return "ROUTE PREVIEW  |  NO ROUTE SELECTED";
    }

    private static String selectedStrikeOpportunityLine(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return "TARGET BOARD OFFLINE";
        CampaignLocation selected = selectedCampaignLocation(ctx);
        if (selected != null) {
            return "TARGET WINDOW  |  " + selected.name.toUpperCase(Locale.US) + "  " + threatReadoutForSidebar(selected.threatLevel);
        }
        StrategicStrikeTargetLock lock = resolveStrategicStrikeTargetLock(ctx);
        if (lock != null) {
            return "TARGET WINDOW  |  " + lock.label.toUpperCase(Locale.US) + "  " + lock.intelLabel.toUpperCase(Locale.US);
        }
        double bestDist = Double.POSITIVE_INFINITY;
        GalaxySearchGroup best = null;
        for (GalaxySearchGroup group : st.galaxySearchGroups) {
            if (group == null || !group.hostile || !group.visible) continue;
            double dist = Math.hypot(group.x - st.playerGalaxyX, group.y - st.playerGalaxyY);
            if (dist < bestDist) {
                bestDist = dist;
                best = group;
            }
        }
        if (best != null) {
            return "TARGET WINDOW  |  " + doctrineReadout(best).toUpperCase(Locale.US) + "  " + contactConfidenceLabel(best).toUpperCase(Locale.US);
        }
        return "TARGET WINDOW  |  NO FIRM TARGET";
    }

    private static String dockedLocationReadout(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || st.dockedGalaxyLocationId == null || st.dockedGalaxyLocationId.isBlank()) {
            return "UNLATCHED";
        }
        CampaignLocation docked = campaignLocationById(st, st.dockedGalaxyLocationId);
        return (docked == null) ? "UNLATCHED" : ("LATCHED " + docked.name.toUpperCase(Locale.US));
    }

    public static boolean isDockedAtSelectedLocation(GameContext ctx) {
        CampaignState st = state(ctx);
        CampaignLocation selected = selectedCampaignLocation(ctx);
        return st != null && selected != null && selected.id.equalsIgnoreCase(st.dockedGalaxyLocationId);
    }

    public static List<String> campaignScoutingReportLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of();
        ArrayList<CampaignForce> hostile = new ArrayList<>();
        for (CampaignForce force : st.campaignForces) {
            if (force == null || force.destroyed || !force.simulationActive || force.faction != Faction.ENEMY || force.kind == CampaignForceKind.PLAYER_FLEET) continue;
            if (force.strength <= 1.0 && force.shipIds.isEmpty() && force.linkedSearchGroupId <= 0) continue;
            hostile.add(force);
        }
        hostile.sort((a, b) -> {
            double da = Math.hypot(forceMarkerX(a) - st.playerGalaxyX, forceMarkerY(a) - st.playerGalaxyY);
            double db = Math.hypot(forceMarkerX(b) - st.playerGalaxyX, forceMarkerY(b) - st.playerGalaxyY);
            return Double.compare(da, db);
        });
        ArrayList<String> out = new ArrayList<>();
        for (CampaignForce force : hostile) {
            out.add("Scout Report: " + force.name
                    + " from " + campaignForceOriginReadout(st, force)
                    + "  |  " + campaignForceIntentLabel(force.intent)
                    + "  |  confidence " + (int) Math.round(force.contactConfidence * 100.0) + "%");
            if (out.size() >= 2) break;
        }
        if (out.isEmpty()) out.add("Scout Report: no hostile force provenance in current sensor picture.");
        return out;
    }

    private static String campaignForceOriginReadout(CampaignState st, CampaignForce force) {
        if (force == null) return "unknown origin";
        CampaignLocation source = campaignLocationById(st, force.sourceLocationId);
        String origin = (force.origin == null || force.origin.isBlank()) ? "campaign theater" : force.origin;
        if (source != null && source.name != null && !source.name.isBlank()) return source.name + " / " + origin;
        return origin;
    }

    public static List<String> galaxyIntelSummaryLines(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of();
        ArrayList<String> out = new ArrayList<>();
        out.add("Intel Quality  |  " + campaignIntelReadout(ctx));
        out.add("Operational Exposure  |  " + campaignExposureReadout(ctx));
        out.addAll(campaignScoutingReportLines(ctx));
        if (!st.galaxySearchGroups.isEmpty()) {
            for (GalaxySearchGroup group : st.galaxySearchGroups) {
                if (group == null || !group.visible) continue;
                String name = contactConfidenceLabel(group);
                String state = switch (group.behavior) {
                    case PATROLLING -> "patrolling";
                    case SEARCHING -> "searching";
                    case INVESTIGATING -> "investigating";
                    case INTERCEPTING -> "intercepting";
                    case GUARDING -> "guarding";
                    case RETURNING -> "returning";
                };
                out.add(name + "  |  " + contactIntelQualityLabel(group.intelQuality) + "  |  " + doctrineReadout(group) + "  |  " + state);
                if (out.size() >= 6) break;
            }
        }
        if (out.size() <= 4) {
            out.add("No confirmed hostile contacts in current sensor picture.");
        }
        for (CampaignForceSummary force : campaignForceSummaries(ctx)) {
            if (force == null) continue;
            out.add("Force: " + force.name + "  |  " + campaignForceIntentLabel(force.intent)
                    + "  |  strength " + (int) Math.round(force.strength));
            if (out.size() >= 7) break;
        }
        return out;
    }

    public static String hubServiceActionLabel(GameContext ctx, CampaignLocation location, HubService service) {
        if (service == null) return "SERVICE";
        return service.label.toUpperCase(Locale.US);
    }

    public static String hubServiceActionDetail(GameContext ctx, CampaignLocation location, HubService service) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || location == null || service == null) return "";
        if (!stationServiceAvailableFor(location, service)) return "OFFLINE";
        if (!isDockedAtSelectedLocation(ctx)) return "APPROACH";
        HubProfile profile = hubProfile(ctx, location);
        double priceMul = hubServicePriceMultiplier(profile, location, service);
        return switch (service) {
            case REPAIR -> "C " + GameContext.scaleCreditEarnings((int) Math.round((80 + damagedPersistentFleetCount(ctx, st) * 28) * priceMul));
            case TRADE -> {
                int amount = campaignOreSaleAmount(ctx);
                int payout = campaignOreSaleCredits(ctx, location, amount);
                yield amount <= 0 ? "NO ORE" : ("SELL " + amount + " ORE  +" + payout + "C");
            }
            case REFIT -> "C " + GameContext.scaleCreditEarnings((int) Math.round(110 * priceMul));
            case SHIPYARD -> "BUILD READY";
            case SUPPLY -> "C " + GameContext.scaleCreditEarnings((int) Math.round(90 * priceMul));
            case STRIKE_REARM -> "C " + strikeRearmCreditCost(profile) + " O " + strikeRearmOreCost(profile);
            case INTEL -> "C " + GameContext.scaleCreditEarnings((int) Math.round(70 * priceMul));
            case CONTRACTS -> "TAKE ADVANCE";
            case SALVAGE -> "PAYOUT";
            case FUEL -> "C " + GameContext.scaleCreditEarnings((int) Math.round(70 * priceMul));
        };
    }

    public static boolean openSelectedHubService(GameContext ctx, HubService service) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || ctx.ui == null || service == null) return false;
        CampaignLocation location = selectedCampaignLocation(ctx);
        if (location == null || !location.services.contains(service)) return false;
        if (!isDockedAtSelectedLocation(ctx)) {
            EventSystem.showBanner(ctx, "MOVE INTO DOCKING RANGE BEFORE USING HUB SERVICES", 1.3);
            return false;
        }
        ctx.ui.showCampaignHubMenu(location.id, service.name());
        EventSystem.showBanner(ctx, service.label.toUpperCase(Locale.US) + " - " + location.name.toUpperCase(Locale.US), 1.0);
        return true;
    }

    public static boolean executeSelectedHubService(GameContext ctx, String serviceId) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || serviceId == null || serviceId.isBlank()) return false;
        HubService service = hubServiceById(serviceId);
        CampaignLocation location = selectedCampaignLocation(ctx);
        if (service == null || location == null || !location.services.contains(service)) return false;
        if (!isDockedAtSelectedLocation(ctx)) {
            EventSystem.showBanner(ctx, "MOVE INTO DOCKING RANGE BEFORE USING HUB SERVICES", 1.3);
            return false;
        }
        return performHubService(ctx, st, location, service);
    }

    public static void closeHubServiceMenu(GameContext ctx) {
        if (ctx == null || ctx.ui == null) return;
        ctx.ui.clearCampaignHubMenu();
    }

    public static boolean confirmSelectedHubService(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || ctx.ui == null || !ctx.ui.campaignHubMenu.active) return false;
        CampaignLocation location = campaignLocationById(st, ctx.ui.campaignHubMenu.locationId);
        HubService service = hubServiceById(ctx.ui.campaignHubMenu.serviceId);
        if (location == null || service == null) {
            ctx.ui.clearCampaignHubMenu();
            return false;
        }
        boolean result = performHubService(ctx, st, location, service);
        ctx.ui.clearCampaignHubMenu();
        return result;
    }

    public static boolean beginCampaignAtomicStrikeConfirm(GameContext ctx) {
        if (ctx == null || ctx.ui == null) return false;
        boolean targetReady = isMissionTacticalStrikeMode(ctx)
                ? tacticalStrikeTargetReady(ctx, "ATOMIC_STRIKE")
                : (hasSelectedCampaignContactTarget(ctx)
                && selectedCampaignContactHostile(ctx)
                && "Target-Quality".equalsIgnoreCase(selectedCampaignContactIntelLabel(ctx)));
        if (!targetReady) {
            EventSystem.showBanner(ctx, "ATOMIC STRIKE  |  NO TARGET-QUALITY HOSTILE CONTACT SELECTED", 1.2);
            return false;
        }
        StrikePreflight preflight = isMissionTacticalStrikeMode(ctx)
                ? buildTacticalStrikePreflight(ctx, "ATOMIC_STRIKE")
                : buildStrikePreflight(ctx, "ATOMIC_STRIKE");
        String body = "Target: " + preflight.targetLabel
                + "  |  Cost: " + preflight.chargeCost + " atomic, A" + preflight.ammoCost
                + " F" + preflight.fuelCost + " S" + preflight.supplyCost
                + "  |  Risk: " + preflight.retaliation
                + (preflight.valid ? "" : "  |  CURRENT BLOCKER: " + preflight.reason.toUpperCase(Locale.US));
        ctx.ui.showCampaignActionConfirm("ATOMIC_STRIKE", "ATOMIC STRIKE CONFIRMATION", body);
        return true;
    }

    private static boolean isMissionTacticalStrikeMode(GameContext ctx) {
        CampaignState st = state(ctx);
        return ctx != null && st != null && st.enabled && !isStrategicOvermapMode(st) && ctx.ui != null;
    }

    private static boolean hasTacticalHostileStrikeSelection(GameContext ctx) {
        return ctx != null
                && ctx.ui != null
                && ctx.ui.tacticalMapSelectionHostile
                && ctx.ui.tacticalMapSelectionLabel != null
                && !ctx.ui.tacticalMapSelectionLabel.isBlank()
                && Double.isFinite(ctx.ui.tacticalMapSelectionX)
                && Double.isFinite(ctx.ui.tacticalMapSelectionY);
    }

    private static Ship tacticalLockedHostileStrikeShip(GameContext ctx) {
        if (ctx == null || ctx.player == null || ctx.lockedTarget == null) return null;
        Ship locked = ctx.lockedTarget;
        if (!locked.alive || locked.dying || locked.hp <= 0) return null;
        if (locked.faction == null || ctx.player.faction == null) return null;
        if (locked.faction.isFriendlyTo(ctx.player.faction)) return null;
        return locked;
    }

    private static boolean hasAnyTacticalStrikeTarget(GameContext ctx) {
        return hasTacticalHostileStrikeSelection(ctx) || tacticalLockedHostileStrikeShip(ctx) != null;
    }

    private static String tacticalStrikeTargetLabel(GameContext ctx) {
        if (hasTacticalHostileStrikeSelection(ctx)) {
            return ctx.ui.tacticalMapSelectionLabel.trim();
        }
        Ship locked = tacticalLockedHostileStrikeShip(ctx);
        if (locked != null && locked.name != null && !locked.name.isBlank()) {
            return locked.name;
        }
        return "NO HOSTILE CONTACT SELECTED";
    }

    private static StrikePreflight buildTacticalStrikePreflight(GameContext ctx, String actionId) {
        CampaignState st = state(ctx);
        boolean infiniteStrikeStores = hasInfiniteTacticalStrikeStores(ctx);
        String id = (actionId == null) ? "" : actionId.trim().toUpperCase(Locale.US);
        String targetLabel = tacticalStrikeTargetLabel(ctx);
        boolean hostile = hasAnyTacticalStrikeTarget(ctx);
        StrikeCost cost = strikeCost(ctx, st, id, "Tracked", true);
        int ammoCost = cost.ammo;
        int fuelCost = cost.fuel;
        int supplyCost = cost.supplies;
        int chargeCost = cost.charges;
        String effect = "";
        String retaliation = "";
        String reason = "";
        if (ctx == null || st == null) {
            return new StrikePreflight(id, targetLabel, false, "strike systems offline", 0, 0, 0, 0, "", "");
        }
        switch (id) {
            case "TORPEDO_STRIKE" -> {
                effect = "Inbound torpedo homes on the selected hostile contact and slams the heaviest target.";
                retaliation = "High exposure spike while hostile contacts react.";
                if (!hostile) reason = "no hostile contact selected";
                else if (!infiniteStrikeStores && st.strategicTorpedoCharges <= 0) reason = "no torpedo strikes ready";
                else if (!infiniteStrikeStores && st.campaignAmmo < ammoCost) reason = "insufficient ammo";
                else if (!infiniteStrikeStores && st.campaignFuel < fuelCost) reason = "insufficient fuel";
            }
            case "CARRIER_SORTIE" -> {
                effect = "Strike craft dash to the contact, dump heavy ordnance, and immediately egress.";
                retaliation = "High strike heat and hostile alert increase.";
                int sortieCap = strategicSortieCapacity(ctx);
                if (!hostile) reason = "no hostile contact selected";
                else if (!infiniteStrikeStores && sortieCap <= 0) reason = "no carrier sorties available";
                else if (!infiniteStrikeStores && st.strategicSortiesLaunched >= sortieCap) reason = "sortie decks committed";
                else if (!infiniteStrikeStores && st.campaignAmmo < ammoCost) reason = "insufficient ammo";
                else if (!infiniteStrikeStores && st.campaignFuel < fuelCost) reason = "insufficient fuel";
                else if (!infiniteStrikeStores && st.campaignSupplies < supplyCost) reason = "insufficient supplies";
            }
            case "ATOMIC_STRIKE" -> {
                effect = "Large blast radius strike scourges the selected hostile contact.";
                retaliation = "Severe theater consequence and major exposure increase.";
                if (!hostile) reason = "no hostile contact selected";
                else if (!infiniteStrikeStores && st.strategicAtomicCharges <= 0) reason = "atomic option unavailable";
                else if (!infiniteStrikeStores && st.campaignAmmo < ammoCost) reason = "insufficient ammo";
                else if (!infiniteStrikeStores && st.campaignFuel < fuelCost) reason = "insufficient fuel";
                else if (!infiniteStrikeStores && st.campaignSupplies < supplyCost) reason = "insufficient supplies";
            }
            default -> reason = "unknown strike action";
        }
        if (infiniteStrikeStores) {
            ammoCost = 0;
            fuelCost = 0;
            supplyCost = 0;
            chargeCost = 0;
        }
        return new StrikePreflight(id, targetLabel, reason.isBlank(), reason, ammoCost, fuelCost, supplyCost, chargeCost, effect, retaliation);
    }

    private static boolean tacticalStrikeTargetReady(GameContext ctx, String actionId) {
        return buildTacticalStrikePreflight(ctx, actionId).valid;
    }

    private static StrategicTaskForce selectedTacticalStrikeTaskForce(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return null;
        Ship ship = selectedTacticalStrikeShip(ctx);
        if (ship != null) {
            for (StrategicTaskForce taskForce : st.strategicTaskForces) {
                if (taskForce != null && taskForce.hostile && taskForce.spawnedShipIds.contains(ship.id)) {
                    return taskForce;
                }
            }
            return nearestHostileStrategicTaskForce(ctx, ship.x, ship.y, 260.0);
        }
        if (!hasTacticalHostileStrikeSelection(ctx)) {
            return null;
        }
        return nearestHostileStrategicTaskForce(ctx, ctx.ui.tacticalMapSelectionX, ctx.ui.tacticalMapSelectionY, 260.0);
    }

    private static Ship selectedTacticalStrikeShip(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || ctx.player == null || ctx.ships == null) return null;
        if (hasTacticalHostileStrikeSelection(ctx)) {
            Ship best = null;
            double bestD2 = 180.0 * 180.0;
            for (Ship ship : ctx.ships) {
                if (ship == null || ship == ctx.player || !ship.alive || ship.dying || ship.hp <= 0) continue;
                if (ship.faction == null || ship.faction.isFriendlyTo(ctx.player.faction)) continue;
                double d2 = GameMath.dist2(ship.x, ship.y, ctx.ui.tacticalMapSelectionX, ctx.ui.tacticalMapSelectionY);
                if (d2 > bestD2) continue;
                if (best == null || d2 < bestD2) {
                    best = ship;
                    bestD2 = d2;
                }
            }
            if (best != null) return best;
        }
        return tacticalLockedHostileStrikeShip(ctx);
    }

    private static List<Ship> tacticalStrikeHostileShips(GameContext ctx) {
        ArrayList<Ship> out = new ArrayList<>();
        if (ctx == null || ctx.ships == null || ctx.player == null || ctx.player.faction == null) return out;
        for (Ship ship : ctx.ships) {
            if (ship == null || ship == ctx.player || !ship.alive || ship.dying || ship.hp <= 0) continue;
            if (ship.faction == null || ship.faction.isFriendlyTo(ctx.player.faction)) continue;
            out.add(ship);
        }
        return out;
    }

    private static Ship bestTacticalStrikeTarget(GameContext ctx, StrategicTaskForce taskForce, List<Ship> hostiles, double targetX, double targetY) {
        if (hostiles == null || hostiles.isEmpty()) return null;
        Ship selectedShip = selectedTacticalStrikeShip(ctx);
        if (selectedShip != null && hostiles.contains(selectedShip)) return selectedShip;
        Ship best = null;
        double bestScore = Double.NEGATIVE_INFINITY;
        for (Ship ship : hostiles) {
            if (ship == null) continue;
            double score = strategicShipStrength(ship) * 1.35 - Math.hypot(ship.x - targetX, ship.y - targetY) * 0.02;
            if (taskForce != null && taskForce.spawnedShipIds.contains(ship.id)) score += 40.0;
            if (best == null || score > bestScore) {
                best = ship;
                bestScore = score;
            }
        }
        return best;
    }

    private static Ship closestTacticalHostileToPoint(List<Ship> hostiles, double x, double y) {
        if (hostiles == null || hostiles.isEmpty()) return null;
        Ship best = null;
        double bestD2 = Double.POSITIVE_INFINITY;
        for (Ship ship : hostiles) {
            if (ship == null) continue;
            double d2 = GameMath.dist2(ship.x, ship.y, x, y);
            if (best == null || d2 < bestD2) {
                best = ship;
                bestD2 = d2;
            }
        }
        return best;
    }

    private static void applyTacticalStrikeTaskForceDamage(CampaignState st, StrategicTaskForce taskForce, double damageBudget) {
        if (st == null || taskForce == null || damageBudget <= 0.0) return;
        taskForce.currentStrength = Math.max(0.0, taskForce.currentStrength - damageBudget);
        taskForce.disruptionRemainingSec = Math.max(taskForce.disruptionRemainingSec, 18.0);
        if (taskForce.currentStrength <= 1.0) {
            taskForce.currentStrength = 0.0;
            taskForce.encounterResolved = true;
            taskForce.encounterSpawned = false;
            taskForce.spawnedShipIds.clear();
        }
    }

    private static void applyTacticalStrikeShipDamage(GameContext ctx, Ship ship, int damage, double impactX, double impactY) {
        if (ctx == null || ship == null || damage <= 0) return;
        double durabilityBefore = Math.max(0.0, ship.hp) + Math.max(0.0, ship.shield);
        ship.takeDamage(damage, impactX, impactY);
        double durabilityAfter = Math.max(0.0, ship.hp) + Math.max(0.0, ship.shield);
        double guaranteedLoss = Math.max(10.0, damage * 0.40);
        if (durabilityAfter > durabilityBefore - 1.0 && durabilityBefore > 0.0) {
            double remainingLoss = Math.min(durabilityBefore, guaranteedLoss);
            if (ship.shield > 0.0) {
                double stripped = Math.min(ship.shield, remainingLoss);
                ship.shield = Math.max(0.0, ship.shield - stripped);
                remainingLoss -= stripped;
            }
            if (remainingLoss > 0.0) {
                ship.hp = Math.max(0, ship.hp - (int) Math.ceil(remainingLoss));
            }
            if (ship.hp <= 0) {
                ship.hp = 0;
                ship.alive = false;
                ship.dying = true;
            }
        }
        Explosion.spawnDestabilizerPulse(impactX, impactY, Math.max(140.0, ship.radius * 2.6));
    }

    private static Missile spawnTacticalStrikeMissile(GameContext ctx,
                                                      StrategicStrikePayload payload,
                                                      Ship target,
                                                      double targetX,
                                                      double targetY,
                                                      double lateralOffset,
                                                      int damage,
                                                      double blastRadius) {
        if (ctx == null || ctx.projectiles == null || target == null) return null;
        double sourceX = (ctx.player == null) ? targetX - 1400.0 : ctx.player.x;
        double sourceY = (ctx.player == null) ? targetY : ctx.player.y;
        double dx = targetX - sourceX;
        double dy = targetY - sourceY;
        double len = Math.max(1.0, Math.hypot(dx, dy));
        double nx = dx / len;
        double ny = dy / len;
        double px = -ny;
        double py = nx;
        double minimumStandOff = Math.max(900.0, blastRadius + 320.0);
        double desiredStandOff = Math.max(minimumStandOff, Math.min(1800.0, len));
        double sx = targetX - nx * desiredStandOff + px * lateralOffset;
        double sy = targetY - ny * desiredStandOff + py * lateralOffset;
        double angle = Math.atan2(targetY - sy, targetX - sx);
        Missile missile = new Missile(
                sx,
                sy,
                angle,
                target,
                GameContext.DT,
                payload == StrategicStrikePayload.ATOMIC ? 620.0 : (payload == StrategicStrikePayload.TORPEDO ? 360.0 : 340.0),
                Math.toRadians(payload == StrategicStrikePayload.ATOMIC ? 520.0 : (payload == StrategicStrikePayload.TORPEDO ? 360.0 : 280.0)),
                Math.max(1, damage),
                900,
                payload == StrategicStrikePayload.ATOMIC ? 18.0 : 10.0,
                Faction.PLAYER);
        missile.role = payload == StrategicStrikePayload.TORPEDO
                ? Turret.MissileRole.ANTI_HEAVY
                : Turret.MissileRole.ANTI_MEDIUM;
        missile.blastRadius = Math.max(40.0, blastRadius);
        missile.splashDamageMul = payload == StrategicStrikePayload.ATOMIC ? 1.0 : 0.55;
        missile.visualScale = payload == StrategicStrikePayload.ATOMIC ? 2.2 : 1.35;
        missile.strikeVisual = switch (payload) {
            case TORPEDO -> Missile.StrikeVisual.TORPEDO;
            case ATOMIC -> Missile.StrikeVisual.ATOMIC;
            default -> Missile.StrikeVisual.DEFAULT;
        };
        missile.guidanceTicksRemaining = Missile.INFINITE_GUIDANCE_TICKS;
        ctx.projectiles.add(missile);
        if (payload == StrategicStrikePayload.TORPEDO) {
            AudioSystem.onTorpedoLaunch(ctx, ctx.player);
        } else {
            AudioSystem.onMissileLaunch(ctx, ctx.player);
        }
        return missile;
    }

    private static Ship spawnTacticalStrikeBomber(GameContext ctx, double x, double y, double angle, int index) {
        if (ctx == null || ctx.ships == null) return null;
        Ship bomber = new FleetShip(ShipRole.BOMBER, Faction.ALLY, x, y);
        bomber.name = "Blue Heavy Bomber " + Math.max(1, index);
        bomber.angle = angle;
        bomber.desiredSpeed = Math.max(bomber.desiredSpeed, bomber.desiredSpeedBase * 1.72);
        bomber.vx = Math.cos(angle) * bomber.desiredSpeed * 0.92;
        bomber.vy = Math.sin(angle) * bomber.desiredSpeed * 0.92;
        bomber.campaignMissionSubzone = (ctx.campaign == null) ? -1 : missionSubzoneForPoint(ctx, ctx.campaign.sector, x, y);
        ctx.ships.add(bomber);
        return bomber;
    }

    private static Ship largestTacticalHostileShip(GameContext ctx) {
        List<Ship> hostiles = tacticalStrikeHostileShips(ctx);
        Ship best = null;
        double bestStrength = Double.NEGATIVE_INFINITY;
        for (Ship ship : hostiles) {
            if (ship == null) continue;
            double s = strategicShipStrength(ship);
            if (best == null || s > bestStrength) {
                best = ship;
                bestStrength = s;
            }
        }
        return best;
    }

    private static boolean launchSelectedTacticalTorpedoStrike(GameContext ctx) {
        CampaignState st = state(ctx);
        boolean infiniteStrikeStores = hasInfiniteTacticalStrikeStores(ctx);
        StrikePreflight preflight = buildTacticalStrikePreflight(ctx, "TORPEDO_STRIKE");
        if (!preflight.valid) {
            recordStrikeDenial(ctx, preflight);
            EventSystem.showBanner(ctx, ("TORPEDO STRIKE  |  " + preflight.reason).toUpperCase(Locale.US), 1.2);
            return hasAnyTacticalStrikeTarget(ctx);
        }
        Ship explicitlySelectedShip = selectedTacticalStrikeShip(ctx);
        List<Ship> hostiles = tacticalStrikeHostileShips(ctx);
        StrategicTaskForce taskForce = selectedTacticalStrikeTaskForce(ctx);
        Ship lockedTarget = tacticalLockedHostileStrikeShip(ctx);
        double tx = hasTacticalHostileStrikeSelection(ctx)
                ? ctx.ui.tacticalMapSelectionX
                : (lockedTarget != null ? lockedTarget.x : (ctx.player == null ? 0.0 : ctx.player.x));
        double ty = hasTacticalHostileStrikeSelection(ctx)
                ? ctx.ui.tacticalMapSelectionY
                : (lockedTarget != null ? lockedTarget.y : (ctx.player == null ? 0.0 : ctx.player.y));
        Ship target = (explicitlySelectedShip != null && explicitlySelectedShip.alive && !explicitlySelectedShip.dying)
                ? explicitlySelectedShip
                : bestTacticalStrikeTarget(ctx, taskForce, hostiles, tx, ty);
        if (target == null) target = closestTacticalHostileToPoint(hostiles, tx, ty);
        if (target == null) {
            EventSystem.showBanner(ctx, "TORPEDO STRIKE  |  NO HOSTILE HULLS AT SELECTED CONTACT", 1.2);
            return hasAnyTacticalStrikeTarget(ctx);
        }
        if (!infiniteStrikeStores) {
            st.strategicTorpedoCharges--;
            st.campaignAmmo = Math.max(0, st.campaignAmmo - preflight.ammoCost);
            st.campaignFuel = Math.max(0, st.campaignFuel - preflight.fuelCost);
        }
        double damageBudget = torpedoStrikeDamageBudget(target);
        Missile missile = spawnTacticalStrikeMissile(ctx, StrategicStrikePayload.TORPEDO, target, target.x, target.y, 0.0,
                Math.max(18, (int) Math.round(damageBudget)), Math.max(90.0, target.radius * 2.2));
        if (missile == null) {
            if (!infiniteStrikeStores) {
                st.strategicTorpedoCharges++;
                st.campaignAmmo += preflight.ammoCost;
                st.campaignFuel += preflight.fuelCost;
            }
            EventSystem.showBanner(ctx, "TORPEDO STRIKE  |  LAUNCH FAILED", 1.2);
            return false;
        }
        st.strategicExposureLevel = MathUtil.clamp(st.strategicExposureLevel + 4.0, 0.0, 100.0);
        st.enemyAlertLevel = MathUtil.clamp(st.enemyAlertLevel + 6.0, 0.0, 100.0);
        setLastStrikeReport(st, "TORPEDO", target.name == null ? tacticalStrikeTargetLabel(ctx) : target.name, 0.0, false, false);
        st.lastStrikeReportDetail = "Result: torpedo object inbound  |  Damage resolves on impact";
        noteStrikeBattleEvent(st, "TORPEDO", target.name == null ? tacticalStrikeTargetLabel(ctx) : target.name,
                "Inbound torpedo battle event; damage applies only if the object reaches the target");
        EventSystem.showBanner(ctx, "TACTICAL TORPEDO INBOUND: " + tacticalStrikeTargetLabel(ctx).toUpperCase(Locale.US), 1.4);
        return true;
    }

    private static double torpedoStrikeDamageBudget(Ship target) {
        if (target == null) return 220.0;
        double durability = Math.max(1.0, target.hp + Math.max(0.0, target.shield));
        double roleFloor = Math.max(target.hpMax * 0.54, strategicShipStrength(target) * 0.68);
        double killMul = isBattleshipClassOrGreater(target) ? 2.20 : 1.35;
        return Math.max(roleFloor, durability * killMul);
    }

    private static boolean isBattleshipClassOrGreater(Ship ship) {
        if (ship == null || ship.role == null) return false;
        if (ship.role.isTitanOrMothership()) return true;
        return switch (ship.role) {
            case BATTLESHIP, DREADNOUGHT, SUPERSHIP -> true;
            default -> false;
        };
    }

    private static boolean launchSelectedTacticalSortie(GameContext ctx) {
        CampaignState st = state(ctx);
        boolean infiniteStrikeStores = hasInfiniteTacticalStrikeStores(ctx);
        StrikePreflight preflight = buildTacticalStrikePreflight(ctx, "CARRIER_SORTIE");
        if (!preflight.valid) {
            recordStrikeDenial(ctx, preflight);
            EventSystem.showBanner(ctx, ("CARRIER SORTIE  |  " + preflight.reason).toUpperCase(Locale.US), 1.2);
            return hasAnyTacticalStrikeTarget(ctx);
        }
        Ship explicitlySelectedShip = selectedTacticalStrikeShip(ctx);
        List<Ship> hostiles = tacticalStrikeHostileShips(ctx);
        if (explicitlySelectedShip != null && explicitlySelectedShip.alive && !explicitlySelectedShip.dying) {
            hostiles.removeIf(ship -> ship != explicitlySelectedShip);
            if (hostiles.isEmpty()) hostiles.add(explicitlySelectedShip);
        }
        if (hostiles.isEmpty()) {
            EventSystem.showBanner(ctx, "CARRIER SORTIE  |  NO HOSTILE HULLS AT SELECTED CONTACT", 1.2);
            return hasAnyTacticalStrikeTarget(ctx);
        }
        StrategicTaskForce taskForce = selectedTacticalStrikeTaskForce(ctx);
        if (!infiniteStrikeStores) {
            st.strategicSortiesLaunched++;
            st.campaignAmmo = Math.max(0, st.campaignAmmo - preflight.ammoCost);
            st.campaignFuel = Math.max(0, st.campaignFuel - preflight.fuelCost);
            st.campaignSupplies = Math.max(0, st.campaignSupplies - preflight.supplyCost);
        }
        Ship lockedTarget = tacticalLockedHostileStrikeShip(ctx);
        double tx = hasTacticalHostileStrikeSelection(ctx)
                ? ctx.ui.tacticalMapSelectionX
                : (lockedTarget != null ? lockedTarget.x : ctx.player.x);
        double ty = hasTacticalHostileStrikeSelection(ctx)
                ? ctx.ui.tacticalMapSelectionY
                : (lockedTarget != null ? lockedTarget.y : ctx.player.y);
        Ship primary = bestTacticalStrikeTarget(ctx, taskForce, hostiles, tx, ty);
        if (primary == null) primary = hostiles.get(0);
        double sourceX = ctx.player == null ? tx - 740.0 : ctx.player.x;
        double sourceY = ctx.player == null ? ty : ctx.player.y;
        double angle = Math.atan2(primary.y - sourceY, primary.x - sourceX);
        final int bomberCount = 6;
        int spawnedBombers = 0;
        for (int i = 0; i < bomberCount; i++) {
            double offset = (i - (bomberCount - 1) * 0.5) * 88.0;
            double px = -Math.sin(angle);
            double py = Math.cos(angle);
            Ship bomber = spawnTacticalStrikeBomber(ctx,
                    primary.x - Math.cos(angle) * 4800.0 + px * offset,
                    primary.y - Math.sin(angle) * 4800.0 + py * offset,
                    angle,
                    i + 1);
            if (bomber != null) {
                spawnedBombers++;
                st.tacticalStrikeBomberTargetIds.put(bomber.id, primary.id);
                st.tacticalStrikeBomberPayloadsRemaining.put(bomber.id, 2);
                st.tacticalStrikeBomberEgressTimers.put(bomber.id, -1.0);
            }
        }
        if (spawnedBombers <= 0) {
            if (!infiniteStrikeStores) {
                st.strategicSortiesLaunched = Math.max(0, st.strategicSortiesLaunched - 1);
                st.campaignAmmo += preflight.ammoCost;
                st.campaignFuel += preflight.fuelCost;
                st.campaignSupplies += preflight.supplyCost;
            }
            EventSystem.showBanner(ctx, "CARRIER SORTIE  |  LAUNCH FAILED", 1.2);
            return false;
        }
        st.strategicExposureLevel = MathUtil.clamp(st.strategicExposureLevel + 5.5, 0.0, 100.0);
        st.enemyAlertLevel = MathUtil.clamp(st.enemyAlertLevel + 7.5, 0.0, 100.0);
        setLastStrikeReport(st, "SORTIE", tacticalStrikeTargetLabel(ctx), 0.0, false, false);
        st.lastStrikeReportDetail = "Result: heavy bombers inbound  |  Payloads resolve on impact";
        noteStrikeBattleEvent(st, "SORTIE", tacticalStrikeTargetLabel(ctx),
                "Heavy bomber strike event; bombers drop payloads then egress under enemy fire");
        updateTacticalStrikeBombers(ctx, st, 0.0);
        EventSystem.showBanner(ctx, "TACTICAL SORTIE INBOUND: BOMBERS COMMITTED", 1.4);
        return true;
    }

    private static boolean launchSelectedTacticalAtomicStrike(GameContext ctx) {
        CampaignState st = state(ctx);
        boolean infiniteStrikeStores = hasInfiniteTacticalStrikeStores(ctx);
        StrikePreflight preflight = buildTacticalStrikePreflight(ctx, "ATOMIC_STRIKE");
        if (!preflight.valid) {
            recordStrikeDenial(ctx, preflight);
            EventSystem.showBanner(ctx, ("ATOMIC STRIKE  |  " + preflight.reason).toUpperCase(Locale.US), 1.2);
            return hasAnyTacticalStrikeTarget(ctx);
        }
        Ship explicitlySelectedShip = selectedTacticalStrikeShip(ctx);
        List<Ship> hostiles = tacticalStrikeHostileShips(ctx);
        if (explicitlySelectedShip != null && explicitlySelectedShip.alive && !explicitlySelectedShip.dying) {
            hostiles.removeIf(ship -> ship != explicitlySelectedShip);
            if (hostiles.isEmpty()) hostiles.add(explicitlySelectedShip);
        }
        if (hostiles.isEmpty()) {
            EventSystem.showBanner(ctx, "ATOMIC STRIKE  |  NO HOSTILE HULLS AT SELECTED CONTACT", 1.2);
            return hasAnyTacticalStrikeTarget(ctx);
        }
        StrategicTaskForce taskForce = selectedTacticalStrikeTaskForce(ctx);
        if (!infiniteStrikeStores) {
            st.strategicAtomicCharges--;
            st.campaignAmmo = Math.max(0, st.campaignAmmo - preflight.ammoCost);
            st.campaignFuel = Math.max(0, st.campaignFuel - preflight.fuelCost);
            st.campaignSupplies = Math.max(0, st.campaignSupplies - preflight.supplyCost);
        }
        Ship lockedTarget = tacticalLockedHostileStrikeShip(ctx);
        double tx = hasTacticalHostileStrikeSelection(ctx)
                ? ctx.ui.tacticalMapSelectionX
                : (lockedTarget != null ? lockedTarget.x : ctx.player.x);
        double ty = hasTacticalHostileStrikeSelection(ctx)
                ? ctx.ui.tacticalMapSelectionY
                : (lockedTarget != null ? lockedTarget.y : ctx.player.y);
        double blastRadius = 640.0;
        Ship target = largestTacticalHostileShip(ctx);
        if (target == null) target = bestTacticalStrikeTarget(ctx, taskForce, hostiles, tx, ty);
        if (target == null) target = hostiles.get(0);
        Missile missile = spawnTacticalStrikeMissile(ctx, StrategicStrikePayload.ATOMIC, target, tx, ty, 0.0,
                Math.max(42, (int) Math.round(target.hpMax * 0.72)), blastRadius);
        if (missile == null) {
            if (!infiniteStrikeStores) {
                st.strategicAtomicCharges++;
                st.campaignAmmo += preflight.ammoCost;
                st.campaignFuel += preflight.fuelCost;
                st.campaignSupplies += preflight.supplyCost;
            }
            EventSystem.showBanner(ctx, "ATOMIC STRIKE  |  LAUNCH FAILED", 1.2);
            return false;
        }
        st.strategicExposureLevel = MathUtil.clamp(st.strategicExposureLevel + 18.0, 0.0, 100.0);
        st.enemyAlertLevel = MathUtil.clamp(st.enemyAlertLevel + 20.0, 0.0, 100.0);
        setLastStrikeReport(st, "ATOMIC", tacticalStrikeTargetLabel(ctx), 0.0, false, true);
        st.lastStrikeReportDetail = "Result: atomic device inbound  |  Detonation resolves on impact";
        noteStrikeBattleEvent(st, "ATOMIC", tacticalStrikeTargetLabel(ctx),
                "Atomic device strike event; blast resolves at the visible detonation point");
        EventSystem.showBanner(ctx, "TACTICAL ATOMIC DEVICE INBOUND", 1.6);
        return true;
    }

    private static boolean hasInfiniteTacticalStrikeStores(GameContext ctx) {
        return ctx != null
                && ctx.config != null
                && ctx.config.mode == GameMode.SHOOTING_RANGE
                && ctx.player != null
                && ctx.player.role == ShipRole.MOTHERSHIP;
    }

    private static boolean tacticalStrikeTabExposesActions(GameContext ctx) {
        if (ctx == null || ctx.config == null || ctx.player == null) return false;
        if (ctx.player.role != ShipRole.MOTHERSHIP) return false;
        return ctx.config.mode == GameMode.CUSTOM_BATTLES
                || ctx.config.mode == GameMode.SHOOTING_RANGE;
    }

    public static boolean confirmCampaignAction(GameContext ctx) {
        if (ctx == null || ctx.ui == null || !ctx.ui.campaignActionConfirm.active) return false;
        String actionId = ctx.ui.campaignActionConfirm.actionId;
        ctx.ui.clearCampaignActionConfirm();
        if ("ATOMIC_STRIKE".equalsIgnoreCase(actionId)) {
            return isMissionTacticalStrikeMode(ctx)
                    ? launchSelectedTacticalAtomicStrike(ctx)
                    : launchSelectedCampaignAtomicStrike(ctx);
        }
        return false;
    }

    public static void cancelCampaignActionConfirm(GameContext ctx) {
        if (ctx == null || ctx.ui == null) return;
        ctx.ui.clearCampaignActionConfirm();
    }

    public static CampaignLocation nearestCampaignLocation(GameContext ctx, double x, double y, double maxDist) {
        CampaignState st = state(ctx);
        if (st == null) return null;
        CampaignLocation best = null;
        double bestD2 = Math.max(1.0, maxDist) * Math.max(1.0, maxDist);
        for (CampaignLocation location : allCampaignLocations(st)) {
            if (location == null || !location.discovered) continue;
            double d2 = GameMath.dist2(x, y, location.x, location.y);
            if (d2 > bestD2) continue;
            if (best == null || d2 < bestD2) {
                best = location;
                bestD2 = d2;
            }
        }
        return best;
    }

    public static boolean selectCampaignLocation(GameContext ctx, double x, double y) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !isStrategicGalaxyMapMode(ctx)) return false;
        CampaignLocation location = nearestCampaignLocation(ctx, x, y, 260.0);
        if (location == null) return false;
        st.selectedGalaxyLocationId = location.id;
        st.selectedFreeGalaxyTargetX = Double.NaN;
        st.selectedFreeGalaxyTargetY = Double.NaN;
        if (st.commandSchoolTraining) st.commandSchoolLastActionId = "SELECT_LOCATION";
        EventSystem.showBanner(ctx, "DESTINATION SELECTED: " + location.name.toUpperCase(Locale.US), 1.2);
        return true;
    }

    public static boolean selectCampaignFreeTravelTarget(GameContext ctx, double x, double y) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !isStrategicGalaxyMapMode(ctx)) return false;
        st.selectedGalaxyLocationId = "";
        st.selectedFreeGalaxyTargetX = GameMath.clamp(x, 0.0, ctx.WORLD_W);
        st.selectedFreeGalaxyTargetY = GameMath.clamp(y, 0.0, ctx.WORLD_H);
        EventSystem.showBanner(ctx,
                "FREE COURSE SELECTED  X " + (int) Math.round(st.selectedFreeGalaxyTargetX)
                        + "  Y " + (int) Math.round(st.selectedFreeGalaxyTargetY),
                1.2);
        return true;
    }

    public static boolean bookmarkSelectedStrategicTarget(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !isStrategicGalaxyMapMode(ctx)) return false;
        CampaignMapBookmark bookmark = buildSelectedStrategicBookmark(ctx, st);
        if (bookmark == null) {
            EventSystem.showBanner(ctx, "SELECT A LOCATION, CONTACT, OR FREE COURSE BEFORE BOOKMARKING", 1.2);
            return true;
        }
        addOrReplaceCampaignMapBookmark(st, bookmark);
        UISystem.addPing(ctx, bookmark.x, bookmark.y, 2.2);
        EventSystem.showBanner(ctx, "BOOKMARKED: " + bookmark.label.toUpperCase(Locale.US), 1.2);
        return true;
    }

    public static boolean selectNextCampaignMapBookmark(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || st.campaignMapBookmarks.isEmpty()) return false;
        int next = Math.floorMod(st.selectedCampaignMapBookmarkIndex + 1, st.campaignMapBookmarks.size());
        st.selectedCampaignMapBookmarkIndex = next;
        CampaignMapBookmark bookmark = st.campaignMapBookmarks.get(next);
        CampaignLocation location = bookmark.locationId.isBlank() ? null : campaignLocationById(st, bookmark.locationId);
        if (location != null) {
            st.selectedGalaxyLocationId = location.id;
            st.selectedFreeGalaxyTargetX = Double.NaN;
            st.selectedFreeGalaxyTargetY = Double.NaN;
            UISystem.addPing(ctx, location.x, location.y, 2.2);
        } else {
            st.selectedGalaxyLocationId = "";
            st.selectedFreeGalaxyTargetX = GameMath.clamp(bookmark.x, 0.0, ctx.WORLD_W);
            st.selectedFreeGalaxyTargetY = GameMath.clamp(bookmark.y, 0.0, ctx.WORLD_H);
            UISystem.addPing(ctx, st.selectedFreeGalaxyTargetX, st.selectedFreeGalaxyTargetY, 2.2);
        }
        EventSystem.showBanner(ctx, "BOOKMARK: " + bookmark.label.toUpperCase(Locale.US), 1.1);
        return true;
    }

    public static List<String> campaignMapBookmarkLines(GameContext ctx) {
        CampaignState st = state(ctx);
        if (st == null || st.campaignMapBookmarks.isEmpty()) return List.of("Bookmarks: none");
        ArrayList<String> out = new ArrayList<>();
        out.add("Bookmarks: " + st.campaignMapBookmarks.size());
        int start = Math.max(0, Math.min(st.campaignMapBookmarks.size() - 1, st.selectedCampaignMapBookmarkIndex));
        for (int i = 0; i < st.campaignMapBookmarks.size() && out.size() < 6; i++) {
            int idx = (start + i) % st.campaignMapBookmarks.size();
            CampaignMapBookmark bookmark = st.campaignMapBookmarks.get(idx);
            String selected = idx == st.selectedCampaignMapBookmarkIndex ? "* " : "";
            out.add(selected + bookmark.category + ": " + bookmark.label
                    + "  X " + (int) Math.round(bookmark.x)
                    + " Y " + (int) Math.round(bookmark.y));
        }
        return out;
    }

    public static boolean queueSelectedRouteStop(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !isStrategicGalaxyMapMode(ctx)) return false;
        CampaignMapBookmark target = buildSelectedStrategicBookmark(ctx, st);
        if (target == null) {
            EventSystem.showBanner(ctx, "SELECT A LOCATION, CONTACT, OR FREE COURSE BEFORE QUEUING", 1.2);
            return true;
        }
        CampaignLocation location = target.locationId.isBlank() ? null : campaignLocationById(st, target.locationId);
        CampaignRouteQueueStop stop = new CampaignRouteQueueStop(
                target.label,
                target.category,
                target.locationId,
                target.x,
                target.y,
                routeQueueConditionFor(location, target));
        addOrReplaceCampaignRouteQueueStop(st, stop);
        UISystem.addPing(ctx, stop.x, stop.y, 2.1);
        EventSystem.showBanner(ctx, "QUEUED STOP: " + stop.label.toUpperCase(Locale.US)
                + "  |  " + stop.condition, 1.2);
        return true;
    }

    public static boolean startQueuedRoute(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !isStrategicGalaxyMapMode(ctx)) return false;
        if (st.galaxyTravel.traveling) {
            EventSystem.showBanner(ctx, "ROUTE QUEUE WAITING FOR CURRENT COURSE", 1.1);
            return true;
        }
        return startNextQueuedRouteStop(ctx, st, true);
    }

    public static boolean clearQueuedRouteStops(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return false;
        if (st.campaignRouteQueue.isEmpty()) return false;
        st.campaignRouteQueue.clear();
        EventSystem.showBanner(ctx, "ROUTE QUEUE CLEARED", 1.1);
        return true;
    }

    public static List<String> campaignRouteQueueLines(GameContext ctx) {
        CampaignState st = state(ctx);
        if (st == null || st.campaignRouteQueue.isEmpty()) return List.of("Route Queue: none");
        ArrayList<String> out = new ArrayList<>();
        out.add("Route Queue: " + st.campaignRouteQueue.size() + " stop" + (st.campaignRouteQueue.size() == 1 ? "" : "s"));
        for (int i = 0; i < st.campaignRouteQueue.size() && out.size() < 5; i++) {
            CampaignRouteQueueStop stop = st.campaignRouteQueue.get(i);
            out.add((i + 1) + ". " + stop.category + ": " + stop.label
                    + "  |  " + stop.condition
                    + "  X " + (int) Math.round(stop.x)
                    + " Y " + (int) Math.round(stop.y));
        }
        return out;
    }

    private static CampaignMapBookmark buildSelectedStrategicBookmark(GameContext ctx, CampaignState st) {
        CampaignLocation selected = selectedCampaignLocation(ctx);
        if (selected != null) {
            String category = bookmarkCategoryFor(selected);
            return new CampaignMapBookmark(selected.name, category, selected.id, selected.x, selected.y);
        }
        if (hasSelectedCampaignContactTarget(ctx)) {
            String category = selectedCampaignContactHostile(ctx) ? "Hostile Track" : "Ping";
            return new CampaignMapBookmark(selectedCampaignContactLabel(ctx), category, "",
                    ctx.ui.selectedCampaignContactX, ctx.ui.selectedCampaignContactY);
        }
        if (hasSelectedFreeTravelTarget(ctx)) {
            return new CampaignMapBookmark("Free Course", "Staging",
                    "", selectedFreeTravelTargetX(ctx), selectedFreeTravelTargetY(ctx));
        }
        return null;
    }

    private static String bookmarkCategoryFor(CampaignLocation location) {
        if (location == null) return "Ping";
        if (!location.services.isEmpty()) return "Staging";
        return switch (location.type) {
            case RESOURCE_ZONE -> "Mining";
            case SALVAGE_FIELD -> "Salvage";
            case REPAIR_SITE -> "Repair";
            case HIDDEN_CACHE -> "Cache";
            case DISTRESS_SIGNAL -> "Rescue";
            case ENEMY_ACTIVITY -> "Hazard";
            case MAIN_MISSION -> "Objective";
            case STORY_EVENT -> "Intel";
        };
    }

    private static void addOrReplaceCampaignMapBookmark(CampaignState st, CampaignMapBookmark bookmark) {
        if (st == null || bookmark == null) return;
        for (int i = 0; i < st.campaignMapBookmarks.size(); i++) {
            CampaignMapBookmark existing = st.campaignMapBookmarks.get(i);
            boolean sameLocation = !bookmark.locationId.isBlank() && bookmark.locationId.equals(existing.locationId);
            boolean samePoint = bookmark.locationId.isBlank() && existing.locationId.isBlank()
                    && Math.hypot(bookmark.x - existing.x, bookmark.y - existing.y) <= 24.0;
            if (sameLocation || samePoint) {
                st.campaignMapBookmarks.set(i, bookmark);
                st.selectedCampaignMapBookmarkIndex = i;
                return;
            }
        }
        st.campaignMapBookmarks.add(bookmark);
        while (st.campaignMapBookmarks.size() > 18) st.campaignMapBookmarks.remove(0);
        st.selectedCampaignMapBookmarkIndex = st.campaignMapBookmarks.size() - 1;
    }

    private static String routeQueueConditionFor(CampaignLocation location, CampaignMapBookmark target) {
        if (location == null) return "ALWAYS";
        if (location.type == CampaignLocationType.REPAIR_SITE
                || location.services.contains(HubService.FUEL)
                || location.services.contains(HubService.SUPPLY)
                || location.services.contains(HubService.REPAIR)
                || location.services.contains(HubService.TRADE)) {
            return "IF LOW STORES";
        }
        if (location.type == CampaignLocationType.ENEMY_ACTIVITY || location.threatLevel >= 0.45f) {
            return "IF FLEET READY";
        }
        return "ALWAYS";
    }

    private static void addOrReplaceCampaignRouteQueueStop(CampaignState st, CampaignRouteQueueStop stop) {
        if (st == null || stop == null) return;
        for (int i = 0; i < st.campaignRouteQueue.size(); i++) {
            CampaignRouteQueueStop existing = st.campaignRouteQueue.get(i);
            boolean sameLocation = !stop.locationId.isBlank() && stop.locationId.equals(existing.locationId);
            boolean samePoint = stop.locationId.isBlank() && existing.locationId.isBlank()
                    && Math.hypot(stop.x - existing.x, stop.y - existing.y) <= 24.0;
            if (sameLocation || samePoint) {
                st.campaignRouteQueue.set(i, stop);
                return;
            }
        }
        st.campaignRouteQueue.add(stop);
        while (st.campaignRouteQueue.size() > 8) st.campaignRouteQueue.remove(0);
    }

    private static boolean startNextQueuedRouteStop(GameContext ctx, CampaignState st, boolean announceEmpty) {
        if (ctx == null || st == null) return false;
        while (!st.campaignRouteQueue.isEmpty()) {
            CampaignRouteQueueStop stop = st.campaignRouteQueue.remove(0);
            if (!routeQueueConditionAllowsStop(ctx, st, stop)) {
                EventSystem.showBanner(ctx, "SKIPPED QUEUED STOP: " + stop.label.toUpperCase(Locale.US)
                        + "  |  " + stop.condition, 1.0);
                continue;
            }
            plotQueuedRouteStop(ctx, st, stop);
            boolean started = startTravelToSelectedLocation(ctx);
            if (started) {
                EventSystem.showBanner(ctx, "ROUTE QUEUE ADVANCING: " + stop.label.toUpperCase(Locale.US), 1.2);
                return true;
            }
            st.campaignRouteQueue.add(0, stop);
            EventSystem.showBanner(ctx, "ROUTE QUEUE HOLDING: " + stop.label.toUpperCase(Locale.US), 1.2);
            return false;
        }
        if (announceEmpty) EventSystem.showBanner(ctx, "ROUTE QUEUE EMPTY", 1.0);
        return false;
    }

    private static boolean routeQueueConditionAllowsStop(GameContext ctx, CampaignState st, CampaignRouteQueueStop stop) {
        if (st == null || stop == null) return false;
        String condition = stop.condition.toUpperCase(Locale.US);
        if (condition.contains("LOW STORES")) {
            return campaignFuel(ctx) < 42 || campaignSupplies(ctx) < 32 || st.campaignAmmo < 30;
        }
        if (condition.contains("FLEET READY")) {
            return campaignFuel(ctx) >= 20 && campaignSupplies(ctx) >= 16 && st.campaignAmmo >= 18
                    && st.fleetStrain < 82.0;
        }
        return true;
    }

    private static void plotQueuedRouteStop(GameContext ctx, CampaignState st, CampaignRouteQueueStop stop) {
        CampaignLocation location = stop.locationId.isBlank() ? null : campaignLocationById(st, stop.locationId);
        if (location != null) {
            st.selectedGalaxyLocationId = location.id;
            st.selectedFreeGalaxyTargetX = Double.NaN;
            st.selectedFreeGalaxyTargetY = Double.NaN;
            UISystem.addPing(ctx, location.x, location.y, 1.9);
            return;
        }
        st.selectedGalaxyLocationId = "";
        st.selectedFreeGalaxyTargetX = GameMath.clamp(stop.x, 0.0, ctx.WORLD_W);
        st.selectedFreeGalaxyTargetY = GameMath.clamp(stop.y, 0.0, ctx.WORLD_H);
        UISystem.addPing(ctx, st.selectedFreeGalaxyTargetX, st.selectedFreeGalaxyTargetY, 1.9);
    }

    private static void maybeAdvanceQueuedRouteAfterArrival(GameContext ctx, CampaignState st) {
        if (ctx == null || st == null || st.campaignRouteQueue.isEmpty() || st.galaxyTravel.traveling) return;
        if (st.galaxyEncounterActive) return;
        if (ctx.ui != null && (ctx.ui.strategicEncounterPrompt.active || ctx.ui.campaignHubMenu.active)) return;
        startNextQueuedRouteStop(ctx, st, false);
    }

    public static boolean startTravelToSelectedLocation(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !isStrategicGalaxyMapMode(ctx)) return false;
        CampaignLocation current = currentCampaignLocation(ctx);
        CampaignLocation destination = selectedCampaignLocation(ctx);
        if (destination == null) {
            return startTravelToFreeTarget(ctx, st, current);
        }
        ensureGalaxyFleetPosition(st, current);
        if (isWithinDockingRange(st, destination)) {
            st.dockedGalaxyLocationId = destination.id;
            st.currentGalaxyLocationId = destination.id;
            st.galaxyTravel.clear();
            if (shouldLaunchEncounterOnArrival(ctx, destination)) {
                beginCampaignArrivalEncounterChoice(ctx, st, destination);
            } else if (isOpenCampaignMissionHub(destination)) {
                resolveOpenCampaignMissionHubArrival(ctx, st, destination);
            } else {
                EventSystem.showBanner(ctx, "ALREADY AT " + destination.name.toUpperCase(Locale.US), 1.1);
            }
            return true;
        }
        double originX = st.playerGalaxyX;
        double originY = st.playerGalaxyY;
        double dist = Math.hypot(destination.x - originX, destination.y - originY);
        GalaxyRouteAssessment route = analyzeRoute(st, ctx, originX, originY, destination);
        String sustainWarning = routeSustainabilityWarning(ctx, st, route);
        if (!sustainWarning.isBlank()) {
            EventSystem.showBanner(ctx, "ROUTE WARNING: " + sustainWarning.toUpperCase(Locale.US), 1.8);
            return false;
        }
        st.galaxyTravel.originId = (current == null) ? st.currentGalaxyLocationId : current.id;
        st.galaxyTravel.destinationId = destination.id;
        st.galaxyTravel.destinationLabel = destination.name;
        st.galaxyTravel.progress = 0.0;
        st.galaxyTravel.durationSec = Math.max(8.0, route.durationSec);
        st.galaxyTravel.freeTravel = false;
        st.galaxyTravel.targetX = destination.x;
        st.galaxyTravel.targetY = destination.y;
        st.galaxyTravel.speed = Math.max(90.0, route.cruiseSpeed);
        st.galaxyTravel.interceptionRisk = (float) MathUtil.clamp(route.interceptionRisk, 0.0, 95.0);
        st.galaxyTravel.traveling = true;
        st.dockedGalaxyLocationId = "";
        resetTravelLegContactMeasurement(st);
        recordTransitVariation(ctx, st, originX, originY, destination.x, destination.y, destination.name, route);
        ensureRouteInterdictionPressure(ctx, st, originX, originY, destination.x, destination.y, route);
        if (st.galaxyTravel.interceptionRisk >= 45.0f) {
            AudioSystem.onStrategicMapEvent(ctx, "route_warning", destination.x, destination.y);
        }
        EventSystem.showBanner(ctx,
                "TRAVELING TO " + destination.name.toUpperCase(Locale.US)
                        + "  ETA " + (int) Math.ceil(st.galaxyTravel.durationSec) + "S"
                        + "  RISK " + (int) Math.round(st.galaxyTravel.interceptionRisk) + "%",
                1.5);
        recordStructuredCampaignEvent(ctx, st, "campaign.transition.travel_start",
                "from=" + safeTelemetryValue(st.galaxyTravel.originId)
                        + " to=" + safeTelemetryValue(destination.id)
                        + " label=" + safeTelemetryValue(destination.name)
                        + " durationSec=" + Math.round(st.galaxyTravel.durationSec)
                        + " risk=" + Math.round(st.galaxyTravel.interceptionRisk)
                        + " free=false");
        return true;
    }

    private static boolean startTravelToFreeTarget(GameContext ctx, CampaignState st, CampaignLocation current) {
        if (ctx == null || st == null || !hasSelectedFreeTravelTarget(ctx)) return false;
        ensureGalaxyFleetPosition(st, current);
        double targetX = GameMath.clamp(st.selectedFreeGalaxyTargetX, 0.0, ctx.WORLD_W);
        double targetY = GameMath.clamp(st.selectedFreeGalaxyTargetY, 0.0, ctx.WORLD_H);
        double dist = Math.hypot(targetX - st.playerGalaxyX, targetY - st.playerGalaxyY);
        if (dist <= 24.0) {
            EventSystem.showBanner(ctx, "COURSE ALREADY HELD AT SELECTED COORDINATES", 1.1);
            return true;
        }
        GalaxyRouteAssessment route = analyzeRouteToPoint(st, ctx, st.playerGalaxyX, st.playerGalaxyY, targetX, targetY, 0.18);
        String sustainWarning = routeSustainabilityWarning(ctx, st, route);
        if (!sustainWarning.isBlank()) {
            EventSystem.showBanner(ctx, "ROUTE WARNING: " + sustainWarning.toUpperCase(Locale.US), 1.8);
            return false;
        }
        st.galaxyTravel.originId = (current == null) ? st.currentGalaxyLocationId : current.id;
        st.galaxyTravel.destinationId = "";
        st.galaxyTravel.destinationLabel = "Free Course";
        st.galaxyTravel.progress = 0.0;
        st.galaxyTravel.durationSec = Math.max(8.0, route.durationSec);
        st.galaxyTravel.freeTravel = true;
        st.galaxyTravel.targetX = targetX;
        st.galaxyTravel.targetY = targetY;
        st.galaxyTravel.speed = Math.max(90.0, route.cruiseSpeed);
        st.galaxyTravel.interceptionRisk = (float) MathUtil.clamp(route.interceptionRisk, 0.0, 95.0);
        st.galaxyTravel.traveling = true;
        st.currentGalaxyLocationId = "";
        st.dockedGalaxyLocationId = "";
        resetTravelLegContactMeasurement(st);
        recordTransitVariation(ctx, st, st.playerGalaxyX, st.playerGalaxyY, targetX, targetY, "Free Course", route);
        ensureRouteInterdictionPressure(ctx, st, st.playerGalaxyX, st.playerGalaxyY, targetX, targetY, route);
        if (st.galaxyTravel.interceptionRisk >= 45.0f) {
            AudioSystem.onStrategicMapEvent(ctx, "route_warning", targetX, targetY);
        }
        EventSystem.showBanner(ctx,
                "FREE NAVIGATION ENGAGED  ETA " + (int) Math.ceil(st.galaxyTravel.durationSec) + "S"
                        + "  RISK " + (int) Math.round(st.galaxyTravel.interceptionRisk) + "%",
                1.5);
        recordStructuredCampaignEvent(ctx, st, "campaign.transition.travel_start",
                "from=" + safeTelemetryValue(st.galaxyTravel.originId)
                        + " to=free-course"
                        + " label=FreeCourse"
                        + " durationSec=" + Math.round(st.galaxyTravel.durationSec)
                        + " risk=" + Math.round(st.galaxyTravel.interceptionRisk)
                        + " free=true");
        return true;
    }

    private static void recordTransitVariation(GameContext ctx,
                                               CampaignState st,
                                               double originX,
                                               double originY,
                                               double targetX,
                                               double targetY,
                                               String destinationLabel,
                                               GalaxyRouteAssessment route) {
        if (ctx == null || st == null || route == null) return;
        int serial = Math.max(0, st.transitVariationSerial++);
        double midX = (originX + targetX) * 0.5;
        double midY = (originY + targetY) * 0.5;
        GalaxyRegionIdentity region = regionIdentityAt(ctx, midX, midY);
        String destination = (destinationLabel == null || destinationLabel.isBlank()) ? "the plotted route" : destinationLabel.trim();
        st.lastTransitStoryLine = "Transit Story  |  " + transitStoryFor(region, serial, destination);
        st.lastRegionalEventLine = "Regional Event  |  " + regionalEventFor(ctx, st, region, serial, route);
        st.lastRouteTrafficPatternLine = "Traffic Pattern  |  " + routeTrafficPatternFor(region, serial, route);
        st.lastContactChainLine = "Contact Chain  |  " + contactChainLineFor(st, region, serial, route);
        pushTheaterEvent(st, st.lastTransitStoryLine);
        pushTheaterEvent(st, st.lastContactChainLine);
    }

    private static String transitStoryFor(GalaxyRegionIdentity region, int serial, String destination) {
        int roll = Math.floorMod(serial, 4);
        return switch (region) {
            case SOUTHERN_SHELTER -> switch (roll) {
                case 0 -> "hub controllers thread Blue through refugee tenders toward " + destination;
                case 1 -> "miners trade ore-dust lane marks before the burn to " + destination;
                case 2 -> "repair crews report which civilian buoys still answer on approach to " + destination;
                default -> "green escorts swap safe-lane codes as the fleet clears for " + destination;
            };
            case CONTESTED_BELT -> switch (roll) {
                case 0 -> "convoy wreckage forces a wider dogleg before " + destination;
                case 1 -> "prospector scouts sell a half-clean path through sensor static toward " + destination;
                case 2 -> "a damaged relay repeats old clearance codes along the route to " + destination;
                default -> "neutral haulers go dark and leave only engine blooms on the way to " + destination;
            };
            case EARTHWARDED_NORTH -> switch (roll) {
                case 0 -> "blackout couriers mark patrol gaps on the final lanes toward " + destination;
                case 1 -> "resistance chatter hides inside customs noise before " + destination;
                case 2 -> "occupation sweeps force Blue to shadow a cold debris track toward " + destination;
                default -> "old Sol traffic buoys answer in fragments on approach to " + destination;
            };
        };
    }

    private static String regionalEventFor(GameContext ctx,
                                           CampaignState st,
                                           GalaxyRegionIdentity region,
                                           int serial,
                                           GalaxyRouteAssessment route) {
        double pressure = MathUtil.clamp((route == null ? 0.0 : route.northPressure), 0.0, 1.0);
        int roll = Math.floorMod(serial + (int) Math.round(pressure * 10.0), 4);
        String theater = regionIdentityTitleFor(ctx, st.playerGalaxyX, st.playerGalaxyY);
        return switch (region) {
            case SOUTHERN_SHELTER -> switch (roll) {
                case 0 -> theater + " ration market steadies; fuel bids soften for one leg";
                case 1 -> theater + " hospital traffic gets priority and slows aggressive burns";
                case 2 -> theater + " mine foremen report a clean convoy window";
                default -> theater + " dock unions flag spare repair crews near friendly hubs";
            };
            case CONTESTED_BELT -> switch (roll) {
                case 0 -> theater + " relay static masks both scouts and raiders";
                case 1 -> theater + " salvage rush pulls neutral traffic into dangerous lanes";
                case 2 -> theater + " blockade rumors raise insurance prices";
                default -> theater + " patrol gaps open around a damaged comm buoy";
            };
            case EARTHWARDED_NORTH -> switch (roll) {
                case 0 -> theater + " occupation sweeps tighten around known routes";
                case 1 -> theater + " resistance couriers request a silent crossing";
                case 2 -> theater + " blackout markets trade fuel for fresh intel";
                default -> theater + " mass-driver warnings scatter civilian traffic";
            };
        };
    }

    private static String routeTrafficPatternFor(GalaxyRegionIdentity region, int serial, GalaxyRouteAssessment route) {
        double risk = MathUtil.clamp((route == null ? 0.0 : route.interceptionRisk) / 100.0, 0.0, 1.0);
        String density = risk >= 0.58 ? "thin and nervous" : (risk >= 0.30 ? "broken but active" : "dense and scheduled");
        int roll = Math.floorMod(serial, 3);
        String pattern = switch (region) {
            case SOUTHERN_SHELTER -> switch (roll) {
                case 0 -> "hub shuttles";
                case 1 -> "ore barges";
                default -> "refugee tenders";
            };
            case CONTESTED_BELT -> switch (roll) {
                case 0 -> "scarred convoys";
                case 1 -> "prospector skiffs";
                default -> "neutral haulers";
            };
            case EARTHWARDED_NORTH -> switch (roll) {
                case 0 -> "blackout runners";
                case 1 -> "resistance couriers";
                default -> "patrol-shadowed liners";
            };
        };
        return density + " " + pattern + "; risk " + (int) Math.round(risk * 100.0) + "%";
    }

    private static String contactChainLineFor(CampaignState st,
                                              GalaxyRegionIdentity region,
                                              int serial,
                                              GalaxyRouteAssessment route) {
        if (st == null) return "no chain active";
        if (st.activeContactChainJumpsRemaining <= 0 || st.activeContactChainLabel == null || st.activeContactChainLabel.isBlank()) {
            st.activeContactChainLabel = contactChainSeedLabel(region, serial);
            st.activeContactChainStage = 1;
            st.activeContactChainJumpsRemaining = 2;
            return st.activeContactChainLabel + " stage 1/3: uncertain return tagged for follow-up";
        }
        st.activeContactChainStage = (int) MathUtil.clamp(st.activeContactChainStage + 1, 1, 3);
        st.activeContactChainJumpsRemaining = Math.max(0, st.activeContactChainJumpsRemaining - 1);
        String detail = switch (st.activeContactChainStage) {
            case 1 -> "uncertain return tagged for follow-up";
            case 2 -> "second jump confirms route intent but not allegiance";
            default -> "third jump resolves into actionable intel or a decoy";
        };
        if (route != null && route.interceptionRisk >= 55.0 && st.activeContactChainStage >= 2) {
            detail = detail + "; hostile pressure rising";
        }
        return st.activeContactChainLabel + " stage " + st.activeContactChainStage + "/3: " + detail;
    }

    private static String contactChainSeedLabel(GalaxyRegionIdentity region, int serial) {
        int roll = Math.floorMod(serial, 3);
        return switch (region) {
            case SOUTHERN_SHELTER -> switch (roll) {
                case 0 -> "Missing Tender Track";
                case 1 -> "Ore Barge Echo";
                default -> "Hub Shuttle Mismatch";
            };
            case CONTESTED_BELT -> switch (roll) {
                case 0 -> "Broken Convoy Wake";
                case 1 -> "Prospector Ghost";
                default -> "Relay Spoof Trail";
            };
            case EARTHWARDED_NORTH -> switch (roll) {
                case 0 -> "Blackout Courier Trace";
                case 1 -> "Resistance Mask";
                default -> "Occupation Sweep Shadow";
            };
        };
    }

    public static boolean stopCampaignTravel(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !isStrategicGalaxyMapMode(ctx)) return false;
        if (!st.galaxyTravel.traveling) return false;
        st.galaxyTravel.clear();
        st.currentGalaxyLocationId = "";
        EventSystem.showBanner(ctx, "TRAVEL HOLD - FLEET DRIFT HALTED", 1.1);
        recordStructuredCampaignEvent(ctx, st, "campaign.transition.travel_stop", "reason=player_hold");
        return true;
    }

    public static boolean requestCampaignSensorSweep(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !st.enabled) return false;
        FleetPosture posture = resolveFleetPosture(st.selectedFleetPostureId);
        int cost = sweepSupplyCost(posture);
        if (st.campaignSupplies < cost) {
            EventSystem.showBanner(ctx, "SCAN SWEEP REQUIRES " + cost + " SUPPLIES", 1.3);
            return true;
        }
        if (!isStrategicGalaxyMapMode(ctx)) {
            st.campaignSupplies = Math.max(0, st.campaignSupplies - cost);
            st.campaignIntelLevel = MathUtil.clamp(st.campaignIntelLevel + 8.0 + postureSweepIntelBonus(posture) * 0.5, 0.0, 100.0);
            st.strategicExposureLevel = MathUtil.clamp(st.strategicExposureLevel + Math.max(0.5, postureSweepExposureShift(posture) * 0.5), 0.0, 100.0);
            int pings = 0;
            for (CampaignObjectiveMarker marker : activeObjectiveMarkers(ctx)) {
                if (marker == null) continue;
                UISystem.addPing(ctx, marker.x, marker.y, 1.8);
                pings++;
                if (pings >= 3) break;
            }
            for (StrategicTaskForce taskForce : st.strategicTaskForces) {
                if (taskForce == null || taskForce.encounterResolved || !taskForce.hostile) continue;
                UISystem.addPing(ctx,
                        missionSubzoneCenterX(ctx, st.sector, taskForce.currentSubzone),
                        missionSubzoneCenterY(ctx, st.sector, taskForce.currentSubzone),
                        1.8);
                break;
            }
            EventSystem.showBanner(ctx, "MISSION RECON SWEEP  |  LOCAL CONTACT PICTURE REFRESHED", 1.4);
            return true;
        }
        double siteRadius = 1650.0 + st.campaignIntelLevel * 8.5 + postureSweepRadiusBonus(posture);
        double hostileRadius = siteRadius + 520.0 + Math.max(120.0, postureSweepRadiusBonus(posture) * 0.45);
        boolean identifyHostiles = st.campaignIntelLevel + postureSweepIntelBonus(posture) >= 34.0;
        int siteHits = revealCampaignSweepSites(ctx, st, siteRadius);
        int hostileHits = revealCampaignSweepHostiles(ctx, st, hostileRadius, identifyHostiles);
        st.campaignSupplies = Math.max(0, st.campaignSupplies - cost);
        st.campaignIntelLevel = MathUtil.clamp(st.campaignIntelLevel + 18.0 + postureSweepIntelBonus(posture), 0.0, 100.0);
        st.enemyAlertLevel = MathUtil.clamp(st.enemyAlertLevel - 3.0 + postureSweepAlertShift(posture), 0.0, 100.0);
        st.strategicExposureLevel = MathUtil.clamp(st.strategicExposureLevel + postureSweepExposureShift(posture), 0.0, 100.0);
        updateOvermapIntelQualities(ctx, st);
        EventSystem.showBanner(ctx, campaignSweepBanner(siteHits, hostileHits, identifyHostiles) + "  |  " + fleetPostureLabel(posture).toUpperCase(Locale.US), 1.5);
        return true;
    }

    public static boolean requestCampaignFocusedTrack(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !st.enabled) return false;
        if (!hasSelectedCampaignContactTarget(ctx) || !selectedCampaignContactHostile(ctx)) {
            EventSystem.showBanner(ctx, "SELECT A HOSTILE CONTACT BEFORE FOCUSING TRACK", 1.3);
            return true;
        }
        int cost = 1;
        if (st.campaignSupplies < cost) {
            EventSystem.showBanner(ctx, "FOCUSED TRACK REQUIRES " + cost + " SUPPLIES", 1.2);
            return true;
        }
        GalaxySearchGroup group = selectedCampaignSearchGroup(ctx);
        StrategicTaskForce taskForce = nearestHostileStrategicTaskForce(ctx,
                ctx.ui.selectedCampaignContactX, ctx.ui.selectedCampaignContactY, 260.0);
        if (group == null && taskForce == null) {
            EventSystem.showBanner(ctx, "FOCUSED TRACK FOUND NO FIRM RETURN", 1.2);
            return true;
        }
        st.campaignSupplies = Math.max(0, st.campaignSupplies - cost);
        st.campaignIntelLevel = MathUtil.clamp(st.campaignIntelLevel + 12.0, 0.0, 100.0);
        st.strategicExposureLevel = MathUtil.clamp(st.strategicExposureLevel + 1.4, 0.0, 100.0);
        if (group != null) {
            group.visible = true;
            group.contactFadeSec = Math.max(group.contactFadeSec, 52.0);
            group.contactConfidence = GalaxyContactConfidence.IDENTIFIED_TASK_FORCE;
            group.identified = true;
            group.intelQuality = ContactIntelQuality.TARGET_QUALITY;
            group.focusedTrackLockSec = Math.max(group.focusedTrackLockSec, 24.0);
            group.trackIntegrity = MathUtil.clamp(group.trackIntegrity + 56.0, 0.0, 100.0);
            group.decoyRisk = Math.max(0.0, group.decoyRisk - 0.30);
            UISystem.addPing(ctx, group.x, group.y, 2.6);
            st.lastContactScanSummary = "Focused Track  |  " + selectedContactScanDetailLine(ctx);
        }
        if (taskForce != null) {
            taskForce.disruptionRemainingSec = Math.max(taskForce.disruptionRemainingSec, 18.0);
            taskForce.breakoffRemainingSec = Math.max(0.0, taskForce.breakoffRemainingSec - 6.0);
            UISystem.addPing(ctx,
                    missionSubzoneCenterX(ctx, st.sector, taskForce.currentSubzone),
                    missionSubzoneCenterY(ctx, st.sector, taskForce.currentSubzone),
                    2.2);
        }
        EventSystem.showBanner(ctx, "FOCUSED TRACK LOCKED  |  TARGET WINDOW SHARPENED", 1.4);
        return true;
    }

    public static boolean requestCampaignTrafficAudit(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !isStrategicGalaxyMapMode(ctx)) return false;
        int cost = 2;
        if (st.campaignSupplies < cost) {
            EventSystem.showBanner(ctx, "TRAFFIC AUDIT REQUIRES " + cost + " SUPPLIES", 1.2);
            return true;
        }
        st.campaignSupplies = Math.max(0, st.campaignSupplies - cost);
        double radius = 2100.0 + st.campaignIntelLevel * 7.0;
        int siteHits = revealCampaignSweepSites(ctx, st, radius);
        int trafficHits = 0;
        for (CampaignLocation location : st.galaxyMainPois) {
            if (location == null) continue;
            double dist = Math.hypot(location.x - st.playerGalaxyX, location.y - st.playerGalaxyY);
            if (dist > radius) continue;
            boolean newlyDiscovered = !location.discovered;
            location.discovered = true;
            location.intelQuality = ContactIntelQuality.IDENTIFIED;
            improveFacilityIntel(location, ContactIntelQuality.IDENTIFIED);
            if (newlyDiscovered) trafficHits++;
            UISystem.addPing(ctx, location.x, location.y, 2.0);
        }
        st.campaignIntelLevel = MathUtil.clamp(st.campaignIntelLevel + 9.0, 0.0, 100.0);
        st.enemyAlertLevel = MathUtil.clamp(st.enemyAlertLevel - 2.0, 0.0, 100.0);
        for (GalaxySearchGroup group : st.galaxySearchGroups) {
            if (group == null) continue;
            double dist = Math.hypot(group.x - st.playerGalaxyX, group.y - st.playerGalaxyY);
            if (dist > radius) continue;
            group.trackIntegrity = MathUtil.clamp(group.trackIntegrity + 16.0, 0.0, 100.0);
            group.commsSignature = MathUtil.clamp(group.commsSignature + 0.10, 0.0, 1.0);
        }
        st.lastTrafficAuditSummary = trafficAuditSummaryLine(ctx, st, radius, siteHits, trafficHits);
        EventSystem.showBanner(ctx,
                "TRAFFIC AUDIT MARKED " + siteHits + " SIDE SITES  |  " + trafficHits + " HUB / LANE CONTACTS",
                1.4);
        return true;
    }

