    private static boolean runBlockadeBreakOperation(GameContext ctx) {
        CampaignState st = state(ctx);
        CampaignLocation location = selectedCampaignLocation(ctx);
        if (ctx == null || st == null || location == null || !isWithinDockingRange(st, location)) return false;
        final double reserveCost = 20.0;
        if (st.blueInterventionReserve < reserveCost) {
            EventSystem.showBanner(ctx, "BLUE INTERVENTION RESERVE TOO LOW FOR BLOCKADE BREAK", 1.3);
            return true;
        }
        double leverage = consumeBlueInterventionReserve(st, reserveCost);
        st.lastTheaterOperationBrief = "Blockade Break at " + location.name
                + ": Punch a corridor through interdiction and reopen movement lanes.";
        st.lastTheaterOperationDebrief = "Blockade broken: +control, +fuel throughput, route danger reduced.";
        st.lastTheaterOperationTick = st.theaterWarTickIndex;
        st.campaignFuel += 8;
        st.campaignSupplies += 3;
        st.recentStrikePressure = Math.max(0.0, st.recentStrikePressure - 5.0);
        awardTheaterControlForOperation(st, location, OPERATION_BLOCKADE_CONTROL_DELTA * leverage);
        pushTheaterEvent(st, "Blockade broken near " + location.name);
        EventSystem.showBanner(ctx, "BLOCKADE BREAK COMPLETE: TRANSIT CORRIDOR OPEN", 1.4);
        return true;
    }

    private static double consumeBlueInterventionReserve(CampaignState st, double reserveCost) {
        if (st == null) return 1.0;
        double before = MathUtil.clamp(st.blueInterventionReserve, 0.0, 100.0);
        st.blueInterventionReserve = Math.max(0.0, before - Math.max(0.0, reserveCost));
        return MathUtil.clamp(0.62 + before * 0.0043, 0.62, 1.05);
    }

    public static boolean launchSelectedLocalEncounter(GameContext ctx) {
        CampaignState st = state(ctx);
        CampaignLocation location = selectedCampaignLocation(ctx);
        if (ctx == null || st == null || location == null) return false;
        if (!canEnterSelectedLocalEncounter(ctx)) {
            EventSystem.showBanner(ctx, "MOVE INTO RANGE BEFORE ENTERING THE SITE", 1.3);
            return true;
        }
        return launchAmbientCampaignLocationEncounter(ctx, st, location);
    }

    static int missionSubzoneCount() {
        return MISSION_ZONE_COLUMNS * MISSION_ZONE_ROWS;
    }

    static int missionSubzoneColumns() {
        return MISSION_ZONE_COLUMNS;
    }

    static int missionSubzoneRows() {
        return MISSION_ZONE_ROWS;
    }

    static double missionSubzoneWidth() {
        return missionLayout((GameConfig) null).subzoneWidth;
    }

    static double missionSubzoneWidth(GameContext ctx) {
        return missionLayout(ctx).subzoneWidth;
    }

    static double missionSubzoneHeight() {
        return missionLayout((GameConfig) null).subzoneHeight;
    }

    static double missionSubzoneHeight(GameContext ctx) {
        return missionLayout(ctx).subzoneHeight;
    }

    static int missionSubzoneIndex(int col, int row) {
        if (col < 0 || col >= MISSION_ZONE_COLUMNS || row < 0 || row >= MISSION_ZONE_ROWS) return -1;
        return row * MISSION_ZONE_COLUMNS + col;
    }

    static int missionSubzoneColumn(int subzoneIndex) {
        if (subzoneIndex < 0) return -1;
        return subzoneIndex % MISSION_ZONE_COLUMNS;
    }

    static int missionSubzoneRow(int subzoneIndex) {
        if (subzoneIndex < 0) return -1;
        return subzoneIndex / MISSION_ZONE_COLUMNS;
    }

    static String missionSubzoneLabel(int subzoneIndex) {
        int col = missionSubzoneColumn(subzoneIndex);
        int row = missionSubzoneRow(subzoneIndex);
        if (col < 0 || row < 0) return "SECTOR";
        char rowTag = (char) ('A' + row);
        return rowTag + Integer.toString(col + 1);
    }

    private static TacticalApproachDirection deriveApproachDirection(double fromX, double fromY, double toX, double toY) {
        double dx = toX - fromX;
        double dy = toY - fromY;
        if (!Double.isFinite(dx) || !Double.isFinite(dy) || (Math.abs(dx) < 1e-6 && Math.abs(dy) < 1e-6)) {
            return TacticalApproachDirection.EAST;
        }
        double angle = Math.atan2(dy, dx);
        double octant = Math.PI / 8.0;
        if (angle >= -octant && angle < octant) return TacticalApproachDirection.WEST;
        if (angle >= octant && angle < 3.0 * octant) return TacticalApproachDirection.NORTHWEST;
        if (angle >= 3.0 * octant && angle < 5.0 * octant) return TacticalApproachDirection.NORTH;
        if (angle >= 5.0 * octant && angle < 7.0 * octant) return TacticalApproachDirection.NORTHEAST;
        if (angle >= 7.0 * octant || angle < -7.0 * octant) return TacticalApproachDirection.EAST;
        if (angle >= -7.0 * octant && angle < -5.0 * octant) return TacticalApproachDirection.SOUTHEAST;
        if (angle >= -5.0 * octant && angle < -3.0 * octant) return TacticalApproachDirection.SOUTH;
        return TacticalApproachDirection.SOUTHWEST;
    }

    private static TacticalApproachDirection oppositeApproachDirection(TacticalApproachDirection direction) {
        if (direction == null) return TacticalApproachDirection.WEST;
        return switch (direction) {
            case WEST -> TacticalApproachDirection.EAST;
            case EAST -> TacticalApproachDirection.WEST;
            case NORTH -> TacticalApproachDirection.SOUTH;
            case SOUTH -> TacticalApproachDirection.NORTH;
            case NORTHWEST -> TacticalApproachDirection.SOUTHEAST;
            case NORTHEAST -> TacticalApproachDirection.SOUTHWEST;
            case SOUTHWEST -> TacticalApproachDirection.NORTHEAST;
            case SOUTHEAST -> TacticalApproachDirection.NORTHWEST;
        };
    }

    private static String approachDirectionLabel(TacticalApproachDirection direction) {
        if (direction == null) return "unknown edge";
        return switch (direction) {
            case WEST -> "west edge";
            case EAST -> "east edge";
            case NORTH -> "north edge";
            case SOUTH -> "south edge";
            case NORTHWEST -> "northwest edge";
            case NORTHEAST -> "northeast edge";
            case SOUTHWEST -> "southwest edge";
            case SOUTHEAST -> "southeast edge";
        };
    }

    private static double[] subzoneApproachPoint(GameContext ctx,
                                                 int sector,
                                                 int subzoneIndex,
                                                 TacticalApproachDirection direction,
                                                 double depth) {
        MissionLayout layout = missionLayout(ctx);
        double minX = missionSubzoneMinX(ctx, sector, subzoneIndex) + MISSION_SUBZONE_CLAMP_MARGIN;
        double maxX = missionSubzoneMinX(ctx, sector, subzoneIndex) + layout.subzoneWidth - MISSION_SUBZONE_CLAMP_MARGIN;
        double minY = missionSubzoneMinY(ctx, sector, subzoneIndex) + MISSION_SUBZONE_CLAMP_MARGIN;
        double maxY = missionSubzoneMinY(ctx, sector, subzoneIndex) + layout.subzoneHeight - MISSION_SUBZONE_CLAMP_MARGIN;
        double centerX = missionSubzoneCenterX(ctx, sector, subzoneIndex);
        double centerY = missionSubzoneCenterY(ctx, sector, subzoneIndex);
        double inset = Math.max(90.0, Math.min(depth, Math.min(layout.subzoneWidth, layout.subzoneHeight) * 0.22));
        TacticalApproachDirection resolved = (direction == null) ? TacticalApproachDirection.EAST : direction;
        double x = centerX;
        double y = centerY;
        switch (resolved) {
            case WEST -> x = minX + inset;
            case EAST -> x = maxX - inset;
            case NORTH -> y = minY + inset;
            case SOUTH -> y = maxY - inset;
            case NORTHWEST -> {
                x = minX + inset;
                y = minY + inset;
            }
            case NORTHEAST -> {
                x = maxX - inset;
                y = minY + inset;
            }
            case SOUTHWEST -> {
                x = minX + inset;
                y = maxY - inset;
            }
            case SOUTHEAST -> {
                x = maxX - inset;
                y = maxY - inset;
            }
        }
        return new double[]{x, y};
    }

    private static double openSpaceFleetClashLaneSpacing(GameContext ctx) {
        MissionLayout layout = missionLayout(ctx);
        double worldLimit = (ctx == null) ? 900.0 : Math.max(520.0, ctx.WORLD_W * 0.18);
        return MathUtil.clamp(layout.subzoneWidth * 0.55, 620.0, Math.min(980.0, worldLimit));
    }

    private static double openSpaceFleetClashCenterX(GameContext ctx, CampaignState st) {
        if (st != null && Double.isFinite(st.galaxyAmbientPocketCenterX)) return st.galaxyAmbientPocketCenterX;
        int centerZone = missionSubzoneIndex(Math.max(0, missionSubzoneColumns() / 2), 1);
        return missionSubzoneCenterX(ctx, st == null ? 0 : st.sector, centerZone);
    }

    private static double openSpaceFleetClashCenterY(GameContext ctx, CampaignState st) {
        if (st != null && Double.isFinite(st.galaxyAmbientPocketCenterY)) return st.galaxyAmbientPocketCenterY;
        int centerZone = missionSubzoneIndex(Math.max(0, missionSubzoneColumns() / 2), 1);
        return missionSubzoneCenterY(ctx, st == null ? 0 : st.sector, centerZone);
    }

    private static double openSpaceFleetClashLaneX(GameContext ctx, CampaignState st, int lane) {
        return openSpaceFleetClashCenterX(ctx, st) + lane * openSpaceFleetClashLaneSpacing(ctx);
    }

    private static double[] openSpaceFleetClashApproachPoint(GameContext ctx,
                                                             CampaignState st,
                                                             int lane,
                                                             TacticalApproachDirection direction,
                                                             double depth) {
        double spacing = openSpaceFleetClashLaneSpacing(ctx);
        double centerX = openSpaceFleetClashLaneX(ctx, st, lane);
        double centerY = openSpaceFleetClashCenterY(ctx, st);
        double halfW = Math.max(320.0, spacing * 0.42);
        double halfH = Math.max(260.0, missionLayout(ctx).subzoneHeight * 0.24);
        double inset = Math.max(90.0, Math.min(depth, Math.min(halfW, halfH) * 0.65));
        TacticalApproachDirection resolved = (direction == null) ? TacticalApproachDirection.EAST : direction;
        double x = centerX;
        double y = centerY;
        switch (resolved) {
            case WEST -> x = centerX - halfW + inset;
            case EAST -> x = centerX + halfW - inset;
            case NORTH -> y = centerY - halfH + inset;
            case SOUTH -> y = centerY + halfH - inset;
            case NORTHWEST -> {
                x = centerX - halfW + inset;
                y = centerY - halfH + inset;
            }
            case NORTHEAST -> {
                x = centerX + halfW - inset;
                y = centerY - halfH + inset;
            }
            case SOUTHWEST -> {
                x = centerX - halfW + inset;
                y = centerY + halfH - inset;
            }
            case SOUTHEAST -> {
                x = centerX + halfW - inset;
                y = centerY + halfH - inset;
            }
        }
        double margin = Math.max(120.0, MISSION_SUBZONE_CLAMP_MARGIN);
        if (ctx != null) {
            x = GameMath.clamp(x, margin, Math.max(margin, ctx.WORLD_W - margin));
            y = GameMath.clamp(y, margin, Math.max(margin, ctx.WORLD_H - margin));
        }
        return new double[]{x, y};
    }

    private static double[] ambientApproachPoint(GameContext ctx,
                                                 CampaignState st,
                                                 TacticalApproachDirection direction,
                                                 double distanceMul) {
        double centerX = ambientEncounterCenterX(ctx, st);
        double centerY = ambientEncounterCenterY(ctx, st);
        double radius = ambientEncounterRadius(st) * MathUtil.clamp(distanceMul, 0.28, 0.92);
        TacticalApproachDirection resolved = (direction == null) ? TacticalApproachDirection.WEST : direction;
        double dx = 0.0;
        double dy = 0.0;
        switch (resolved) {
            case WEST -> dx = -1.0;
            case EAST -> dx = 1.0;
            case NORTH -> dy = -1.0;
            case SOUTH -> dy = 1.0;
            case NORTHWEST -> {
                dx = -0.78;
                dy = -0.78;
            }
            case NORTHEAST -> {
                dx = 0.78;
                dy = -0.78;
            }
            case SOUTHWEST -> {
                dx = -0.78;
                dy = 0.78;
            }
            case SOUTHEAST -> {
                dx = 0.78;
                dy = 0.78;
            }
        }
        return new double[]{centerX + dx * radius, centerY + dy * radius};
    }

    private static double pointAngleToward(double fromX, double fromY, double toX, double toY) {
        return Math.atan2(toY - fromY, toX - fromX);
    }

    private static TacticalApproachDirection ambientEncounterArrivalDirection(CampaignState st, CampaignLocation location) {
        if (st == null || location == null) return TacticalApproachDirection.WEST;
        double originX = galaxyOriginX(st);
        double originY = galaxyOriginY(st);
        if (Math.hypot(location.x - originX, location.y - originY) > 1e-3) {
            double dx = location.x - originX;
            double dy = location.y - originY;
            // Keep lane-entry narration stable on tall theaters where y-span is intentionally larger.
            if (Math.abs(dx) >= Math.abs(dy) * 0.45) {
                return (dx >= 0.0) ? TacticalApproachDirection.WEST : TacticalApproachDirection.EAST;
            }
            return deriveApproachDirection(originX, originY, location.x, location.y);
        }
        double headingRad = Math.toRadians(Double.isFinite(st.playerGalaxyHeadingDeg) ? st.playerGalaxyHeadingDeg : 0.0);
        return deriveApproachDirection(location.x - Math.cos(headingRad) * 220.0,
                location.y - Math.sin(headingRad) * 220.0,
                location.x,
                location.y);
    }

    private static TacticalApproachDirection ambientEncounterObjectiveDirection(CampaignLocation location,
                                                                                TacticalApproachDirection arrivalDirection) {
        if (location != null && location.type == CampaignLocationType.RESOURCE_ZONE) {
            return TacticalApproachDirection.NORTHEAST;
        }
        if (location != null && location.type == CampaignLocationType.DISTRESS_SIGNAL) {
            return TacticalApproachDirection.EAST;
        }
        return oppositeApproachDirection(arrivalDirection);
    }

    private static MissionSection reserveStagingSection(CampaignState st) {
        if (st == null || st.missionSections.isEmpty()) return null;
        for (MissionSection section : st.missionSections) {
            if (section != null && section.label != null
                    && section.label.toUpperCase(Locale.US).contains("RESERVE STAGING")) {
                return section;
            }
        }
        return st.missionSections.get(Math.max(0, st.missionSections.size() - 1));
    }

    private static TacticalApproachDirection reserveApproachDirectionForSection(CampaignState st, MissionSection targetSection) {
        if (st == null || targetSection == null) return TacticalApproachDirection.EAST;
        MissionSection reserve = reserveStagingSection(st);
        if (reserve == null) return TacticalApproachDirection.EAST;
        return deriveApproachDirection(reserve.x, reserve.y, targetSection.x, targetSection.y);
    }

    static List<DiscoverySignalSite> anomalySignalSites(GameContext ctx) {
        CampaignState st = state(ctx);
        if (st == null || st.discoverySites.isEmpty()) return List.of();
        ArrayList<DiscoverySignalSite> out = new ArrayList<>();
        for (DiscoverySite site : st.discoverySites) {
            if (site == null || site.discovered || site.kind != DiscoveryKind.ANOMALY) continue;
            out.add(new DiscoverySignalSite(site.label, site.subtitle, site.kind.name(), site.x, site.y, site.radius));
        }
        return out;
    }

    static List<DiscoverySignalSite> discoverySignalSites(GameContext ctx) {
        CampaignState st = state(ctx);
        if (st == null || st.discoverySites.isEmpty()) return List.of();
        ArrayList<DiscoverySignalSite> out = new ArrayList<>();
        for (DiscoverySite site : st.discoverySites) {
            if (site == null || site.discovered || site.kind == null) continue;
            out.add(new DiscoverySignalSite(site.label, site.subtitle, site.kind.name(), site.x, site.y, site.radius));
        }
        return out;
    }

    static List<DiscoverySignalSite> recoverableWreckSignalSites(GameContext ctx) {
        CampaignState st = state(ctx);
        if (st == null || st.recoverableWreckSites.isEmpty()) return List.of();
        ArrayList<DiscoverySignalSite> out = new ArrayList<>();
        for (RecoverableWreckSite site : st.recoverableWreckSites) {
            if (site == null || site.claimed) continue;
            out.add(new DiscoverySignalSite(site.label, site.subtitle, "RECOVERABLE_WRECK", site.x, site.y, site.radius));
        }
        return out;
    }

    static List<CampaignObjectiveMarker> activeObjectiveMarkers(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !st.enabled) return List.of();

        ArrayList<CampaignObjectiveMarker> out = new ArrayList<>();
        if (isStrategicOvermapMode(st)) {
            CampaignLocation current = currentCampaignLocation(ctx);
            CampaignLocation selected = selectedCampaignLocation(ctx);
            for (CampaignLocation poi : st.galaxyMainPois) {
                if (poi == null || !poi.discovered) continue;
                String subtitle = poi.detail;
                if (current != null && poi.id.equalsIgnoreCase(current.id)) {
                    subtitle = "Current location  |  " + poi.detail;
                } else if (selected != null && poi.id.equalsIgnoreCase(selected.id)) {
                    subtitle = "Selected destination  |  " + poi.detail;
                }
                if (poi.completed) {
                    subtitle = "Mission secured  |  " + poi.detail;
                }
                out.add(new CampaignObjectiveMarker(
                        (current != null && poi.id.equalsIgnoreCase(current.id))
                                ? ObjectiveMarkerType.NEXT_ROUTE
                                : ObjectiveMarkerType.PRIMARY_OBJECTIVE,
                        poi.name,
                        subtitle,
                        poi.x, poi.y,
                        160.0,
                        poi.completed ? 72 : 96));
            }
            for (RecoverableWreckSite wreck : st.recoverableWreckSites) {
                if (wreck == null || wreck.claimed) continue;
                String wreckSubtitle = recoverableWreckObjectiveSubtitle(st, wreck);
                out.add(new CampaignObjectiveMarker(
                        ObjectiveMarkerType.OPTIONAL_OBJECTIVE,
                        wreck.label,
                        wreckSubtitle,
                        wreck.x, wreck.y,
                        wreck.radius,
                        58));
            }
            return out;
        }

        if (st.galaxyEncounterActive && !st.galaxyAmbientEncounterActive) {
            double centerX = (ctx.player == null) ? 0.0 : ctx.player.x;
            double centerY = (ctx.player == null) ? 0.0 : ctx.player.y;
            out.add(new CampaignObjectiveMarker(
                    ObjectiveMarkerType.PRIMARY_OBJECTIVE,
                    "Intercept Pocket",
                    "Visible hostile formation in open space  |  break contact and clear the lane",
                    centerX, centerY,
                    220.0,
                    96));
            addTacticalDeploymentPreviewMarkers(ctx, st, out);
        int priority = 90;
        for (Ship ship : ctx.ships) {
                if (ship == null || ship == ctx.player || !ship.alive || ship.dying || ship.hp <= 0) continue;
                boolean friendly = ship.faction != null && ctx.player != null && ctx.player.faction != null
                        && ship.faction.isFriendlyTo(ctx.player.faction);
                out.add(new CampaignObjectiveMarker(
                        friendly ? ObjectiveMarkerType.PROTECTED_ASSET : ObjectiveMarkerType.DESTROY_TARGET,
                        displayShipName(ship, friendly ? "Friendly Contact" : "Hostile Contact"),
                        friendly ? "Friendly intercept element" : "Hostile intercept element",
                        ship.faction,
                        ship.x, ship.y,
                        Math.max(150.0, ship.radius * 2.5),
                        priority));
                priority = Math.max(68, priority - 3);
            if (out.size() >= 9) break;
            }
            addOpenSpaceZoneOwnershipMarkers(ctx, st, out);
            return localMissionObjectiveMarkers(ctx, st, out);
        }

        if (st.galaxyAmbientEncounterActive) {
            CampaignLocation site = campaignLocationById(st, st.activeGalaxyEncounterLocationId);
            double centerX = ambientEncounterCenterX(ctx, st);
            double centerY = ambientEncounterCenterY(ctx, st);
            double radius = ambientEncounterRadius(st);
            if (site != null) {
                out.add(new CampaignObjectiveMarker(
                        ObjectiveMarkerType.PRIMARY_OBJECTIVE,
                        site.name,
                        "Local site pocket  |  Security Sweep the marked contacts and Withdraw To Strategic Map when ready",
                        centerX,
                        centerY,
                        Math.max(260.0, radius),
                        96));
            }
            int contactPriority = 88;
            for (Ship ship : ctx.ships) {
                if (ship == null || ship == ctx.player || !ship.alive || ship.dying || ship.hp <= 0) continue;
                ObjectiveMarkerType type = (ship.faction != null && ctx.player != null && ctx.player.faction != null
                        && ship.faction.isFriendlyTo(ctx.player.faction))
                        ? ObjectiveMarkerType.PROTECTED_ASSET
                        : ObjectiveMarkerType.DESTROY_TARGET;
                String subtitle = (type == ObjectiveMarkerType.PROTECTED_ASSET)
                        ? "Friendly local contact"
                        : "Hostile local contact";
                out.add(new CampaignObjectiveMarker(
                        type,
                        displayShipName(ship, "Local Contact"),
                        subtitle,
                        ship.faction,
                        ship.x, ship.y,
                        Math.max(160.0, ship.radius * 2.6),
                        contactPriority));
                contactPriority = Math.max(62, contactPriority - 4);
                if (out.size() >= 8) break;
            }
        }

        if (!st.missionSections.isEmpty()) {
            int activeIndex = Math.max(0, Math.min(st.missionSections.size() - 1, st.activeMissionSection));
            MissionSection active = st.missionSections.get(activeIndex);
            if (active != null) {
                out.add(new CampaignObjectiveMarker(
                        st.missionSectionTravelLocked ? ObjectiveMarkerType.NEXT_ROUTE : ObjectiveMarkerType.PRIMARY_OBJECTIVE,
                        active.label,
                        st.missionSectionTravelLocked
                                ? "Fly the flagship here to resume mission progress"
                                : "Clear this pocket to unlock the next objective route",
                        active.x, active.y, active.radius,
                        st.missionSectionTravelLocked ? 100 : 95));
            }
            if (!st.missionSectionTravelLocked && activeIndex + 1 < st.missionSections.size()) {
                MissionSection next = st.missionSections.get(activeIndex + 1);
                if (next != null) {
                    out.add(new CampaignObjectiveMarker(
                            ObjectiveMarkerType.NEXT_ROUTE,
                            next.label,
                            "Next route after the current pocket is secured",
                            next.x, next.y, next.radius,
                            70));
                }
            }
            addTacticalDeploymentPreviewMarkers(ctx, st, out);
        }

        if (st.objectiveType == ObjectiveType.ESCORT && st.escortShip != null
                && st.escortShip.alive && !st.escortShip.dying && st.escortShip.hp > 0) {
            out.add(new CampaignObjectiveMarker(
                    ObjectiveMarkerType.ESCORT_TARGET,
                    displayShipName(st.escortShip, "Escort Target"),
                    "Keep this ship alive",
                    st.escortShip.faction,
                    st.escortShip.x, st.escortShip.y,
                    Math.max(180.0, st.escortShip.radius * 2.5),
                    96));
        }

        if (st.objectiveType == ObjectiveType.CAPTURE) {
            out.add(new CampaignObjectiveMarker(
                    ObjectiveMarkerType.CAPTURE_ZONE,
                    "Capture Zone",
                    "Clear defenders and secure this area",
                    st.captureX, st.captureY, st.captureRadius,
                    94));
        }

        if (st.protectFlagshipObjectiveActive && ctx.player != null
                && ctx.player.alive && !ctx.player.dying && ctx.player.hp > 0) {
            out.add(new CampaignObjectiveMarker(
                    ObjectiveMarkerType.PROTECTED_ASSET,
                    "Protect Flagship",
                    "Keep flagship hull above " + (int) Math.round(st.protectFlagshipMinHullFrac * 100.0) + "%",
                    ctx.player.faction,
                    ctx.player.x,
                    ctx.player.y,
                    Math.max(190.0, ctx.player.radius * 2.7),
                    99));
        }

        if (st.emergencyExtractionObjectiveActive) {
            Ship target = findShipById(ctx, st.emergencyExtractionShipId);
            if (target != null && target.alive && !target.dying && target.hp > 0) {
                int progress = (int) Math.round(MathUtil.clamp(
                        st.emergencyExtractionProgressSec / Math.max(1.0, st.emergencyExtractionGoalSec), 0.0, 1.0) * 100.0);
                out.add(new CampaignObjectiveMarker(
                        ObjectiveMarkerType.PROTECTED_ASSET,
                        "Emergency Extraction",
                        "Hold near disabled ship  |  extraction " + progress + "%",
                        target.faction,
                        target.x,
                        target.y,
                        st.emergencyExtractionRadius,
                        98));
            }
        }

        if (st.convoyLaneDefenseObjectiveActive && st.objectiveAssetTotal > 0) {
            double[] center = objectiveAssetCenter(ctx, st);
            if (center != null) {
                out.add(new CampaignObjectiveMarker(
                        ObjectiveMarkerType.PROTECTED_ASSET,
                        "Convoy Lane Defense",
                        "Civilian traffic constraint  |  keep " + Math.max(1, st.objectiveAssetRequiredSurvivors)
                                + "/" + st.objectiveAssetTotal + " convoy hulls safe",
                        center[0],
                        center[1],
                        520.0,
                        97));
            }
        }

        if (st.minefieldBreachObjectiveActive && !st.minefieldBreachRoutePoints.isEmpty()) {
            for (int i = 0; i < st.minefieldBreachRoutePoints.size(); i++) {
                double[] point = st.minefieldBreachRoutePoints.get(i);
                if (point == null || point.length < 2) continue;
                boolean current = i == st.minefieldBreachRouteIndex;
                int progress = (int) Math.round(MathUtil.clamp(
                        st.minefieldBreachProgressSec / Math.max(1.0, st.minefieldBreachHoldSec), 0.0, 1.0) * 100.0);
                out.add(new CampaignObjectiveMarker(
                        current ? ObjectiveMarkerType.NEXT_ROUTE : ObjectiveMarkerType.OPTIONAL_OBJECTIVE,
                        current ? "Minefield Breach Point" : "Planned Breach Route",
                        current
                                ? "Route planning waypoint " + (i + 1) + "/" + st.minefieldBreachRoutePoints.size()
                                + "  |  hold " + progress + "%"
                                : "Planned safe lane waypoint " + (i + 1),
                        point[0],
                        point[1],
                        st.minefieldBreachRadius,
                        current ? 96 : 62));
            }
        }

        if (st.pursuitObjectiveActive) {
            Ship target = findShipById(ctx, st.pursuitTargetShipId);
            if (target != null && target.alive && !target.dying && target.hp > 0) {
                int disabled = (int) Math.round(MathUtil.clamp(
                        st.pursuitDisableProgressSec / Math.max(0.75, st.pursuitDisableHoldSec), 0.0, 1.0) * 100.0);
                out.add(new CampaignObjectiveMarker(
                        ObjectiveMarkerType.DESTROY_TARGET,
                        displayShipName(target, "Pursuit Target"),
                        "Disable engines or destroy before escape  |  disabled " + disabled + "%",
                        target.faction,
                        target.x,
                        target.y,
                        Math.max(180.0, target.radius * 2.6),
                        99));
            }
            out.add(new CampaignObjectiveMarker(
                    ObjectiveMarkerType.NEXT_ROUTE,
                    "Escape Vector",
                    "Target escapes if it reaches this boundary",
                    st.pursuitEscapeX,
                    st.pursuitEscapeY,
                    st.pursuitEscapeRadius,
                    74));
        }

        if (st.retreatCorridorObjectiveActive) {
            int progress = (int) Math.round(MathUtil.clamp(
                    st.retreatCorridorProgressSec / Math.max(1.0, st.retreatCorridorHoldSec), 0.0, 1.0) * 100.0);
            out.add(new CampaignObjectiveMarker(
                    ObjectiveMarkerType.NEXT_ROUTE,
                    "Retreat Corridor",
                    "Survival objective  |  hold extraction lane " + progress + "%  |  kills optional",
                    st.retreatCorridorX,
                    st.retreatCorridorY,
                    st.retreatCorridorRadius,
                    98));
        }

        if (st.objectiveType == ObjectiveType.BOSS || st.objectiveType == ObjectiveType.FINAL_BOSS) {
            Ship boss = findShipById(ctx, st.bossTargetId);
            if (boss != null && boss.alive && !boss.dying && boss.hp > 0) {
                out.add(new CampaignObjectiveMarker(
                        ObjectiveMarkerType.BOSS_TARGET,
                        displayShipName(boss, "Boss Target"),
                        "Break the flagship when you are ready to commit",
                        boss.faction,
                        boss.x, boss.y,
                        Math.max(220.0, boss.radius * 3.0),
                        98));
            }
        }

        for (Integer id : st.objectiveAssetIds) {
            Ship asset = findShipById(ctx, id == null ? -1 : id);
            if (asset == null || !asset.alive || asset.dying || asset.hp <= 0) continue;
            out.add(new CampaignObjectiveMarker(
                    ObjectiveMarkerType.PROTECTED_ASSET,
                    displayShipName(asset, trimmedOrFallback(st.objectiveAssetLabel, "Protected Asset")),
                    objectiveAssetMarkerSubtitle(st),
                    asset.faction,
                    asset.x, asset.y,
                    Math.max(150.0, asset.radius * 2.4),
                    88));
        }

        for (Integer id : st.authoredObjectiveHostiles) {
            Ship hostile = findShipById(ctx, id == null ? -1 : id);
            if (hostile == null || !hostile.alive || hostile.dying || hostile.hp <= 0) continue;
            out.add(new CampaignObjectiveMarker(
                    ObjectiveMarkerType.DESTROY_TARGET,
                    displayShipName(hostile, "Marked Target"),
                    "Required kill for mission completion",
                    hostile.faction,
                    hostile.x, hostile.y,
                    Math.max(150.0, hostile.radius * 2.5),
                    90));
        }

        for (RecoverableWreckSite wreck : st.recoverableWreckSites) {
            if (wreck == null || wreck.claimed) continue;
            String wreckSubtitle = recoverableWreckObjectiveSubtitle(st, wreck);
            out.add(new CampaignObjectiveMarker(
                    ObjectiveMarkerType.OPTIONAL_OBJECTIVE,
                    wreck.label,
                    wreckSubtitle,
                    wreck.x, wreck.y,
                    wreck.radius,
                    58));
        }

        return localMissionObjectiveMarkers(ctx, st, out);
    }

    private static List<CampaignObjectiveMarker> localMissionObjectiveMarkers(GameContext ctx,
                                                                              CampaignState st,
                                                                              List<CampaignObjectiveMarker> markers) {
        if (ctx == null || st == null || markers == null || isStrategicOvermapMode(st) || !usesMissionSubzones(ctx)) {
            return markers == null ? List.of() : markers;
        }
        int loaded = currentLoadedMissionSubzone(ctx);
        if (loaded < 0 && ctx.player != null) {
            loaded = missionSubzoneForPoint(ctx, st.sector, ctx.player.x, ctx.player.y);
        }
        if (loaded < 0) return markers;
        ArrayList<CampaignObjectiveMarker> out = new ArrayList<>();
        for (CampaignObjectiveMarker marker : markers) {
            if (marker == null) continue;
            int subzone = missionSubzoneForPoint(ctx, st.sector, marker.x, marker.y);
            if (subzone == loaded || isAlwaysRelevantLocalObjective(marker)) {
                out.add(marker);
            }
        }
        return out;
    }

    private static boolean isAlwaysRelevantLocalObjective(CampaignObjectiveMarker marker) {
        if (marker == null) return false;
        return marker.type == ObjectiveMarkerType.ESCORT_TARGET
                || marker.type == ObjectiveMarkerType.BOSS_TARGET
                || marker.type == ObjectiveMarkerType.PROTECTED_ASSET
                || marker.type == ObjectiveMarkerType.DESTROY_TARGET
                || "Intercept Pocket".equalsIgnoreCase(marker.label)
                || "Allied Spawn Zone".equalsIgnoreCase(marker.label)
                || "Neutral Transit Zone".equalsIgnoreCase(marker.label)
                || "Hostile Contact Zone".equalsIgnoreCase(marker.label)
                || (marker.type == ObjectiveMarkerType.OPTIONAL_OBJECTIVE
                && marker.label != null
                && marker.label.startsWith("Deployment Preview: "));
    }

    private static double[] objectiveAssetCenter(GameContext ctx, CampaignState st) {
        if (ctx == null || st == null || st.objectiveAssetIds.isEmpty()) return null;
        double sx = 0.0;
        double sy = 0.0;
        int count = 0;
        for (Integer id : st.objectiveAssetIds) {
            Ship asset = findShipById(ctx, id == null ? -1 : id);
            if (asset == null || !asset.alive || asset.dying || asset.hp <= 0) continue;
            sx += asset.x;
            sy += asset.y;
            count++;
        }
        if (count <= 0) return null;
        return new double[]{sx / count, sy / count};
    }

    private static String objectiveAssetMarkerSubtitle(CampaignState st) {
        if (st != null && st.civilianTrafficConstraintActive) {
            return "Civilian traffic: screen hostiles and avoid convoy losses";
        }
        return "Must survive for mission success";
    }

    private static String recoverableWreckObjectiveSubtitle(CampaignState st, RecoverableWreckSite wreck) {
        if (wreck == null) return "Optional fleet recovery opportunity";
        if (st != null && st.salvageUnderFireObjectiveActive) {
            int progress = (int) Math.round(MathUtil.clamp(
                    wreck.underFireProgressSec / Math.max(1.0, st.salvageUnderFireGoalSec), 0.0, 1.0) * 100.0);
            return "SALVAGE UNDER FIRE  |  hold wreck " + progress + "%";
        }
        return wreck.subtitle.isBlank() ? "Optional fleet recovery opportunity" : wreck.subtitle;
    }

    private static void addTacticalDeploymentPreviewMarkers(GameContext ctx,
                                                            CampaignState st,
                                                            ArrayList<CampaignObjectiveMarker> out) {
        if (ctx == null || st == null || out == null) return;
        GameContext.FleetFormation formation = (ctx.command == null || ctx.command.alliedFleetFormation == null)
                ? GameContext.FleetFormation.WEDGE
                : ctx.command.alliedFleetFormation;
        if (st.galaxyEncounterActive && !st.galaxyAmbientEncounterActive) {
            out.add(new CampaignObjectiveMarker(
                    ObjectiveMarkerType.OPTIONAL_OBJECTIVE,
                    "Deployment Preview: " + formation.name(),
                    preBattleFormationEffect(formation),
                    Faction.ALLY,
                    openSpaceFleetClashLaneX(ctx, st, -1),
                    openSpaceFleetClashCenterY(ctx, st),
                    Math.max(210.0, openSpaceFleetClashLaneSpacing(ctx) * 0.24),
                    86));
            return;
        }
        int row = Math.max(0, Math.min(missionSubzoneRows() - 1, 1));
        int allied = missionSubzoneIndex(0, row);
        if (allied >= 0) {
            out.add(new CampaignObjectiveMarker(
                    ObjectiveMarkerType.OPTIONAL_OBJECTIVE,
                    "Deployment Preview: " + formation.name(),
                    preBattleFormationEffect(formation),
                    Faction.ALLY,
                    missionSubzoneCenterX(ctx, st.sector, allied),
                    missionSubzoneCenterY(ctx, st.sector, allied),
                    Math.max(220.0, missionLayout(ctx).subzoneWidth * 0.28),
                    86));
        }
    }

    private static void addOpenSpaceZoneOwnershipMarkers(GameContext ctx, CampaignState st, ArrayList<CampaignObjectiveMarker> out) {
        if (ctx == null || st == null || out == null) return;
        int row = Math.max(0, Math.min(missionSubzoneRows() - 1, 1));
        int allied = missionSubzoneIndex(0, row);
        int neutral = missionSubzoneIndex(Math.max(0, missionSubzoneColumns() / 2), row);
        int hostile = missionSubzoneIndex(Math.max(0, missionSubzoneColumns() - 1), row);
        if (st.galaxyEncounterActive && !st.galaxyAmbientEncounterActive) {
            addOpenSpaceLaneOwnershipMarker(ctx, st, out, -1, "Allied Spawn Zone", "Left zone: player and committed allies enter here", Faction.ALLY, 64);
            addOpenSpaceLaneOwnershipMarker(ctx, st, out, 0, "Neutral Transit Zone", "Middle zone: maneuver space, no default owner", null, 62);
            addOpenSpaceLaneOwnershipMarker(ctx, st, out, 1, "Hostile Contact Zone", "Right zone: enemy fleet deployment area", Faction.ENEMY, 64);
        } else {
            addZoneOwnershipMarker(ctx, st, out, allied, "Allied Spawn Zone", "Left zone: player and committed allies enter here", Faction.ALLY, 64);
            addZoneOwnershipMarker(ctx, st, out, neutral, "Neutral Transit Zone", "Middle zone: maneuver space, no default owner", null, 62);
            addZoneOwnershipMarker(ctx, st, out, hostile, "Hostile Contact Zone", "Right zone: enemy fleet deployment area", Faction.ENEMY, 64);
        }
    }

    private static void addOpenSpaceLaneOwnershipMarker(GameContext ctx,
                                                        CampaignState st,
                                                        ArrayList<CampaignObjectiveMarker> out,
                                                        int lane,
                                                        String label,
                                                        String subtitle,
                                                        Faction faction,
                                                        int priority) {
        out.add(new CampaignObjectiveMarker(
                ObjectiveMarkerType.OPTIONAL_OBJECTIVE,
                label,
                subtitle,
                faction,
                openSpaceFleetClashLaneX(ctx, st, lane),
                openSpaceFleetClashCenterY(ctx, st),
                Math.max(220.0, openSpaceFleetClashLaneSpacing(ctx) * 0.28),
                priority));
    }

    private static void addZoneOwnershipMarker(GameContext ctx,
                                               CampaignState st,
                                               ArrayList<CampaignObjectiveMarker> out,
                                               int subzone,
                                               String label,
                                               String subtitle,
                                               Faction faction,
                                               int priority) {
        if (subzone < 0) return;
        out.add(new CampaignObjectiveMarker(
                ObjectiveMarkerType.OPTIONAL_OBJECTIVE,
                label,
                subtitle,
                faction,
                missionSubzoneCenterX(ctx, st.sector, subzone),
                missionSubzoneCenterY(ctx, st.sector, subzone),
                Math.max(260.0, missionLayout(ctx).subzoneWidth * 0.34),
                priority));
    }

    static List<CampaignSupportMarker> activeSupportMarkers(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !st.enabled) return List.of();
        cleanupInvalidCampaignForceReferences(st);
        double detectionRange = strategicDetectionRange(ctx, st);
        if (isStrategicOvermapMode(st)) {
            ArrayList<CampaignSupportMarker> out = new ArrayList<>();
            for (CampaignLocation area : st.galaxyAreasOfInterest) {
                if (area == null || !area.discovered) continue;
                if (area.type == CampaignLocationType.ENEMY_ACTIVITY
                        && !hasLiveHostileSourceNearLocation(st, area, 420.0)) {
                    continue;
                }
                SupportMarkerType type = switch (area.type) {
                    case RESOURCE_ZONE -> SupportMarkerType.RESOURCE;
                    case SALVAGE_FIELD -> SupportMarkerType.SALVAGE;
                    case DISTRESS_SIGNAL, STORY_EVENT, REPAIR_SITE -> SupportMarkerType.FACTION_CONTACT;
                    case ENEMY_ACTIVITY -> SupportMarkerType.HAZARD;
                    case HIDDEN_CACHE -> SupportMarkerType.INTEL;
                    default -> SupportMarkerType.ANOMALY;
                };
                String label = (type == SupportMarkerType.FACTION_CONTACT)
                        ? factionFacingContactLabel(area)
                        : area.name;
                String subtitle = contactIntelQualityLabel(area.intelQuality) + "  |  " + campaignSiteMemorySubtitle(area);
                out.add(new CampaignSupportMarker(type, label, subtitle, area.x, area.y, 120.0, 40));
                addDynamicTheaterMarkers(out, area);
            }
            for (CampaignLocation poi : st.galaxyMainPois) {
                if (poi == null || !poi.discovered) continue;
                addDynamicTheaterMarkers(out, poi);
                out.addAll(missionOuterThreatMarkers(poi));
            }
            for (GalaxySearchGroup group : st.galaxySearchGroups) {
                CampaignSupportMarker marker = supportMarkerForGalaxySearchGroup(group);
                if (marker != null) out.add(marker);
            }
            for (StrategicStrikeObject strike : st.strategicStrikeObjects) {
                CampaignSupportMarker marker = supportMarkerForStrategicStrike(strike);
                if (marker != null) out.add(marker);
            }
            for (CampaignBattle battle : st.campaignBattles) {
                CampaignSupportMarker marker = supportMarkerForCampaignBattle(battle);
                if (marker != null) out.add(marker);
            }
            for (PendingHostileReinforcement pending : st.pendingHostileReinforcements) {
                if (pending == null) continue;
                String quality = pending.warnedMid ? "TRACKED" : "POSSIBLE CONTACT";
                String eta = Math.max(1, (int) Math.ceil(pending.etaSec)) + "s";
                out.add(new CampaignSupportMarker(
                        SupportMarkerType.INTEL,
                        "Hostile Launch Source: " + pending.label,
                        quality + "  |  origin ping  |  ETA " + eta,
                        Faction.ENEMY,
                        pending.sourceX,
                        pending.sourceY,
                        130.0,
                        68));
                out.add(new CampaignSupportMarker(
                        SupportMarkerType.HAZARD,
                        "Incoming Threat Lane: " + pending.label,
                        quality + "  |  projected target  |  ETA " + eta,
                        Faction.ENEMY,
                        pending.targetX,
                        pending.targetY,
                        150.0,
                        72));
            }
            out.removeIf(marker -> marker == null
                    || !isWithinStrategicDetectionRange(st, marker.x, marker.y, detectionRange));
            HashSet<String> seen = new HashSet<>();
            for (CampaignSupportMarker marker : out) {
                if (marker == null) continue;
                seen.add(marker.type + "|" + marker.label + "|" + Math.round(marker.x / 25.0) + "|" + Math.round(marker.y / 25.0));
            }
            addCampaignForceMarkers(ctx, st, out, seen);
            ensureNarrativeSupportMarker(ctx, st, out, seen);
            return out;
        }
        ArrayList<CampaignSupportMarker> out = new ArrayList<>();
        HashSet<String> seen = new HashSet<>();
        if (st.galaxyAmbientEncounterActive) {
            addAmbientEncounterSupportMarkers(ctx, st, out, seen);
        }
        for (DiscoverySignalSite site : discoverySignalSites(ctx)) {
            CampaignSupportMarker marker = supportMarkerFor(site);
            if (marker == null) continue;
            if (!isLocalMissionSupportMarker(ctx, st, marker)) continue;
            String key = marker.type + "|" + marker.label + "|" + Math.round(marker.x / 25.0) + "|" + Math.round(marker.y / 25.0);
            if (!seen.add(key)) continue;
            out.add(marker);
        }
        return out;
    }

    private static boolean isLocalMissionSupportMarker(GameContext ctx, CampaignState st, CampaignSupportMarker marker) {
        if (ctx == null || st == null || marker == null) return false;
        if (!usesMissionSubzones(ctx)) return true;
        int loaded = currentLoadedMissionSubzone(ctx);
        if (loaded < 0 && ctx.player != null) {
            loaded = missionSubzoneForPoint(ctx, st.sector, ctx.player.x, ctx.player.y);
        }
        if (loaded < 0) return true;
        return missionSubzoneForPoint(ctx, st.sector, marker.x, marker.y) == loaded;
    }

    private static void ensureNarrativeSupportMarker(GameContext ctx,
                                                     CampaignState st,
                                                     ArrayList<CampaignSupportMarker> out,
                                                     HashSet<String> seen) {
        if (ctx == null || st == null || out == null || seen == null) return;
        boolean hasNarrative = out.stream().anyMatch(marker -> marker != null
                && (marker.type == SupportMarkerType.ANOMALY
                || marker.type == SupportMarkerType.FACTION_CONTACT && isFactionFacingContactLabel(marker.label)
                || marker.type == SupportMarkerType.INTEL));
        if (hasNarrative) return;
        CampaignLocation anchor = currentCampaignLocation(ctx);
        if (anchor == null) anchor = selectedCampaignLocation(ctx);
        if (anchor == null && !st.galaxyMainPois.isEmpty()) anchor = st.galaxyMainPois.get(0);
        if (anchor == null) return;
        CampaignSupportMarker fallback = new CampaignSupportMarker(
                SupportMarkerType.FACTION_CONTACT,
                factionFacingContactLabel(anchor),
                "Local actors are active; investigate nearby tracks for classified contacts.",
                ambientLocationFaction(st, anchor),
                GameMath.clamp(anchor.x + 132.0, 0.0, ctx.WORLD_W),
                GameMath.clamp(anchor.y + 84.0, 0.0, ctx.WORLD_H),
                88.0,
                28);
        addSupportMarker(out, seen, fallback);
    }

    private static boolean isFactionFacingContactLabel(String label) {
        if (label == null) return false;
        return label.startsWith("Broker Contact - ")
                || label.startsWith("Coalition Contact - ")
                || label.startsWith("Detention Contact - ")
                || label.startsWith("Support Contact - ");
    }

    private static void addCampaignForceMarkers(GameContext ctx,
                                                CampaignState st,
                                                ArrayList<CampaignSupportMarker> out,
                                                HashSet<String> seen) {
        if (ctx == null || st == null || out == null || seen == null) return;
        ensureCampaignForceOwnership(ctx, st);
        double detectionRange = strategicDetectionRange(ctx, st);
        boolean scopedToActiveEncounter = st.galaxyEncounterActive && !st.activeGalaxyEncounterForceIds.isEmpty();
        for (CampaignForce force : st.campaignForces) {
            if (scopedToActiveEncounter && (force == null || !st.activeGalaxyEncounterForceIds.contains(force.id))) {
                continue;
            }
            CampaignSupportMarker marker = supportMarkerForCampaignForce(ctx, st, force);
            if (marker == null || !isWithinStrategicDetectionRange(st, marker.x, marker.y, detectionRange)) continue;
            addSupportMarker(out, seen, marker);
            CampaignSupportMarker blockade = supportMarkerForMovingBlockadeLine(force);
            if (blockade != null && isWithinStrategicDetectionRange(st, blockade.x, blockade.y, detectionRange)) {
                addSupportMarker(out, seen, blockade);
            }
        }
    }

    private static boolean hasLiveHostileSourceNearLocation(CampaignState st, CampaignLocation location, double radius) {
        if (st == null || location == null) return false;
        double r2 = Math.max(1.0, radius) * Math.max(1.0, radius);
        for (CampaignForce force : st.campaignForces) {
            if (force == null || force.destroyed || !force.simulationActive || force.faction != Faction.ENEMY) continue;
            if (force.shipIds.isEmpty() && force.linkedSearchGroupId <= 0 && force.strength <= 12.0) continue;
            if (GameMath.dist2(force.x, force.y, location.x, location.y) <= r2) return true;
        }
        for (GalaxySearchGroup group : st.galaxySearchGroups) {
            if (group == null || !group.hostile) continue;
            if (GameMath.dist2(group.x, group.y, location.x, location.y) <= r2) return true;
        }
        for (PendingHostileReinforcement pending : st.pendingHostileReinforcements) {
            if (pending == null) continue;
            if (!pending.targetLocationId.isBlank() && pending.targetLocationId.equals(location.id)) return true;
            if (GameMath.dist2(pending.targetX, pending.targetY, location.x, location.y) <= r2) return true;
        }
        return false;
    }

    private static void addDynamicTheaterMarkers(ArrayList<CampaignSupportMarker> out, CampaignLocation location) {
        if (out == null || location == null) return;
        String scar = campaignScarLine(location);
        String route = campaignRouteStateLine(location);
        String contact = recurringContactName(location.recurringContactId);
        Faction locationFaction = locationDisplayMarkerFaction(location);
        Faction contactFaction = recurringContactMarkerFaction(location.recurringContactId);
        if (!scar.isBlank()) {
            SupportMarkerType scarType = (location.type == CampaignLocationType.ENEMY_ACTIVITY || location.primaryMission)
                    ? SupportMarkerType.HAZARD
                    : SupportMarkerType.SALVAGE;
            out.add(new CampaignSupportMarker(
                    scarType,
                    location.name + " Scar",
                    scar,
                    scarType == SupportMarkerType.HAZARD ? Faction.ENEMY : locationFaction,
                    location.x + 52.0,
                    location.y - 44.0,
                    90.0,
                    26));
        }
        if (!route.isBlank()) {
            out.add(new CampaignSupportMarker(
                    location.supportRouteStabilized ? SupportMarkerType.FACTION_CONTACT : SupportMarkerType.INTEL,
                    location.supportRouteStabilized ? "Stabilized Route" : "Lane State",
                    route,
                    locationFaction,
                    location.x - 46.0,
                    location.y + 42.0,
                    86.0,
                    24));
        }
        if (!contact.isBlank()) {
            out.add(new CampaignSupportMarker(
                    SupportMarkerType.INTEL,
                    contact,
                    recurringContactStatus(null, location),
                    (contactFaction != null) ? contactFaction : locationFaction,
                    location.x + 34.0,
                    location.y + 60.0,
                    80.0,
                    22));
        }
    }

    private static String factionFacingContactLabel(CampaignLocation location) {
        if (location == null || location.name == null || location.name.isBlank()) return "Support Contact - Local";
        String name = location.name.trim();
        String upper = name.toUpperCase(Locale.US);
        if (upper.contains("BROKER")) return "Broker Contact - " + name;
        if (upper.contains("COALITION")) return "Coalition Contact - " + name;
        if (upper.contains("DETENTION")) return "Detention Contact - " + name;
        return "Support Contact - " + name;
    }

    private static List<SiteResolutionMode> availableSiteResolutionModes(CampaignLocation location) {
        if (location == null) return List.of();
        return switch (location.type) {
            case RESOURCE_ZONE, SALVAGE_FIELD, HIDDEN_CACHE -> List.of(
                    SiteResolutionMode.FAST_STRIP,
                    SiteResolutionMode.CAREFUL_SECURE,
                    SiteResolutionMode.MARK_FOR_ALLIES);
            case DISTRESS_SIGNAL -> List.of(
                    SiteResolutionMode.EVAC_SURVIVORS,
                    SiteResolutionMode.TOW_DAMAGED_HULL,
                    SiteResolutionMode.STRIP_FOR_PARTS);
            case STORY_EVENT -> List.of(
                    SiteResolutionMode.QUIET_DECODE,
                    SiteResolutionMode.ALLY_BROADCAST,
                    SiteResolutionMode.JAM_AND_DESTROY);
            default -> List.of();
        };
    }

    private static SiteResolutionMode resolveSiteResolutionMode(String raw, CampaignLocation location) {
        List<SiteResolutionMode> available = availableSiteResolutionModes(location);
        if (available.isEmpty()) return SiteResolutionMode.CAREFUL_SECURE;
        SiteResolutionMode parsed = parseEnum(raw, available.get(0));
        return available.contains(parsed) ? parsed : available.get(0);
    }

    private static String siteResolutionModeLabel(SiteResolutionMode mode) {
        if (mode == null) return "";
        return switch (mode) {
            case FAST_STRIP -> "Fast Strip";
            case CAREFUL_SECURE -> "Careful Secure";
            case MARK_FOR_ALLIES -> "Mark For Allies";
            case EVAC_SURVIVORS -> "Evacuate Survivors";
            case TOW_DAMAGED_HULL -> "Tow Damaged Hull";
            case STRIP_FOR_PARTS -> "Strip For Parts";
            case QUIET_DECODE -> "Quiet Decode";
            case ALLY_BROADCAST -> "Ally Broadcast";
            case JAM_AND_DESTROY -> "Jam And Destroy";
        };
    }

    private static String siteResolutionModeDetail(CampaignLocation location, SiteResolutionMode mode) {
        if (location == null || mode == null) return "";
        return switch (mode) {
            case FAST_STRIP -> "more immediate payout, more exposure, rougher site scar";
            case CAREFUL_SECURE -> "safer recovery, steadier intel, lower exposure";
            case MARK_FOR_ALLIES -> "less direct payout, stronger favor and route support";
            case EVAC_SURVIVORS -> "favor gain, lower material reward, safer lane aftermath";
            case TOW_DAMAGED_HULL -> "better chance to recover a hull, slower and costlier extraction";
            case STRIP_FOR_PARTS -> "more salvage, harsher reputation and distress memory";
            case QUIET_DECODE -> "best intel, lower exposure, slower payoff";
            case ALLY_BROADCAST -> "more favor and support-route gains, more exposure";
            case JAM_AND_DESTROY -> "cuts pressure and enemy intel, loses softer rewards";
        };
    }

    private static void addAmbientEncounterSupportMarkers(GameContext ctx, CampaignState st,
                                                          ArrayList<CampaignSupportMarker> out,
                                                          HashSet<String> seen) {
        if (ctx == null || st == null || out == null || seen == null) return;
        double centerX = ambientEncounterCenterX(ctx, st);
        double centerY = ambientEncounterCenterY(ctx, st);
        double pocketRadius = ambientEncounterRadius(st);
        CampaignLocation site = campaignLocationById(st, st.activeGalaxyEncounterLocationId);
        if (site != null) {
            addSupportMarker(out, seen, new CampaignSupportMarker(
                    SupportMarkerType.INTEL,
                    "Pocket Center",
                    "Compact local operating area  |  important contacts are clustered inside this ring",
                    centerX, centerY, Math.max(180.0, pocketRadius), 72));
        }

        int addedShips = 0;
        for (Ship ship : ctx.ships) {
            if (ship == null || ship == ctx.player || !ship.alive || ship.dying || ship.hp <= 0 || ship.faction == null) continue;
            boolean friendly = ctx.player != null && ctx.player.faction != null && ship.faction.isFriendlyTo(ctx.player.faction);
            SupportMarkerType type = friendly ? SupportMarkerType.FACTION_CONTACT : SupportMarkerType.HAZARD;
            String subtitle = friendly ? "Friendly local traffic" : "Hostile local traffic";
            addSupportMarker(out, seen, new CampaignSupportMarker(
                    type,
                    displayShipName(ship, friendly ? "Friendly Contact" : "Hostile Contact"),
                    subtitle,
                    ship.faction,
                    ship.x, ship.y,
                    Math.max(120.0, ship.radius * 2.4),
                    friendly ? 58 : 68));
            addedShips++;
            if (addedShips >= 10) break;
        }

        int addedAsteroids = 0;
        for (Asteroid asteroid : ctx.asteroids) {
            if (asteroid == null || asteroid.ore <= 0) continue;
            addSupportMarker(out, seen, new CampaignSupportMarker(
                    SupportMarkerType.RESOURCE,
                    asteroid.rich ? "Rich Ore Pocket" : "Ore Pocket",
                    "Mineable asteroid cluster",
                    asteroid.x, asteroid.y,
                    Math.max(100.0, asteroid.radius * 5.0),
                    52));
            addedAsteroids++;
            if (addedAsteroids >= 8) break;
        }

        int addedSalvage = 0;
        for (Salvage salvage : ctx.salvage) {
            if (salvage == null || !salvage.alive()) continue;
            addSupportMarker(out, seen, new CampaignSupportMarker(
                    SupportMarkerType.SALVAGE,
                    "Recovery Drift",
                    "Recoverable wreckage and loose stores",
                    salvage.x, salvage.y,
                    110.0,
                    54));
            addedSalvage++;
            if (addedSalvage >= 8) break;
        }
    }

    private static void addSupportMarker(ArrayList<CampaignSupportMarker> out,
                                         HashSet<String> seen,
                                         CampaignSupportMarker marker) {
        if (out == null || seen == null || marker == null) return;
        String key = marker.type + "|" + marker.label + "|" + Math.round(marker.x / 25.0) + "|" + Math.round(marker.y / 25.0);
        if (!seen.add(key)) return;
        out.add(marker);
    }

    private static void addLiveHostileShipMarkers(GameContext ctx,
                                                  CampaignState st,
                                                  ArrayList<CampaignSupportMarker> out,
                                                  HashSet<String> seen) {
        if (ctx == null || st == null || out == null || seen == null || ctx.ships == null || ctx.player == null) return;
        for (Ship ship : ctx.ships) {
            if (ship == null || ship == ctx.player || !ship.alive || ship.dying || ship.hp <= 0) continue;
            if (ship.faction == null || ship.faction.isFriendlyTo(ctx.player.faction)) continue;
            String label = displayShipName(ship, "Hostile Hull");
            String subtitle = "Tracked  |  Hostile hull  |  " + localRangeBearingReadout(ctx, ship.x, ship.y);
            addSupportMarker(out, seen, new CampaignSupportMarker(
                    SupportMarkerType.HAZARD,
                    label,
                    subtitle,
                    ship.faction,
                    ship.x,
                    ship.y,
                    Math.max(72.0, ship.radius * 2.6),
                    72));
        }
    }

    static List<CampaignSupportMarker> strategicTaskForceMarkers(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !st.enabled) return List.of();
        if (st.galaxyEncounterActive && !st.galaxyAmbientEncounterActive) return List.of();
        ArrayList<CampaignSupportMarker> out = new ArrayList<>();
        HashSet<String> seen = new HashSet<>();
        addLiveHostileShipMarkers(ctx, st, out, seen);
        if (!st.strategicTaskForces.isEmpty()) {
            for (StrategicTaskForce taskForce : st.strategicTaskForces) {
                CampaignSupportMarker marker = supportMarkerForTaskForce(ctx, st, taskForce);
                addSupportMarker(out, seen, marker);
            }
        }
        for (CampaignSupportMarker marker : strategicDivisionMarkers(ctx)) {
            addSupportMarker(out, seen, marker);
        }
        return out;
    }

    private static List<CampaignSupportMarker> strategicDivisionMarkers(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || st.strategicDivisions.isEmpty() || isStrategicOvermapMode(st)) return List.of();
        ArrayList<CampaignSupportMarker> out = new ArrayList<>();
        for (StrategicDivisionState division : st.strategicDivisions.values()) {
            if (division == null) continue;
            int subzone = Math.max(0, division.currentSubzone);
            double x = missionSubzoneCenterX(ctx, st.sector, subzone);
            double y = missionSubzoneCenterY(ctx, st.sector, subzone);
            String move = (division.transitRemainingSec > 0.0 && division.targetSubzone >= 0 && division.targetSubzone != division.currentSubzone)
                    ? " moving to " + localRangeBearingReadout(ctx,
                    missionSubzoneCenterX(ctx, st.sector, Math.max(0, division.targetSubzone)),
                    missionSubzoneCenterY(ctx, st.sector, Math.max(0, division.targetSubzone)))
                    : " holding " + localRangeBearingReadout(ctx, x, y);
            out.add(new CampaignSupportMarker(
                    SupportMarkerType.FACTION_CONTACT,
                    strategicDivisionLabel(st, division.groupId),
                    division.stance.name() + move + "  |  ships " + strategicDivisionShipCount(st, division.groupId),
                    Faction.ALLY,
                    x,
                    y,
                    135.0,
                    division.groupId == CAMPAIGN_FLAGSHIP_COMMAND_GROUP ? 64 : 70));
        }
        return out;
    }

    static CampaignSupportMarker nearestStrategicTaskForceMarker(GameContext ctx, double x, double y, double maxDist) {
        List<CampaignSupportMarker> markers = strategicTaskForceMarkers(ctx);
        if (markers.isEmpty()) return null;
        CampaignSupportMarker best = null;
        double bestD2 = Math.max(1.0, maxDist) * Math.max(1.0, maxDist);
        for (CampaignSupportMarker marker : markers) {
            if (marker == null) continue;
            double range = Math.max(maxDist, marker.radius);
            double d2 = GameMath.dist2(x, y, marker.x, marker.y);
            if (d2 > range * range) continue;
            if (best == null || d2 < bestD2 || (Math.abs(d2 - bestD2) < 1e-6 && marker.priority > best.priority)) {
                best = marker;
                bestD2 = d2;
            }
        }
        return best;
    }

    static String strategicMapActionSummary(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !st.enabled) return "";
        if (isStrategicOvermapMode(st)) {
            String theaterSummary = strategicTheaterCompactSummary(st);
            CampaignTravelState travel = st.galaxyTravel;
            if (travel.traveling) {
                CampaignLocation destination = campaignLocationById(st, travel.destinationId);
                int eta = (int) Math.ceil(Math.max(0.0, (1.0 - travel.progress) * travel.durationSec));
                return "TRAVEL: " + ((destination == null) ? "EN ROUTE" : destination.name.toUpperCase(Locale.US))
                        + "  ETA " + eta + "S  RISK " + (int) Math.round(travel.interceptionRisk) + "%"
                        + "  INTEL " + (int) Math.round(st.campaignIntelLevel)
                        + theaterSummary;
            }
            return "FLEET HOLDING  |  INTEL " + (int) Math.round(st.campaignIntelLevel)
                    + "  EXPOSURE " + (int) Math.round(st.strategicExposureLevel)
                    + theaterSummary
                    + "  |  SELECT A DESTINATION, PRESS T TO CRUISE, H TO HOLD, OR DOUBLE-CLICK TO DEPART";
        }
        int torpedoes = Math.max(0, st.strategicTorpedoCharges);
        int sortieCap = strategicSortieCapacity(ctx);
        int sortiesLeft = Math.max(0, sortieCap - st.strategicSortiesLaunched);
        int atomic = Math.max(0, st.strategicAtomicCharges);
        return "TORPEDOES " + torpedoes + "  SORTIES " + sortiesLeft + "  ATOMIC " + atomic
                + "  INTEL " + (int) Math.round(st.campaignIntelLevel)
                + "  EXPOSURE " + (int) Math.round(st.strategicExposureLevel);
    }

    private static String strategicTheaterCompactSummary(CampaignState st) {
        if (st == null || st.campaignTheaters.isEmpty()) return "";
        StringBuilder sb = new StringBuilder("  |  THEATERS ");
        for (CampaignTheaterState theater : st.campaignTheaters) {
            if (theater == null || theater.id == null) continue;
            if (sb.charAt(sb.length() - 1) != ' ') sb.append(' ');
            char key = switch (theater.id) {
                case SOUTHERN -> 'S';
                case FRONTIER -> 'F';
                case LUNAR -> 'L';
                case EARTH -> 'E';
            };
            sb.append(key).append(':').append(theaterControlShortToken(theater.controlState));
        }
        return sb.toString();
    }

    private static String theaterControlShortToken(TheaterControlState state) {
        if (state == null) return "CT";
        return switch (state) {
            case BLUE_GREEN_CONTROLLED -> "BG";
            case RED_CONTROLLED -> "RD";
            case CONTESTED -> "CT";
        };
    }

    static List<String> strategicDivisionSummaryLines(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || st.strategicDivisions.isEmpty()) return List.of();
        if (isStrategicOvermapMode(st)) return List.of();
        ArrayList<String> out = new ArrayList<>();
        for (StrategicDivisionState division : st.strategicDivisions.values()) {
            if (division == null) continue;
            String label = strategicDivisionLabel(st, division.groupId);
            int strength = (int) Math.round(strategicDivisionStrength(st, division.groupId));
            int ships = strategicDivisionShipCount(st, division.groupId);
            String zone = localRangeBearingReadout(ctx,
                    missionSubzoneCenterX(ctx, st.sector, Math.max(0, division.currentSubzone)),
                    missionSubzoneCenterY(ctx, st.sector, Math.max(0, division.currentSubzone)));
            String move = (division.transitRemainingSec > 0.0 && division.targetSubzone >= 0 && division.targetSubzone != division.currentSubzone)
                    ? (" -> " + localRangeBearingReadout(ctx,
                    missionSubzoneCenterX(ctx, st.sector, Math.max(0, division.targetSubzone)),
                    missionSubzoneCenterY(ctx, st.sector, Math.max(0, division.targetSubzone))))
                    : "";
            String selected = (ctx.ui != null && ctx.ui.selectedStrategicDivisionGroupId == division.groupId) ? " *" : "";
            out.add(label + "  " + division.stance.name() + "  " + zone + move + "  STR " + strength + "  SHIPS " + ships + selected);
            if (out.size() >= 6) break;
        }
        return out;
    }

    public static boolean cycleStrategicDivisionSelection(GameContext ctx, int dir) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || st.strategicDivisions.isEmpty()) return false;
        ArrayList<Integer> ids = new ArrayList<>(st.strategicDivisions.keySet());
        ids.sort(Integer::compareTo);
        int current = ctx.ui.selectedStrategicDivisionGroupId;
        int idx = ids.indexOf(current);
        if (idx < 0) idx = 0;
        int step = (dir < 0) ? -1 : 1;
        idx = Math.floorMod(idx + step, ids.size());
        ctx.ui.selectedStrategicDivisionGroupId = ids.get(idx);
        StrategicDivisionState division = st.strategicDivisions.get(ctx.ui.selectedStrategicDivisionGroupId);
        if (division != null) {
            EventSystem.showBanner(ctx,
                    "DIVISION SELECTED: " + strategicDivisionLabel(st, division.groupId) + " " + division.stance.name(),
                    1.0);
        }
        return true;
    }

    public static boolean issueStrategicDivisionOrder(GameContext ctx, double worldX, double worldY) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || st.strategicDivisions.isEmpty()) return false;
        int groupId = ctx.ui.selectedStrategicDivisionGroupId;
        StrategicDivisionState division = st.strategicDivisions.get(groupId);
        if (division == null) return false;
        if (groupId == CAMPAIGN_FLAGSHIP_COMMAND_GROUP) {
            EventSystem.showBanner(ctx, "FLAG DIVISION FOLLOWS THE COMMAND SHIP", 1.2);
            return true;
        }
        int subzone = missionSubzoneForPoint(ctx, st.sector, worldX, worldY);
        if (subzone < 0) {
            EventSystem.showBanner(ctx, "DIVISION ORDER FAILED: TARGET OUTSIDE LOCAL OPERATING AREA", 1.2);
            return true;
        }
        division.targetSubzone = subzone;
        division.lastOrderX = GameMath.clamp(worldX, 0.0, ctx.WORLD_W);
        division.lastOrderY = GameMath.clamp(worldY, 0.0, ctx.WORLD_H);
        if (division.currentSubzone == subzone) {
            division.transitRemainingSec = 0.0;
            EventSystem.showBanner(ctx, "DIVISION HOLDING " + localRangeBearingReadout(ctx, worldX, worldY), 1.1);
            return true;
        }
        division.transitRemainingSec = strategicDivisionTransitSeconds(division, division.currentSubzone, subzone);
        EventSystem.showBanner(ctx,
                "DIVISION ORDER: " + strategicDivisionLabel(st, groupId) + " -> " + localRangeBearingReadout(ctx, worldX, worldY),
                1.3);
        return true;
    }

    public static boolean createDetachedStrategicDivision(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !st.enabled) return false;
        PersistentFleetEntry anchor = chooseDetachmentAnchor(st);
        if (anchor == null) {
            EventSystem.showBanner(ctx, "NO FLAGSHIP-ASSIGNED SHIP AVAILABLE TO DETACH", 1.4);
            return true;
        }
        anchor.commandGroupId = anchor.slotId;
        PersistentFleetEntry escort = chooseDetachmentEscort(st, anchor);
        if (escort != null) {
            escort.commandGroupId = anchor.slotId;
        }
        StrategicDivisionState flagship = st.strategicDivisions.get(CAMPAIGN_FLAGSHIP_COMMAND_GROUP);
        int subzone = (flagship == null) ? currentLoadedMissionSubzone(ctx) : flagship.currentSubzone;
        if (subzone < 0 && ctx.player != null) {
            subzone = missionSubzoneForPoint(ctx, st.sector, ctx.player.x, ctx.player.y);
        }
        if (subzone < 0) subzone = missionSubzoneIndex(0, 1);
        st.strategicDivisions.put(anchor.slotId,
                new StrategicDivisionState(anchor.slotId, defaultDivisionStance(anchor), subzone));
        if (ctx.ui != null) {
            ctx.ui.selectedStrategicDivisionGroupId = anchor.slotId;
        }
        String escortLabel = (escort == null) ? "" : " + " + displayPersistentFleetEntryName(escort);
        EventSystem.showBanner(ctx,
                "DIVISION DETACHED: " + displayPersistentFleetEntryName(anchor) + escortLabel,
                1.6);
        return true;
    }

    public static boolean mergeSelectedStrategicDivisionIntoFlagship(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !st.enabled || ctx.ui == null) return false;
        int groupId = ctx.ui.selectedStrategicDivisionGroupId;
        if (groupId == CAMPAIGN_FLAGSHIP_COMMAND_GROUP) {
            EventSystem.showBanner(ctx, "FLAG DIVISION IS ALREADY THE MAIN FLEET", 1.2);
            return true;
        }
        StrategicDivisionState division = st.strategicDivisions.get(groupId);
        StrategicDivisionState flagship = st.strategicDivisions.get(CAMPAIGN_FLAGSHIP_COMMAND_GROUP);
        if (division == null || flagship == null) return false;
        PersistentFleetEntry anchor = persistentFleetEntryBySlotId(st, groupId);
        if (anchor != null && isTitanPersistentEntry(anchor)) {
            EventSystem.showBanner(ctx, "TITAN COMMAND DIVISIONS CANNOT MERGE INTO THE FLAGSHIP GROUP", 1.5);
            return true;
        }
        if (division.currentSubzone != flagship.currentSubzone) {
            EventSystem.showBanner(ctx, "MERGE REQUIRES BOTH DIVISIONS IN THE SAME POCKET", 1.5);
            return true;
        }
        boolean changed = false;
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed) continue;
            if (Math.max(CAMPAIGN_FLAGSHIP_COMMAND_GROUP, entry.commandGroupId) != groupId) continue;
            entry.commandGroupId = CAMPAIGN_FLAGSHIP_COMMAND_GROUP;
            changed = true;
        }
        st.strategicDivisions.remove(groupId);
        ctx.ui.selectedStrategicDivisionGroupId = CAMPAIGN_FLAGSHIP_COMMAND_GROUP;
        if (changed) {
            EventSystem.showBanner(ctx,
                    "DIVISION MERGED INTO FLAG DIVISION: " + strategicDivisionLabel(st, groupId),
                    1.5);
        }
        return true;
    }

    static List<String> strategicTaskForceSummaryLines(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || st.strategicTaskForces.isEmpty()) return List.of();
        if (isStrategicOvermapMode(st)) return List.of();
        ArrayList<String> out = new ArrayList<>();
        for (StrategicTaskForce taskForce : st.strategicTaskForces) {
            if (taskForce == null || taskForce.encounterResolved) continue;
            String prefix = switch (taskForce.kind) {
                case PATROL -> taskForce.hostile ? "PATROL" : "SCREEN";
                case STRIKE -> "STRIKE";
                case STEALTH -> (taskForce.disruptionRemainingSec > 0.0 || taskForce.breakoffRemainingSec > 0.0)
                        ? "STEALTH"
                        : "GHOST";
                case CONVOY -> "CONVOY";
                case SALVAGE -> "SALVAGE";
            };
            String zone = localRangeBearingReadout(ctx,
                    missionSubzoneCenterX(ctx, st.sector, Math.max(0, taskForce.currentSubzone)),
                    missionSubzoneCenterY(ctx, st.sector, Math.max(0, taskForce.currentSubzone)));
            int strengthPct = (taskForce.maxStrength <= 1e-6)
                    ? 100
                    : (int) Math.round(100.0 * MathUtil.clamp(taskForce.currentStrength / taskForce.maxStrength, 0.0, 1.0));
            String pendingSuffix = (ctx != null
                    && ctx.ui != null
                    && ctx.ui.strategicEncounterPrompt.active
                    && ctx.ui.strategicEncounterPrompt.taskForceId == taskForce.id)
                    ? " - PENDING ENGAGEMENT"
                    : "";
            out.add(prefix + " " + taskForce.label + " - " + zone + " - " + strengthPct + "%" + pendingSuffix);
            if (out.size() >= 5) break;
        }
        return out;
    }

    public static boolean hasPendingStrategicEncounterChoice(GameContext ctx) {
        if (ctx == null || ctx.ui == null || ctx.ui.strategicEncounterPrompt == null
                || !ctx.ui.strategicEncounterPrompt.active) return false;
        return switch (ctx.ui.strategicEncounterPrompt.kind) {
            case TASK_FORCE -> ctx.ui.strategicEncounterPrompt.taskForceId > 0;
            case GALAXY_SEARCH_GROUP -> ctx.ui.strategicEncounterPrompt.galaxySearchGroupId > 0;
            case INSTALLATION_THREAT -> ctx.ui.strategicEncounterPrompt.installationThreatId > 0;
            case CAMPAIGN_LOCATION -> ctx.ui.strategicEncounterPrompt.campaignLocationId != null
                    && !ctx.ui.strategicEncounterPrompt.campaignLocationId.isBlank();
            case CAMPAIGN_FORCE -> ctx.ui.strategicEncounterPrompt.campaignForceId > 0;
            case CAMPAIGN_BATTLE -> ctx.ui.strategicEncounterPrompt.campaignBattleId > 0;
        };
    }

    public static boolean hasValidStrategicEncounterResponder(GameContext ctx) {
        if (!hasPendingStrategicEncounterChoice(ctx)) return false;
        CampaignState st = state(ctx);
        if (st == null) return false;
        UiState.StrategicEncounterPrompt prompt = ctx.ui.strategicEncounterPrompt;
        return switch (prompt.kind) {
            case TASK_FORCE -> {
                StrategicTaskForce taskForce = strategicTaskForceById(st, prompt.taskForceId);
                yield taskForce != null && !taskForce.encounterResolved;
            }
            case GALAXY_SEARCH_GROUP -> galaxySearchGroupById(st, prompt.galaxySearchGroupId) != null;
            case INSTALLATION_THREAT -> {
                CampaignInstallationThreatCase threat = installationThreatCaseById(st, prompt.installationThreatId);
                yield threat != null && threat.active && campaignLocationById(st, prompt.campaignLocationId) != null;
            }
            case CAMPAIGN_LOCATION -> {
                CampaignLocation location = campaignLocationById(st, prompt.campaignLocationId);
                yield location != null && !location.completed;
            }
            case CAMPAIGN_FORCE -> {
                CampaignForce force = campaignForceById(st, prompt.campaignForceId);
                yield force != null && !force.destroyed;
            }
            case CAMPAIGN_BATTLE -> {
                CampaignBattle battle = campaignBattleById(st, prompt.campaignBattleId);
                yield battle != null && !battle.resolved;
            }
        };
    }

    private static double strategicReconQualityAgainstTaskForce(GameContext ctx, CampaignState st, StrategicTaskForce taskForce) {
        if (ctx == null || st == null || taskForce == null) return 0.18;
        StrategicRoleProfile roleProfile = friendlyStrategicRoleProfile(ctx, st);
        double recon = 0.16
                + MathUtil.clamp(st.campaignIntelLevel / 100.0, 0.0, 1.0) * 0.48
                + roleProfile.carrierProjection() * 0.22
                + roleProfile.stealthCoverage() * 0.14
                + roleProfile.strikeReach() * 0.08;
        if (taskForce.kind == StrategicTaskForceKind.STEALTH) recon -= 0.18;
        if (taskForce.kind == StrategicTaskForceKind.CONVOY || taskForce.kind == StrategicTaskForceKind.SALVAGE) recon += 0.06;
        if (taskForce.disruptionRemainingSec > 0.0) recon += 0.12;
        if (taskForce.torpedoStrikesSustained + taskForce.sortieStrikesSustained > 0) recon += 0.08;
        return MathUtil.clamp(recon, 0.05, 0.96);
    }

    private static StrategicCountermeasureProfile strategicCountermeasureProfile(GameContext ctx, CampaignState st, StrategicTaskForce taskForce) {
        StrategicCountermeasureProfile profile = new StrategicCountermeasureProfile();
        if (st == null || taskForce == null) return profile;
        switch (taskForce.kind) {
            case PATROL -> {
                profile.interception = 0.18;
                profile.jamming = 0.10;
                profile.decoy = 0.10;
                profile.evasion = 0.12;
                profile.alertResponse = 0.18;
            }
            case STRIKE -> {
                profile.interception = 0.28;
                profile.jamming = 0.14;
                profile.decoy = 0.10;
                profile.evasion = 0.16;
                profile.alertResponse = 0.30;
            }
            case STEALTH -> {
                profile.interception = 0.10;
                profile.jamming = 0.30;
                profile.decoy = 0.24;
                profile.evasion = 0.30;
                profile.alertResponse = 0.24;
            }
            case CONVOY -> {
                profile.interception = 0.12;
                profile.jamming = 0.08;
                profile.decoy = 0.26;
                profile.evasion = 0.24;
                profile.alertResponse = 0.18;
            }
            case SALVAGE -> {
                profile.interception = 0.08;
                profile.jamming = 0.06;
                profile.decoy = 0.18;
                profile.evasion = 0.18;
                profile.alertResponse = 0.12;
            }
        }
        double support = hostileCountermeasureSupport(st, taskForce);
        double alert = MathUtil.clamp(st.enemyAlertLevel / 100.0, 0.0, 1.0);
        double strikeHeat = MathUtil.clamp(st.recentStrikePressure / 100.0, 0.0, 1.0);
        profile.interception = MathUtil.clamp(profile.interception + support * 0.10 + alert * 0.16, 0.0, 0.78);
        profile.jamming = MathUtil.clamp(profile.jamming + support * 0.06 + alert * 0.10, 0.0, 0.78);
        profile.decoy = MathUtil.clamp(profile.decoy + support * 0.05 + strikeHeat * 0.08, 0.0, 0.80);
        profile.evasion = MathUtil.clamp(profile.evasion + alert * 0.10 + strikeHeat * 0.08, 0.0, 0.82);
        profile.alertResponse = MathUtil.clamp(profile.alertResponse + support * 0.08 + alert * 0.20 + strikeHeat * 0.20, 0.0, 0.92);
        return profile;
    }

    private static double hostileCountermeasureSupport(CampaignState st, StrategicTaskForce target) {
        if (st == null || target == null) return 0.0;
        double support = 0.0;
        for (StrategicTaskForce other : st.strategicTaskForces) {
            if (other == null || other == target || other.encounterResolved || !other.hostile) continue;
            int distance = manhattanSubzoneDistance(other.currentSubzone, target.currentSubzone);
            if (distance <= 0) support += 0.18;
            else if (distance == 1) support += 0.10;
            else if (distance == 2) support += 0.05;
        }
        return MathUtil.clamp(support, 0.0, 0.45);
    }

    private static int countHostileCounterInterceptors(CampaignState st, StrategicTaskForce target) {
        if (st == null || target == null) return 0;
        int count = 0;
        for (StrategicTaskForce other : st.strategicTaskForces) {
            if (other == null || other == target || other.encounterResolved || !other.hostile) continue;
            if (manhattanSubzoneDistance(other.currentSubzone, target.currentSubzone) <= 1) {
                count++;
            }
        }
        return count;
    }

    private static void rerouteHostileTaskForcesAfterStrike(GameContext ctx, CampaignState st,
                                                            StrategicTaskForce target,
                                                            StrategicCountermeasureProfile countermeasure) {
        if (ctx == null || st == null || target == null || countermeasure == null) return;
        for (StrategicTaskForce other : st.strategicTaskForces) {
            if (other == null || other == target || other.encounterResolved || !other.hostile) continue;
            int distance = manhattanSubzoneDistance(other.currentSubzone, target.currentSubzone);
            if (distance > 2) continue;
            other.dwellRemainingSec = 0.0;
            other.targetSubzone = target.currentSubzone;
            if (distance > 0) {
                other.transitRemainingSec = Math.max(4.0, other.transitRemainingSec * 0.55);
            }
            if (other.kind == StrategicTaskForceKind.PATROL || other.kind == StrategicTaskForceKind.STRIKE) {
                other.disruptionRemainingSec = Math.max(0.0, other.disruptionRemainingSec - 4.0);
            }
        }
        if (target.currentStrength > 1.0 && countermeasure.evasion >= 0.18) {
            List<Integer> neighbors = strategicNeighborSubzones(target.currentSubzone);
            if (!neighbors.isEmpty()) {
                int playerSubzone = currentLoadedMissionSubzone(ctx);
                neighbors.sort((a, b) -> Integer.compare(manhattanSubzoneDistance(b, playerSubzone), manhattanSubzoneDistance(a, playerSubzone)));
                int fallback = neighbors.get(0);
                if (fallback >= 0 && fallback != target.currentSubzone) {
                    target.targetSubzone = fallback;
                    target.transitRemainingSec = Math.max(5.0, strategicTransitSeconds(target, target.currentSubzone, fallback, friendlyStrategicRoleProfile(ctx, st)) * 0.55);
                    target.dwellRemainingSec = 0.0;
                }
            }
        }
    }

    private static void applyLongRangeStrikeConsequences(GameContext ctx, CampaignState st,
                                                         StrategicTaskForce taskForce,
                                                         String strikeType,
                                                         double reconQuality,
                                                         StrategicCountermeasureProfile countermeasure,
                                                         boolean atomic) {
        if (ctx == null || st == null || taskForce == null || countermeasure == null) return;
        double baseAlert = atomic ? 24.0 : ("SORTIE".equals(strikeType) ? 11.0 : 8.0);
        double baseExposure = atomic ? 28.0 : ("SORTIE".equals(strikeType) ? 13.0 : 10.0);
        double baseStrikePressure = atomic ? 22.0 : ("SORTIE".equals(strikeType) ? 12.0 : 10.0);
        st.enemyAlertLevel = MathUtil.clamp(st.enemyAlertLevel + baseAlert + countermeasure.alertResponse * 18.0, 0.0, 100.0);
        st.strategicExposureLevel = MathUtil.clamp(st.strategicExposureLevel + baseExposure + countermeasure.alertResponse * 16.0, 0.0, 100.0);
        st.recentStrikePressure = MathUtil.clamp(st.recentStrikePressure + baseStrikePressure + countermeasure.alertResponse * 20.0, 0.0, 100.0);
        double intelShift = atomic
                ? (reconQuality * 5.0 - countermeasure.jamming * 12.0)
                : ("SORTIE".equals(strikeType)
                ? (10.0 + reconQuality * 12.0 - countermeasure.jamming * 8.0)
                : (4.0 + reconQuality * 6.0 - countermeasure.jamming * 9.0));
        st.campaignIntelLevel = MathUtil.clamp(st.campaignIntelLevel + intelShift, 0.0, 100.0);
        if (atomic) {
            st.greenContractFavor = Math.max(0, st.greenContractFavor - 2);
            st.yellowLiberationFavor = Math.max(0, st.yellowLiberationFavor - 2);
        }
        rerouteHostileTaskForcesAfterStrike(ctx, st, taskForce, countermeasure);
        for (GalaxySearchGroup group : st.galaxySearchGroups) {
            if (group == null || !group.hostile) continue;
            group.visible = true;
            group.contactFadeSec = Math.max(group.contactFadeSec, atomic ? 24.0 : 16.0);
            if (group.contactConfidence.ordinal() < GalaxyContactConfidence.CONFIRMED_HOSTILE.ordinal()) {
                group.contactConfidence = GalaxyContactConfidence.CONFIRMED_HOSTILE;
            }
            if (st.enemyAlertLevel >= 72.0 || atomic) {
                group.contactConfidence = GalaxyContactConfidence.IDENTIFIED_TASK_FORCE;
                group.identified = true;
            }
            group.behavior = (group.tier >= 3 || atomic) ? GalaxySearchBehavior.INTERCEPTING : GalaxySearchBehavior.INVESTIGATING;
            group.targetX = st.playerGalaxyX;
            group.targetY = st.playerGalaxyY;
            group.stateTimer = Math.max(group.stateTimer, atomic ? 18.0 : 12.0);
        }
    }

    private static void setLastStrikeReport(CampaignState st,
                                            String strikeType,
                                            String targetLabel,
                                            double damageFrac,
                                            boolean destroyed,
                                            boolean atomic) {
        if (st == null) return;
        String cleanedType = (strikeType == null || strikeType.isBlank()) ? "STRIKE" : strikeType.trim().toUpperCase(Locale.US);
        String cleanedTarget = (targetLabel == null || targetLabel.isBlank()) ? "HOSTILE CONTACT" : targetLabel.trim();
        int damage = (int) Math.round(MathUtil.clamp(damageFrac, 0.0, 1.0) * 100.0);
        st.lastStrikeReportTitle = cleanedType + " REPORT  |  " + cleanedTarget.toUpperCase(Locale.US);
        st.lastStrikeReportDetail = destroyed
                ? ("Result: target broken  |  Damage " + damage + "%  |  Heat " + pressureBandLabel(st.recentStrikePressure))
                : ("Result: target disrupted  |  Damage " + damage + "%  |  Heat " + pressureBandLabel(st.recentStrikePressure)
                + (atomic ? "  |  Blast radius severe" : ""));
    }

    private static void beginStrikeCinematic(GameContext ctx,
                                             CampaignState st,
                                             String strikeType,
                                             double sourceX,
                                             double sourceY,
                                             double targetX,
                                             double targetY,
                                             String targetLabel,
                                             double blastRadius,
                                             double damageScale,
                                             boolean atomic,
                                             boolean destroyedTarget) {
        if (ctx == null || st == null) return;
        st.strikeCinematicActive = true;
        st.strikeCinematicType = (strikeType == null || strikeType.isBlank()) ? "TORPEDO" : strikeType.trim();
        st.strikeCinematicSourceLabel = "BLUE MOTHERSHIP";
        st.strikeCinematicTargetLabel = (targetLabel == null || targetLabel.isBlank()) ? "HOSTILE CONTACT" : targetLabel.trim();
        st.strikeCinematicTimer = 0.0;
        st.strikeCinematicSourceX = GameMath.clamp(sourceX, 0.0, ctx.WORLD_W);
        st.strikeCinematicSourceY = GameMath.clamp(sourceY, 0.0, ctx.WORLD_H);
        st.strikeCinematicTargetX = GameMath.clamp(targetX, 0.0, ctx.WORLD_W);
        st.strikeCinematicTargetY = GameMath.clamp(targetY, 0.0, ctx.WORLD_H);
        st.strikeCinematicPayloadX = st.strikeCinematicSourceX;
        st.strikeCinematicPayloadY = st.strikeCinematicSourceY;
        st.strikeCinematicBlastRadius = Math.max(120.0, blastRadius);
        st.strikeCinematicDamageScale = MathUtil.clamp(damageScale, 0.0, 1.6);
        st.strikeCinematicAtomic = atomic;
        st.strikeCinematicDestroyedTarget = destroyedTarget;
        st.cinematicFocusX = st.strikeCinematicSourceX;
        st.cinematicFocusY = st.strikeCinematicSourceY;
        if (ctx.ui != null) {
            ctx.ui.mapOpen = true;
        }
    }

    private static void clearStrikeCinematic(CampaignState st) {
        if (st == null) return;
        st.strikeCinematicActive = false;
        st.strikeCinematicType = "";
        st.strikeCinematicSourceLabel = "";
        st.strikeCinematicTargetLabel = "";
        st.strikeCinematicTimer = 0.0;
        st.strikeCinematicSourceX = Double.NaN;
        st.strikeCinematicSourceY = Double.NaN;
        st.strikeCinematicTargetX = Double.NaN;
        st.strikeCinematicTargetY = Double.NaN;
        st.strikeCinematicPayloadX = Double.NaN;
        st.strikeCinematicPayloadY = Double.NaN;
        st.strikeCinematicBlastRadius = 0.0;
        st.strikeCinematicDamageScale = 0.0;
        st.strikeCinematicAtomic = false;
        st.strikeCinematicDestroyedTarget = false;
    }

    private static void noteStrikeBattleEvent(CampaignState st, String type, String target, String resolution) {
        if (st == null) return;
        st.strikeBattleEventActive = true;
        st.strikeBattleEventType = (type == null || type.isBlank()) ? "STRIKE" : type.trim().toUpperCase(Locale.US);
        st.strikeBattleEventTarget = (target == null || target.isBlank()) ? "HOSTILE CONTACT" : target.trim();
        st.strikeBattleEventResolution = (resolution == null || resolution.isBlank())
                ? "Payload resolved at impact point"
                : resolution.trim();
    }

    public static String campaignStrikeBattleEventSummary(GameContext ctx) {
        CampaignState st = state(ctx);
        if (st == null || !st.strikeBattleEventActive) return "";
        return st.strikeBattleEventType + " IMPACT EVENT  |  "
                + st.strikeBattleEventTarget.toUpperCase(Locale.US)
                + "  |  " + st.strikeBattleEventResolution;
    }

    private static void updateTacticalStrikeBombers(GameContext ctx, CampaignState st, double dt) {
        if (ctx == null || st == null || st.tacticalStrikeBomberEgressTimers.isEmpty()) return;
        ArrayList<Integer> remove = new ArrayList<>();
        for (Map.Entry<Integer, Double> entry : st.tacticalStrikeBomberEgressTimers.entrySet()) {
            int shipId = entry.getKey() == null ? -1 : entry.getKey();
            Ship bomber = findShipById(ctx, shipId);
            if (bomber == null || !bomber.alive || bomber.dying || bomber.hp <= 0) {
                remove.add(shipId);
                continue;
            }
            double remaining = (entry.getValue() == null) ? 0.0 : entry.getValue();
            int payloads = st.tacticalStrikeBomberPayloadsRemaining.getOrDefault(shipId, 0);
            int targetId = st.tacticalStrikeBomberTargetIds.getOrDefault(shipId, -1);
            Ship target = findShipById(ctx, targetId);
            if (remaining < 0.0) {
                if (target == null || !target.alive || target.dying || target.hp <= 0) {
                    target = largestTacticalHostileShip(ctx);
                    if (target != null) {
                        st.tacticalStrikeBomberTargetIds.put(shipId, target.id);
                    }
                }
                if (target != null) {
                    double attackAngle = Math.atan2(target.y - bomber.y, target.x - bomber.x);
                    bomber.angle = attackAngle;
                    bomber.desiredSpeed = Math.max(bomber.desiredSpeed, bomber.desiredSpeedBase * 1.78);
                    bomber.vx = Math.cos(attackAngle) * bomber.desiredSpeed;
                    bomber.vy = Math.sin(attackAngle) * bomber.desiredSpeed;
                    double distance = Math.hypot(target.x - bomber.x, target.y - bomber.y);
                    if (distance <= 5000.0 && payloads > 0) {
                        for (int i = 0; i < payloads; i++) {
                            double lateral = (i - (payloads - 1) * 0.5) * 52.0;
                            int heavyDamage = (target.role == ShipRole.DREADNOUGHT
                                    || target.role == ShipRole.SUPERSHIP
                                    || (target.role != null && target.role.isTitanOrMothership()))
                                    ? Math.max(44, (int) Math.round(target.hpMax * 0.42))
                                    : Math.max(300, target.hpMax + (int) Math.round(target.hpMax * 0.40));
                            Missile missile = spawnTacticalStrikeMissile(ctx,
                                    StrategicStrikePayload.SORTIE,
                                    target,
                                    target.x,
                                    target.y,
                                    lateral,
                                    heavyDamage,
                                    Math.max(120.0, target.radius * 2.6));
                            if (missile != null) {
                                missile.visualScale = 1.55;
                                missile.speed = Math.max(missile.speed, 420.0);
                                missile.turnRate = Math.max(missile.turnRate, Math.toRadians(300.0));
                            }
                        }
                        st.tacticalStrikeBomberPayloadsRemaining.put(shipId, 0);
                        entry.setValue(1.6);
                    }
                    continue;
                }
                entry.setValue(1.4);
                continue;
            }
            remaining = Math.max(0.0, remaining - Math.max(0.0, dt));
            entry.setValue(remaining);
            if (remaining > 1e-6) continue;
            Ship threat = nearestHostileShipTo(ctx, bomber.x, bomber.y, 2600.0);
            double awayAngle = (threat == null) ? bomber.angle : Math.atan2(bomber.y - threat.y, bomber.x - threat.x);
            bomber.angle = awayAngle;
            bomber.desiredSpeed = Math.max(bomber.desiredSpeed, bomber.desiredSpeedBase * 1.58);
            bomber.vx = Math.cos(awayAngle) * bomber.desiredSpeed;
            bomber.vy = Math.sin(awayAngle) * bomber.desiredSpeed;
            bomber.aiForcedEngageTimer = 0.0;
            bomber.aiCommittedTargetId = -1;
            int subzone = ensureShipMissionSubzone(ctx, bomber);
            if (subzone >= 0 && Math.hypot(bomber.x - missionSubzoneCenterX(ctx, st.sector, subzone),
                    bomber.y - missionSubzoneCenterY(ctx, st.sector, subzone)) > missionLayout(ctx).subzoneWidth * 0.82) {
                ctx.ships.remove(bomber);
                remove.add(shipId);
            }
        }
        for (Integer shipId : remove) {
            st.tacticalStrikeBomberEgressTimers.remove(shipId);
            st.tacticalStrikeBomberTargetIds.remove(shipId);
            st.tacticalStrikeBomberPayloadsRemaining.remove(shipId);
        }
    }

    private static Ship nearestHostileShipTo(GameContext ctx, double x, double y, double maxDist) {
        if (ctx == null || ctx.ships == null) return null;
        Ship best = null;
        double bestD2 = Math.max(1.0, maxDist) * Math.max(1.0, maxDist);
        for (Ship ship : ctx.ships) {
            if (ship == null || !ship.alive || ship.dying || ship.hp <= 0) continue;
            if (ctx.player != null && ship == ctx.player) continue;
            if (ship.faction == null || ctx.player == null || ctx.player.faction == null
                    || ship.faction.isFriendlyTo(ctx.player.faction)) continue;
            double d2 = GameMath.dist2(x, y, ship.x, ship.y);
            if (d2 < bestD2) {
                bestD2 = d2;
                best = ship;
            }
        }
        return best;
    }

    private static void updateStrikeCinematic(GameContext ctx, CampaignState st, double dt) {
        if (st == null || !st.strikeCinematicActive) return;
        st.strikeCinematicTimer += Math.max(0.0, dt);
        double total = 3.9;
        double launchEnd = 0.65;
        double transitEnd = 2.45;
        double impactEnd = 3.2;
        if (st.strikeCinematicTimer >= total) {
            clearStrikeCinematic(st);
            if (!st.introSequenceActive) {
                st.cinematicFocusX = Double.NaN;
                st.cinematicFocusY = Double.NaN;
            }
            return;
        }

        double sourceX = Double.isFinite(st.strikeCinematicSourceX) ? st.strikeCinematicSourceX : st.playerGalaxyX;
        double sourceY = Double.isFinite(st.strikeCinematicSourceY) ? st.strikeCinematicSourceY : st.playerGalaxyY;
        double targetX = Double.isFinite(st.strikeCinematicTargetX) ? st.strikeCinematicTargetX : sourceX;
        double targetY = Double.isFinite(st.strikeCinematicTargetY) ? st.strikeCinematicTargetY : sourceY;
        if (st.strikeCinematicTimer <= launchEnd) {
            st.strikeCinematicPayloadX = sourceX;
            st.strikeCinematicPayloadY = sourceY;
            st.cinematicFocusX = sourceX;
            st.cinematicFocusY = sourceY;
            return;
        }

        double transitT = MathUtil.clamp((st.strikeCinematicTimer - launchEnd) / Math.max(1e-6, transitEnd - launchEnd), 0.0, 1.0);
        double eased = 1.0 - Math.pow(1.0 - transitT, 3.0);
        st.strikeCinematicPayloadX = sourceX + (targetX - sourceX) * eased;
        st.strikeCinematicPayloadY = sourceY + (targetY - sourceY) * eased;
        if (st.strikeCinematicTimer <= transitEnd) {
            st.cinematicFocusX = st.strikeCinematicPayloadX;
            st.cinematicFocusY = st.strikeCinematicPayloadY;
            return;
        }
        st.strikeCinematicPayloadX = targetX;
        st.strikeCinematicPayloadY = targetY;
        if (st.strikeCinematicTimer <= impactEnd) {
            st.cinematicFocusX = targetX;
            st.cinematicFocusY = targetY;
            if (ctx != null && ctx.ui != null && ((int) Math.floor((st.strikeCinematicTimer - transitEnd) * 8.0) % 2 == 0)) {
                UISystem.addPing(ctx, targetX, targetY, 0.22);
            }
            return;
        }
        st.cinematicFocusX = targetX;
        st.cinematicFocusY = targetY;
    }

    private static boolean queueStrategicStrikeObject(GameContext ctx,
                                                      CampaignState st,
                                                      StrategicStrikePayload payload,
                                                      StrategicStrikeTargetKind targetKind,
                                                      int targetId,
                                                      String targetLocationId,
                                                      String targetLabel,
                                                      double targetX,
                                                      double targetY) {
        if (ctx == null || st == null || payload == null || targetKind == null) return false;
        boolean tacticalTaskForceStrike = targetKind == StrategicStrikeTargetKind.TASK_FORCE && !isStrategicOvermapMode(st);
        if (!tacticalTaskForceStrike && !isWithinStrategicStrikeRange(ctx, st, targetX, targetY)) {
            EventSystem.showBanner(ctx, "STRIKE TARGET OUT OF RANGE  |  " + strategicRangeReadout(ctx, st, targetX, targetY), 1.4);
            return false;
        }
        double sourceX = tacticalTaskForceStrike && ctx.player != null ? ctx.player.x : st.playerGalaxyX;
        double sourceY = tacticalTaskForceStrike && ctx.player != null ? ctx.player.y : st.playerGalaxyY;
        StrategicStrikeObject strike = new StrategicStrikeObject(
                st.nextStrategicStrikeObjectId++,
                payload,
                targetKind,
                targetId,
                targetLocationId,
                targetLabel,
                Faction.PLAYER,
                sourceX,
                sourceY,
                targetX,
                targetY,
                STRATEGIC_STRIKE_OBJECT_SPEED);
        st.strategicStrikeObjects.add(strike);
        double heat = switch (payload) {
            case TORPEDO -> 6.0;
            case SORTIE -> 8.0;
            case ATOMIC -> 18.0;
        };
        st.enemyAlertLevel = MathUtil.clamp(st.enemyAlertLevel + heat, 0.0, 100.0);
        st.strategicExposureLevel = MathUtil.clamp(st.strategicExposureLevel + heat * 0.9, 0.0, 100.0);
        st.recentStrikePressure = MathUtil.clamp(st.recentStrikePressure + heat * 1.1, 0.0, 100.0);
        if (payload == StrategicStrikePayload.ATOMIC) {
            st.greenContractFavor = Math.max(0, st.greenContractFavor - 1);
            st.yellowLiberationFavor = Math.max(0, st.yellowLiberationFavor - 1);
        }
        for (GalaxySearchGroup group : st.galaxySearchGroups) {
            if (group == null || !group.hostile) continue;
            boolean direct = targetKind == StrategicStrikeTargetKind.SEARCH_GROUP && group.id == targetId;
            boolean nearby = targetKind == StrategicStrikeTargetKind.TASK_FORCE
                    || targetKind == StrategicStrikeTargetKind.CAMPAIGN_FORCE
                    || Math.hypot(group.x - targetX, group.y - targetY) <= maxStrategicSensorRange(ctx, st) * 0.45;
            if (direct || nearby) {
                group.visible = true;
                group.contactFadeSec = Math.max(group.contactFadeSec, 12.0);
                if (group.contactConfidence.ordinal() < GalaxyContactConfidence.CONFIRMED_HOSTILE.ordinal()) {
                    group.contactConfidence = GalaxyContactConfidence.CONFIRMED_HOSTILE;
                }
                if (direct) {
                    group.behavior = GalaxySearchBehavior.INVESTIGATING;
                }
            }
        }
        setLastStrikeReport(st, payload.name(), targetLabel, 0.0, false, payload == StrategicStrikePayload.ATOMIC);
        st.lastStrikeReportDetail = "Result: strike object launched  |  Impact pending  |  Heat " + pressureBandLabel(st.recentStrikePressure);
        beginStrikeCinematic(ctx, st, payload.name(), sourceX, sourceY, targetX, targetY,
                targetLabel, payload == StrategicStrikePayload.ATOMIC ? 520.0 : 220.0, 0.0,
                payload == StrategicStrikePayload.ATOMIC, false);
        EventSystem.showBanner(ctx,
                payload.name() + " STRIKE LAUNCHED  |  ETA "
                        + (int) Math.ceil(Math.hypot(targetX - strike.x, targetY - strike.y) / Math.max(1.0, strike.speed)) + "S",
                1.5);
        return true;
    }

    private static void updateStrategicStrikeObjects(GameContext ctx, CampaignState st, double dt) {
        if (ctx == null || st == null || st.strategicStrikeObjects.isEmpty()) return;
        double stepSec = Math.max(0.0, dt);
        for (Iterator<StrategicStrikeObject> it = st.strategicStrikeObjects.iterator(); it.hasNext(); ) {
            StrategicStrikeObject strike = it.next();
            if (strike == null) {
                it.remove();
                continue;
            }
            refreshStrategicStrikeTarget(st, strike);
            double dx = strike.targetX - strike.x;
            double dy = strike.targetY - strike.y;
            double dist = Math.hypot(dx, dy);
            strike.ageSec += stepSec;
            if (dist <= STRATEGIC_STRIKE_IMPACT_RADIUS || strike.ageSec > 180.0) {
                resolveStrategicStrikeObjectImpact(ctx, st, strike);
                it.remove();
                continue;
            }
            double move = Math.min(dist, strike.speed * stepSec);
            if (dist > 1e-6) {
                strike.x += dx / dist * move;
                strike.y += dy / dist * move;
            }
        }
    }

    private static void refreshStrategicStrikeTarget(CampaignState st, StrategicStrikeObject strike) {
        if (st == null || strike == null) return;
        switch (strike.targetKind) {
            case SEARCH_GROUP -> {
                GalaxySearchGroup group = galaxySearchGroupById(st, strike.targetId);
                if (group != null) {
                    strike.targetX = group.x;
                    strike.targetY = group.y;
                }
            }
            case MISSION_OUTER_THREAT -> {
                CampaignLocation location = campaignLocationById(st, strike.targetLocationId);
                if (location != null) {
                    strike.targetX = location.x;
                    strike.targetY = location.y;
                }
            }
            case TASK_FORCE -> {
                StrategicTaskForce taskForce = strategicTaskForceById(st, strike.targetId);
                // Mission task-force strikes keep the last known subzone center while the payload travels.
                if (taskForce != null && !taskForce.encounterResolved) {
                    strike.targetLabel = taskForce.label;
                }
            }
            case CAMPAIGN_FORCE -> {
                CampaignForce force = campaignForceById(st, strike.targetId);
                if (force != null && !force.destroyed) {
                    strike.targetX = forceMarkerX(force);
                    strike.targetY = forceMarkerY(force);
                    strike.targetLabel = force.name;
                }
            }
        }
    }

    private static void resolveStrategicStrikeObjectImpact(GameContext ctx, CampaignState st, StrategicStrikeObject strike) {
        if (ctx == null || st == null || strike == null) return;
        switch (strike.targetKind) {
            case SEARCH_GROUP -> resolveStrategicStrikeObjectAgainstSearchGroup(ctx, st, strike, galaxySearchGroupById(st, strike.targetId));
            case MISSION_OUTER_THREAT -> resolveStrategicStrikeObjectAgainstMissionLocation(ctx, st, strike,
                    campaignLocationById(st, strike.targetLocationId));
            case TASK_FORCE -> resolveStrategicStrikeObjectAgainstTaskForce(ctx, st, strike, strategicTaskForceById(st, strike.targetId));
            case CAMPAIGN_FORCE -> resolveStrategicStrikeObjectAgainstCampaignForce(ctx, st, strike,
                    campaignForceById(st, strike.targetId));
        }
    }

    private static void resolveStrategicStrikeObjectAgainstSearchGroup(GameContext ctx,
                                                                       CampaignState st,
                                                                       StrategicStrikeObject strike,
                                                                       GalaxySearchGroup group) {
        if (group == null || !group.hostile) {
            setLastStrikeReport(st, strike.payload.name(), strike.targetLabel, 0.0, false, strike.payload == StrategicStrikePayload.ATOMIC);
            noteStrikeBattleEvent(st, strike.payload.name(), strike.targetLabel, "Target track lost before impact");
            EventSystem.showBanner(ctx, "STRIKE ARRIVED  |  TARGET TRACK LOST", 1.3);
            return;
        }
        double damageFrac = switch (strike.payload) {
            case TORPEDO -> 0.46;
            case SORTIE -> 0.30;
            case ATOMIC -> 0.72;
        };
        double counterplay = MathUtil.clamp(group.decoyRisk * 0.34
                + (group.contactConfidence == GalaxyContactConfidence.LOST_CONTACT ? 0.30 : 0.0)
                + (group.doctrine == GalaxySearchDoctrine.BLOCKADE_GROUP ? 0.12 : 0.0)
                + (group.doctrine == GalaxySearchDoctrine.PUNISHMENT_FLEET ? 0.16 : 0.0),
                0.0,
                strike.payload == StrategicStrikePayload.ATOMIC ? 0.38 : 0.58);
        damageFrac = MathUtil.clamp(damageFrac - counterplay, strike.payload == StrategicStrikePayload.ATOMIC ? 0.24 : 0.08, 0.82);
        if (strike.payload != StrategicStrikePayload.ATOMIC
                && group.contactConfidence == GalaxyContactConfidence.LOST_CONTACT
                && group.decoyRisk >= 0.42) {
            group.trackIntegrity = MathUtil.clamp(group.trackIntegrity - 12.0, 0.0, 100.0);
            setLastStrikeReport(st, strike.payload.name(), group.label, 0.0, false, false);
            st.lastStrikeReportDetail = "Result: target lock spoofed  |  Payload missed  |  Heat " + pressureBandLabel(st.recentStrikePressure);
            noteStrikeBattleEvent(st, strike.payload.name(), group.label, "Payload missed after target lock spoofing");
            EventSystem.showBanner(ctx, strike.payload.name() + " STRIKE MISSED: TARGET SPOOFED", 1.5);
            return;
        }
        if (group.tier <= 2) damageFrac += 0.12;
        boolean broken = strike.payload == StrategicStrikePayload.ATOMIC || damageFrac >= 0.58 && group.tier <= 3;
        group.trackIntegrity = MathUtil.clamp(group.trackIntegrity - damageFrac * 62.0, 0.0, 100.0);
        group.stateTimer = Math.max(group.stateTimer, 18.0 + damageFrac * 18.0);
        group.behavior = broken ? GalaxySearchBehavior.RETURNING : GalaxySearchBehavior.INVESTIGATING;
        group.contactConfidence = broken ? GalaxyContactConfidence.LOST_CONTACT : GalaxyContactConfidence.CONFIRMED_HOSTILE;
        group.intelQuality = broken ? ContactIntelQuality.CLASSIFIED : ContactIntelQuality.IDENTIFIED;
        group.identified = false;
        group.visible = !broken;
        group.contactFadeSec = broken ? 0.0 : Math.max(group.contactFadeSec, 10.0);
        retaskGalaxySearchGroupAwayFromFleet(st, group, broken ? 2.6 : 1.8);
        applyCampaignForceStrikeDamage(st, campaignForceForLinkedSearchGroup(st, group), damageFrac, broken);
        st.enemyAlertLevel = MathUtil.clamp(st.enemyAlertLevel + (strike.payload == StrategicStrikePayload.ATOMIC ? 24.0 : 10.0), 0.0, 100.0);
        st.strategicExposureLevel = MathUtil.clamp(st.strategicExposureLevel + (strike.payload == StrategicStrikePayload.ATOMIC ? 26.0 : 9.0), 0.0, 100.0);
        st.recentStrikePressure = MathUtil.clamp(st.recentStrikePressure + (strike.payload == StrategicStrikePayload.ATOMIC ? 26.0 : 12.0), 0.0, 100.0);
        setLastStrikeReport(st, strike.payload.name(), group.label, damageFrac, broken, strike.payload == StrategicStrikePayload.ATOMIC);
        noteStrikeBattleEvent(st, strike.payload.name(), group.label,
                (broken ? "Target formation broken" : "Target formation disrupted")
                        + "; survivors and contact state updated from impact result");
        beginStrikeCinematic(ctx, st, strike.payload.name(), strike.x, strike.y, group.x, group.y,
                group.label, strike.payload == StrategicStrikePayload.ATOMIC ? 520.0 : 220.0, damageFrac,
                strike.payload == StrategicStrikePayload.ATOMIC, broken);
        EventSystem.showBanner(ctx, strike.payload.name() + " STRIKE IMPACT: " + group.label.toUpperCase(Locale.US), 1.5);
    }

    private static void resolveStrategicStrikeObjectAgainstMissionLocation(GameContext ctx,
                                                                           CampaignState st,
                                                                           StrategicStrikeObject strike,
                                                                           CampaignLocation location) {
        if (location == null || !hasMissionOuterThreat(location)) {
            setLastStrikeReport(st, strike.payload.name(), strike.targetLabel, 0.0, false, strike.payload == StrategicStrikePayload.ATOMIC);
            noteStrikeBattleEvent(st, strike.payload.name(), strike.targetLabel, "Outer screen track lost before impact");
            EventSystem.showBanner(ctx, "STRIKE ARRIVED  |  OUTER SCREEN TRACK LOST", 1.3);
            return;
        }
        launchStrategicStrikeAgainstMissionLocation(ctx, st, location, strike.payload.name());
    }

    private static void resolveStrategicStrikeObjectAgainstCampaignForce(GameContext ctx,
                                                                         CampaignState st,
                                                                         StrategicStrikeObject strike,
                                                                         CampaignForce force) {
        if (force == null || force.destroyed || force.faction != Faction.ENEMY) {
            setLastStrikeReport(st, strike.payload.name(), strike.targetLabel, 0.0, false, strike.payload == StrategicStrikePayload.ATOMIC);
            noteStrikeBattleEvent(st, strike.payload.name(), strike.targetLabel, "Campaign force contact lost before impact");
            EventSystem.showBanner(ctx, "STRIKE ARRIVED  |  FORCE CONTACT LOST", 1.3);
            return;
        }
        double before = Math.max(1.0, force.strength);
        double base = switch (strike.payload) {
            case TORPEDO -> 0.34;
            case SORTIE -> 0.24;
            case ATOMIC -> 0.62;
        };
        double lockBonus = MathUtil.clamp(force.contactConfidence * 0.16, 0.0, 0.16);
        double evasion = MathUtil.clamp(force.stealthRating / 500.0 + force.speed / 1200.0, 0.0, 0.22);
        double damageFrac = MathUtil.clamp(base + lockBonus - evasion, strike.payload == StrategicStrikePayload.ATOMIC ? 0.24 : 0.08, 0.78);
        force.strength = Math.max(0.0, force.strength - before * damageFrac);
        force.readiness = Math.max(0.0, force.readiness - 22.0 * damageFrac - (strike.payload == StrategicStrikePayload.ATOMIC ? 10.0 : 0.0));
        force.hullIntegrity = Math.max(0.0, force.hullIntegrity - 30.0 * damageFrac);
        force.supply = Math.max(0.0, force.supply - 16.0 * damageFrac);
        force.morale = Math.max(0.0, force.morale - 24.0 * damageFrac);
        force.speed = Math.max(60.0, force.speed * (strike.payload == StrategicStrikePayload.SORTIE ? 0.78 : 0.86));
        force.contactConfidence = MathUtil.clamp(Math.max(force.contactConfidence, 0.62), 0.0, 1.0);
        force.contactState = force.contactConfidence >= 0.72 ? CampaignForceContactState.KNOWN : CampaignForceContactState.SUSPECTED;
        noteCampaignForceKnownPosition(force, force.x, force.y, force.contactConfidence, Math.max(90.0, force.uncertaintyRadius * 0.55));
        boolean broken = force.strength <= 8.0 || strike.payload == StrategicStrikePayload.ATOMIC && force.strength <= 24.0;
        if (broken) {
            force.intent = CampaignForceIntent.RETREATING;
            force.state = CampaignFleetState.RETREATING;
            CampaignLocation support = nearestFriendlySupportHub(ctx, st, force.faction, force.x, force.y);
            CampaignLocation source = campaignLocationById(st, force.sourceLocationId);
            CampaignLocation fallback = support != null ? support : source;
            if (fallback != null) setCampaignForceRoute(force, force.x, force.y, fallback.x, fallback.y);
        } else if (force.readiness < 42.0 || force.morale < 38.0) {
            force.intent = CampaignForceIntent.REGROUPING;
            force.state = CampaignFleetState.RETREATING;
            double angle = Math.atan2(force.y - st.playerGalaxyY, force.x - st.playerGalaxyX);
            setCampaignForceRoute(force, force.x, force.y,
                    MathUtil.clamp(force.x + Math.cos(angle) * 520.0, 0.0, ctx.WORLD_W),
                    MathUtil.clamp(force.y + Math.sin(angle) * 520.0, 0.0, ctx.WORLD_H));
        } else {
            force.intent = CampaignForceIntent.INTERCEPTING;
            force.state = CampaignFleetState.PURSUING;
            setCampaignForceRoute(force, force.x, force.y, st.playerGalaxyX, st.playerGalaxyY);
        }
        st.enemyAlertLevel = MathUtil.clamp(st.enemyAlertLevel + (strike.payload == StrategicStrikePayload.ATOMIC ? 20.0 : 8.0), 0.0, 100.0);
        st.strategicExposureLevel = MathUtil.clamp(st.strategicExposureLevel + (strike.payload == StrategicStrikePayload.ATOMIC ? 24.0 : 8.0), 0.0, 100.0);
        st.recentStrikePressure = MathUtil.clamp(st.recentStrikePressure + (strike.payload == StrategicStrikePayload.ATOMIC ? 24.0 : 10.0), 0.0, 100.0);
        double actualDamage = MathUtil.clamp((before - force.strength) / before, 0.0, 1.0);
        setLastStrikeReport(st, strike.payload.name(), force.name, actualDamage, broken, strike.payload == StrategicStrikePayload.ATOMIC);
        st.lastStrikeReportDetail += broken
                ? "  |  Force retreating to source"
                : force.intent == CampaignForceIntent.REGROUPING
                ? "  |  Force scattered and regrouping"
                : "  |  Force hard-committed toward player";
        noteStrikeBattleEvent(st, strike.payload.name(), force.name,
                broken ? "Campaign force broken into retreat"
                        : force.intent == CampaignForceIntent.REGROUPING
                        ? "Campaign force scattered and slowed"
                        : "Campaign force damaged but hard-committed");
        beginStrikeCinematic(ctx, st, strike.payload.name(), strike.x, strike.y, force.x, force.y,
                force.name, strike.payload == StrategicStrikePayload.ATOMIC ? 520.0 : 220.0, actualDamage,
                strike.payload == StrategicStrikePayload.ATOMIC, broken);
        EventSystem.showBanner(ctx, strike.payload.name() + " STRIKE IMPACT: " + force.name.toUpperCase(Locale.US), 1.5);
    }

    private static void resolveStrategicStrikeObjectAgainstTaskForce(GameContext ctx,
                                                                     CampaignState st,
                                                                     StrategicStrikeObject strike,
                                                                     StrategicTaskForce taskForce) {
        if (taskForce == null || taskForce.encounterResolved) {
            setLastStrikeReport(st, strike.payload.name(), strike.targetLabel, 0.0, false, strike.payload == StrategicStrikePayload.ATOMIC);
            noteStrikeBattleEvent(st, strike.payload.name(), strike.targetLabel, "Task force dispersed before impact");
            EventSystem.showBanner(ctx, "STRIKE ARRIVED  |  TASK FORCE DISPERSED", 1.3);
            return;
        }
        double before = taskForce.currentStrength;
        StrategicCountermeasureProfile countermeasure = strategicCountermeasureProfile(ctx, st, taskForce);
        double reconQuality = strategicReconQualityAgainstTaskForce(ctx, st, taskForce);
        double base = switch (strike.payload) {
            case TORPEDO -> 0.36;
            case SORTIE -> 0.24;
            case ATOMIC -> 0.62;
        };
        double damageFrac = MathUtil.clamp(base + reconQuality * 0.16 - countermeasure.interception * 0.18 - countermeasure.evasion * 0.16, 0.08, 0.78);
        taskForce.currentStrength = Math.max(0.0, taskForce.currentStrength - taskForce.maxStrength * damageFrac);
        taskForce.disruptionRemainingSec = Math.max(taskForce.disruptionRemainingSec, strike.payload == StrategicStrikePayload.ATOMIC ? 34.0 : 18.0);
        if (strike.payload == StrategicStrikePayload.TORPEDO) taskForce.torpedoStrikesSustained++;
        if (strike.payload == StrategicStrikePayload.SORTIE) taskForce.sortieStrikesSustained++;
        boolean broken = taskForce.currentStrength <= 1.0;
        if (broken) {
            taskForce.currentStrength = 0.0;
            taskForce.encounterResolved = true;
            taskForce.encounterSpawned = false;
            taskForce.spawnedShipIds.clear();
        }
        applyLongRangeStrikeConsequences(ctx, st, taskForce, strike.payload.name(), reconQuality, countermeasure,
                strike.payload == StrategicStrikePayload.ATOMIC);
        setLastStrikeReport(st, strike.payload.name(), taskForce.label,
                (before <= 1e-6) ? 0.0 : ((before - taskForce.currentStrength) / before),
                broken,
                strike.payload == StrategicStrikePayload.ATOMIC);
        noteStrikeBattleEvent(st, strike.payload.name(), taskForce.label,
                (broken ? "Task force broken" : "Task force damaged and disrupted")
                        + "; campaign strength, survivors, morale pressure, and contact state resolved");
        beginStrikeCinematic(ctx, st, strike.payload.name(), strike.x, strike.y, strike.targetX, strike.targetY,
                taskForce.label, strike.payload == StrategicStrikePayload.ATOMIC ? 540.0 : 220.0, damageFrac,
                strike.payload == StrategicStrikePayload.ATOMIC, broken);
        resolveStrategicTaskForceAfterRemoteStrike(ctx, st, taskForce, strike.payload.name() + " STRIKE IMPACT");
    }

    public static boolean launchStrategicTorpedoStrike(GameContext ctx, double worldX, double worldY) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !st.enabled) return false;
        GalaxySearchGroup preferredGroup = preferredSelectedHostileSearchGroupForStrike(ctx, st, worldX, worldY, 520.0, ContactIntelQuality.TRACKED);
        GalaxySearchGroup nearbyGroup = nearestHostileGalaxySearchGroup(st, worldX, worldY, 420.0);
        GalaxySearchGroup strikeGroup = (preferredGroup != null) ? preferredGroup
                : (canLaunchImmediateStrikeOnSearchGroup(nearbyGroup, ContactIntelQuality.TRACKED, worldX, worldY) ? nearbyGroup : null);
        StrategicTaskForce taskForce = nearestHostileStrategicTaskForce(ctx, worldX, worldY, 240.0);
        CampaignLocation missionLocation = nearestMissionOuterThreatLocation(st, worldX, worldY, 240.0);
        CampaignForce campaignForce = nearestStrikeableCampaignForce(st, worldX, worldY, 420.0);
        if (st.strategicTorpedoCharges <= 0) {
            EventSystem.showBanner(ctx, "NO TORPEDO STRIKES READY", 1.2);
            return true;
        }
        StrikeCost cost = strikeCost(ctx, st, "TORPEDO_STRIKE", strategicStrikeCostIntelLabel(ctx), false);
        int ammoCost = cost.ammo;
        int fuelCost = cost.fuel;
        if (st.campaignAmmo < ammoCost || st.campaignFuel < fuelCost) {
            EventSystem.showBanner(ctx, "TORPEDO STRIKE REQUIRES AMMO AND FUEL", 1.2);
            return true;
        }
        if (strikeGroup != null) {
            if (isStrategicOvermapMode(st) && !isWithinStrategicStrikeRange(ctx, st, strikeGroup.x, strikeGroup.y)) {
                EventSystem.showBanner(ctx, "TORPEDO TARGET OUT OF RANGE  |  " + strategicRangeReadout(ctx, st, strikeGroup.x, strikeGroup.y), 1.3);
                return true;
            }
            st.strategicTorpedoCharges--;
            st.campaignAmmo = Math.max(0, st.campaignAmmo - ammoCost);
            st.campaignFuel = Math.max(0, st.campaignFuel - fuelCost);
            return queueStrategicStrikeObject(ctx, st, StrategicStrikePayload.TORPEDO,
                    StrategicStrikeTargetKind.SEARCH_GROUP, strikeGroup.id, "", hostileSearchGroupDisplayName(st, strikeGroup),
                    strikeGroup.x, strikeGroup.y);
        }
        if (campaignForce != null) {
            double tx = forceMarkerX(campaignForce);
            double ty = forceMarkerY(campaignForce);
            if (isStrategicOvermapMode(st) && !isWithinStrategicStrikeRange(ctx, st, tx, ty)) {
                EventSystem.showBanner(ctx, "TORPEDO TARGET OUT OF RANGE  |  " + strategicRangeReadout(ctx, st, tx, ty), 1.3);
                return true;
            }
            st.strategicTorpedoCharges--;
            st.campaignAmmo = Math.max(0, st.campaignAmmo - ammoCost);
            st.campaignFuel = Math.max(0, st.campaignFuel - fuelCost);
            return queueStrategicStrikeObject(ctx, st, StrategicStrikePayload.TORPEDO,
                    StrategicStrikeTargetKind.CAMPAIGN_FORCE, campaignForce.id, "", campaignForce.name,
                    tx, ty);
        }
        if (missionLocation != null) {
            if (!isWithinStrategicStrikeRange(ctx, st, missionLocation.x, missionLocation.y)) {
                EventSystem.showBanner(ctx, "TORPEDO TARGET OUT OF RANGE  |  " + strategicRangeReadout(ctx, st, missionLocation.x, missionLocation.y), 1.3);
                return true;
            }
            st.strategicTorpedoCharges--;
            st.campaignAmmo = Math.max(0, st.campaignAmmo - ammoCost);
            st.campaignFuel = Math.max(0, st.campaignFuel - fuelCost);
            return queueStrategicStrikeObject(ctx, st, StrategicStrikePayload.TORPEDO,
                    StrategicStrikeTargetKind.MISSION_OUTER_THREAT, 0, missionLocation.id, missionLocation.name,
                    missionLocation.x, missionLocation.y);
        }
        if (taskForce == null) {
            st.strategicTorpedoCharges--;
            st.campaignAmmo = Math.max(0, st.campaignAmmo - ammoCost);
            st.campaignFuel = Math.max(0, st.campaignFuel - fuelCost);
            boolean result = launchStrategicStrikeAgainstSearchGroup(ctx, st, worldX, worldY, "TORPEDO");
            if (!result) {
                st.strategicTorpedoCharges++;
                st.campaignAmmo += ammoCost;
                st.campaignFuel += fuelCost;
            }
            return result;
        }
        if (taskForce.encounterSpawned) {
            EventSystem.showBanner(ctx, "CONTACT ALREADY IN TACTICAL COMBAT", 1.2);
            return true;
        }
        if (isStrategicOvermapMode(st) && !isWithinStrategicStrikeRange(ctx, st, worldX, worldY)) {
            EventSystem.showBanner(ctx, "TORPEDO TARGET OUT OF RANGE  |  " + strategicRangeReadout(ctx, st, worldX, worldY), 1.3);
            return true;
        }
        st.strategicTorpedoCharges--;
        st.campaignAmmo = Math.max(0, st.campaignAmmo - ammoCost);
        st.campaignFuel = Math.max(0, st.campaignFuel - fuelCost);
        return queueStrategicStrikeObject(ctx, st, StrategicStrikePayload.TORPEDO,
                StrategicStrikeTargetKind.TASK_FORCE, taskForce.id, "", taskForce.label,
                worldX, worldY);
    }

    public static boolean launchStrategicSortie(GameContext ctx, double worldX, double worldY) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !st.enabled) return false;
        GalaxySearchGroup preferredGroup = preferredSelectedHostileSearchGroupForStrike(ctx, st, worldX, worldY, 520.0, ContactIntelQuality.TRACKED);
        GalaxySearchGroup nearbyGroup = nearestHostileGalaxySearchGroup(st, worldX, worldY, 420.0);
        GalaxySearchGroup strikeGroup = (preferredGroup != null) ? preferredGroup
                : (canLaunchImmediateStrikeOnSearchGroup(nearbyGroup, ContactIntelQuality.TRACKED, worldX, worldY) ? nearbyGroup : null);
        StrategicTaskForce taskForce = nearestHostileStrategicTaskForce(ctx, worldX, worldY, 240.0);
        CampaignLocation missionLocation = nearestMissionOuterThreatLocation(st, worldX, worldY, 240.0);
        CampaignForce campaignForce = nearestStrikeableCampaignForce(st, worldX, worldY, 420.0);
        int sortieCap = strategicSortieCapacity(ctx);
        if (sortieCap <= 0) {
            EventSystem.showBanner(ctx, "NO CARRIER SORTIES AVAILABLE", 1.2);
            return true;
        }
        if (st.strategicSortiesLaunched >= sortieCap) {
            EventSystem.showBanner(ctx, "SORTIE DECKS COMMITTED", 1.2);
            return true;
        }
        StrikeCost cost = strikeCost(ctx, st, "CARRIER_SORTIE", strategicStrikeCostIntelLabel(ctx), false);
        int ammoCost = cost.ammo;
        int fuelCost = cost.fuel;
        int supplyCost = cost.supplies;
        if (st.campaignAmmo < ammoCost || st.campaignFuel < fuelCost || st.campaignSupplies < supplyCost) {
            EventSystem.showBanner(ctx, "SORTIE STRIKE REQUIRES FUEL, AMMO, AND SUPPLIES", 1.2);
            return true;
        }
        if (strikeGroup != null) {
            if (isStrategicOvermapMode(st) && !isWithinStrategicStrikeRange(ctx, st, strikeGroup.x, strikeGroup.y)) {
                EventSystem.showBanner(ctx, "SORTIE TARGET OUT OF RANGE  |  " + strategicRangeReadout(ctx, st, strikeGroup.x, strikeGroup.y), 1.3);
                return true;
            }
            st.strategicSortiesLaunched++;
            st.campaignAmmo = Math.max(0, st.campaignAmmo - ammoCost);
            st.campaignFuel = Math.max(0, st.campaignFuel - fuelCost);
            st.campaignSupplies = Math.max(0, st.campaignSupplies - supplyCost);
            return queueStrategicStrikeObject(ctx, st, StrategicStrikePayload.SORTIE,
                    StrategicStrikeTargetKind.SEARCH_GROUP, strikeGroup.id, "", hostileSearchGroupDisplayName(st, strikeGroup),
                    strikeGroup.x, strikeGroup.y);
        }
        if (campaignForce != null) {
            double tx = forceMarkerX(campaignForce);
            double ty = forceMarkerY(campaignForce);
            if (isStrategicOvermapMode(st) && !isWithinStrategicStrikeRange(ctx, st, tx, ty)) {
                EventSystem.showBanner(ctx, "SORTIE TARGET OUT OF RANGE  |  " + strategicRangeReadout(ctx, st, tx, ty), 1.3);
                return true;
            }
            st.strategicSortiesLaunched++;
            st.campaignAmmo = Math.max(0, st.campaignAmmo - ammoCost);
            st.campaignFuel = Math.max(0, st.campaignFuel - fuelCost);
            st.campaignSupplies = Math.max(0, st.campaignSupplies - supplyCost);
            return queueStrategicStrikeObject(ctx, st, StrategicStrikePayload.SORTIE,
                    StrategicStrikeTargetKind.CAMPAIGN_FORCE, campaignForce.id, "", campaignForce.name,
                    tx, ty);
        }
        if (missionLocation != null) {
            if (!isWithinStrategicStrikeRange(ctx, st, missionLocation.x, missionLocation.y)) {
                EventSystem.showBanner(ctx, "SORTIE TARGET OUT OF RANGE  |  " + strategicRangeReadout(ctx, st, missionLocation.x, missionLocation.y), 1.3);
                return true;
            }
            st.strategicSortiesLaunched++;
            st.campaignAmmo = Math.max(0, st.campaignAmmo - ammoCost);
            st.campaignFuel = Math.max(0, st.campaignFuel - fuelCost);
            st.campaignSupplies = Math.max(0, st.campaignSupplies - supplyCost);
            return queueStrategicStrikeObject(ctx, st, StrategicStrikePayload.SORTIE,
                    StrategicStrikeTargetKind.MISSION_OUTER_THREAT, 0, missionLocation.id, missionLocation.name,
                    missionLocation.x, missionLocation.y);
        }
        if (taskForce == null) {
            st.strategicSortiesLaunched++;
            st.campaignAmmo = Math.max(0, st.campaignAmmo - ammoCost);
            st.campaignFuel = Math.max(0, st.campaignFuel - fuelCost);
            st.campaignSupplies = Math.max(0, st.campaignSupplies - supplyCost);
            boolean result = launchStrategicStrikeAgainstSearchGroup(ctx, st, worldX, worldY, "SORTIE");
            if (!result) {
                st.strategicSortiesLaunched = Math.max(0, st.strategicSortiesLaunched - 1);
                st.campaignAmmo += ammoCost;
                st.campaignFuel += fuelCost;
                st.campaignSupplies += supplyCost;
            }
            return result;
        }
        if (taskForce.encounterSpawned) {
            EventSystem.showBanner(ctx, "CONTACT ALREADY IN TACTICAL COMBAT", 1.2);
            return true;
        }
        if (isStrategicOvermapMode(st) && !isWithinStrategicStrikeRange(ctx, st, worldX, worldY)) {
            EventSystem.showBanner(ctx, "SORTIE TARGET OUT OF RANGE  |  " + strategicRangeReadout(ctx, st, worldX, worldY), 1.3);
            return true;
        }
        st.strategicSortiesLaunched++;
        st.campaignAmmo = Math.max(0, st.campaignAmmo - ammoCost);
        st.campaignFuel = Math.max(0, st.campaignFuel - fuelCost);
        st.campaignSupplies = Math.max(0, st.campaignSupplies - supplyCost);
        return queueStrategicStrikeObject(ctx, st, StrategicStrikePayload.SORTIE,
                StrategicStrikeTargetKind.TASK_FORCE, taskForce.id, "", taskForce.label,
                worldX, worldY);
    }

